var CTAI_BLITZ=[{q:'The term \'AI Effect\' refers to the changing perception of what constitutes AI as society and technology advance.',a:'True'},{q:'The modern definition of AI is the same today as it was in the 1950s.',a:'False'},{q:'Deep Blue\'s chess-playing system is now widely considered true artificial intelligence because it beat the world champion.',a:'False'},{q:'Narrow AI systems are designed to perform a specific task with limited context.',a:'True'},{q:'As of 2021, general AI systems with human-like cognitive abilities across all domains have been realized.',a:'False'},{q:'Super AI systems are expected to quickly become wiser than humans once they reach the technological singularity.',a:'True'},{q:'In a conventional system, it is relatively easy for humans to understand how inputs are transformed into outputs.',a:'True'},{q:'AI-based systems using machine learning use explicit if-then-else rules to determine behaviour.',a:'False'},{q:'Fuzzy logic and decision trees are both listed as AI technologies.',a:'True'},{q:'TensorFlow is an open-source ML framework provided by Google.',a:'True'},{q:'PyTorch is an open-source ML library operated by Microsoft.',a:'False'},{q:'GPUs typically outperform CPUs for ML tasks because they have thousands of cores suited to massively parallel processing.',a:'True'},{q:'General-purpose CPUs are the best hardware choice for training large ML models.',a:'False'},{q:'ASICs designed for AI are most suitable for edge computing where the trained model runs on individual devices.',a:'True'},{q:'AIaaS SLAs typically define ML functional performance metrics such as accuracy in the same way they define uptime.',a:'False'},{q:'AIaaS allows organisations to implement AI using cloud services even without sufficient in-house resources.',a:'True'},{q:'A pre-trained model can be embedded in an AI-based system without modification.',a:'True'},{q:'Transfer learning takes a pre-trained model and modifies it to perform a different requirement.',a:'True'},{q:'In transfer learning, the later layers of a neural network are typically reused unchanged while early layers are retrained.',a:'False'},{q:'A risk of pre-trained models is that inherited biases may not be apparent if documentation about training data is lacking.',a:'True'},{q:'Models created through transfer learning are unlikely to share the same vulnerabilities as the original pre-trained model.',a:'False'},{q:'The GDPR requires that every single prediction made by an AI system must be accurate.',a:'False'},{q:'ISO/IEC JTC 1/SC42, a subcommittee on AI, was set up in 2017.',a:'True'},{q:'ISO 26262 is a regulatory standard applicable to automotive systems.',a:'True'},{q:'Standards in isolation are mandatory for all organizations developing AI systems.',a:'False'},{q:'Keras is a high-level Python API capable of running on top of TensorFlow and CNTK.',a:'True'},{q:'Neuromorphic processors use the traditional von Neumann architecture.',a:'False'},{q:'A hybrid AIaaS approach combines AI functionality provided internally with some provided as an external service.',a:'True'},{q:'The ImageNet dataset contains over 14 million images classified into over 1000 categories.',a:'True'},{q:'Several of the risks of pre-trained models can be mitigated by thorough documentation of the model.',a:'True'},{q:'Flexibility is the ability of the system to be used in situations not part of the original requirements.',a:'True'},{q:'Adaptability and flexibility are identical concepts with no distinction in the CT-AI syllabus.',a:'False'},{q:'In the CT-AI syllabus, autonomy means the system works independently of human oversight for prolonged periods.',a:'True'},{q:'Fully autonomous systems are the desired goal for all AI-based systems.',a:'False'},{q:'Evolution in AI systems is the ability to improve in response to changing external constraints.',a:'True'},{q:'Sample bias occurs when the training data is not fully representative of the operational data space.',a:'True'},{q:'Algorithmic bias can be managed by hyperparameter tuning of the ML algorithm.',a:'True'},{q:'Inappropriate bias in AI systems has been reported in bank lending and recruitment systems.',a:'True'},{q:'Reward hacking occurs when the system achieves its goal through a solution that perverts the designer\'s intent.',a:'True'},{q:'Negative side effects occur when the system fails to achieve its specified goal.',a:'False'},{q:'Transparency in XAI refers to how easily users can determine how the system arrives at a result.',a:'False'},{q:'Explainability in XAI refers to the ease with which users can determine how the AI system arrives at a result.',a:'True'},{q:'Self-learning AI systems must be adaptable and flexible by nature.',a:'True'},{q:'Complexity and non-determinism are characteristics that make it harder to ensure AI systems are safe.',a:'True'},{q:'The OECD AI principles, issued in 2019, were the first international AI standards agreed by governments.',a:'True'},{q:'In supervised learning, the algorithm creates the model from labelled data.',a:'True'},{q:'Classification is used when the output is a continuous numeric value.',a:'False'},{q:'Regression in ML predicts a numeric output — this is the same usage as \'regression testing\' in ISTQB testing syllabi.',a:'False'},{q:'In unsupervised learning, the algorithm creates the model from unlabelled data.',a:'True'},{q:'Clustering groups data based on similarities without prior labels.',a:'True'},{q:'Association identifies interesting relationships or dependencies among data attributes.',a:'True'},{q:'Reinforcement learning uses labelled training data to learn correct behaviour.',a:'False'},{q:'Robotics and chatbots are typical applications of reinforcement learning.',a:'True'},{q:'The first step in the ML workflow is to train the model.',a:'False'},{q:'Model hyperparameters define the model structure, such as the number of layers in a neural network.',a:'True'},{q:'Algorithm hyperparameters control the training process, such as the number of epochs.',a:'True'},{q:'The ML workflow is strictly sequential and steps are never repeated in practice.',a:'False'},{q:'Overfitting produces a model that performs well on training data but poorly on new data.',a:'True'},{q:'Underfitting occurs when the model is too complex and memorises noise in the training data.',a:'False'},{q:'If the output of a problem is numeric and continuous, regression is likely the appropriate ML approach.',a:'True'},{q:'Reinforcement learning is best suited to contexts involving interaction with an environment and decisions at multiple states.',a:'True'},{q:'There is always one optimal ML algorithm for a given problem.',a:'False'},{q:'After deployment, a model should be monitored and tuned to address concept drift.',a:'True'},{q:'The ML workflow diagram includes a \'Monitor and Tune the Model\' step after deployment.',a:'True'},{q:'A/B testing can be used to compare an updated model against the previous version during the monitor phase.',a:'True'},{q:'Data preparation uses an average of 43% of the ML workflow effort.',a:'True'},{q:'Model selection and building uses more effort than data preparation in a typical ML project.',a:'False'},{q:'Data augmentation increases the number of samples in a dataset and can help provide robustness against adversarial attacks.',a:'True'},{q:'Feature selection removes irrelevant features, which can reduce training time and prevent overfitting.',a:'True'},{q:'Feature extraction creates new informative features from existing ones, typically resulting in a smaller dataset.',a:'True'},{q:'EDA uses data analysis and visualisation to discover trends in the data.',a:'True'},{q:'Three datasets are logically required: training, validation, and test.',a:'True'},{q:'The test (holdout) dataset is used during model evaluation and tuning.',a:'False'},{q:'A typical training:validation:test split guideline ranges from 60:20:20 to 80:10:10.',a:'True'},{q:'K-fold cross validation is used when there is limited data available.',a:'True'},{q:'Wrong data means the captured data was incorrect, for example due to a faulty sensor.',a:'True'},{q:'Unbalanced data can result from inappropriate bias such as race or gender bias in data collection.',a:'True'},{q:'Duplicate data records can unduly influence the resultant ML model.',a:'True'},{q:'Poor data quality can result in a compromised model with security vulnerabilities.',a:'True'},{q:'Data labelling is a minor activity that uses around 5% of time on ML projects.',a:'False'},{q:'Annotation refers to labelling objects in images, for example by drawing rectangles around them.',a:'True'},{q:'In crowdsourced labelling, multiple annotators may label the same data to manage quality.',a:'True'},{q:'AI-Assisted labelling requires no human review of the results.',a:'False'},{q:'Mislabelled data can result from random errors, systemic errors, deliberate errors, or translation errors.',a:'True'},{q:'Supervised learning assumes all data in the dataset is always correctly labelled in practice.',a:'False'},{q:'A False Positive is when the model predicts positive but the actual value is negative.',a:'True'},{q:'A False Negative is when the model predicts negative but the actual value is positive.',a:'True'},{q:'Accuracy measures the percentage of all correct classifications.',a:'True'},{q:'Precision measures the proportion of actual positives that were predicted correctly.',a:'False'},{q:'Recall (sensitivity) measures the proportion of actual positives that were predicted correctly.',a:'True'},{q:'The F1-score is the arithmetic mean of precision and recall.',a:'False'},{q:'A high F1-score (close to 1) indicates that false data has little influence on the result.',a:'True'},{q:'The ROC curve plots true positive rate against false positive rate.',a:'True'},{q:'A higher AUC value means the model\'s predictions are better.',a:'True'},{q:'MSE is used for supervised regression models and a value closer to zero is better.',a:'True'},{q:'The silhouette coefficient of -1 means clusters are well-separated.',a:'False'},{q:'Intra-cluster metrics measure the similarity of data points within a cluster.',a:'True'},{q:'ML functional performance metrics also measure non-functional quality characteristics such as performance efficiency.',a:'False'},{q:'Accuracy is a poor metric when one class of data dominates the dataset.',a:'True'},{q:'Precision should be prioritised when the cost of false positives is high.',a:'True'},{q:'Recall should be prioritised when it is critical that no actual positives are missed.',a:'True'},{q:'F1-score is most useful when the dataset is perfectly balanced and precision and recall are equally important.',a:'False'},{q:'ML benchmark suites provide objective comparisons between different AI technologies and hardware platforms.',a:'True'},{q:'ML functional performance metrics evaluate the entire system including the data pipeline.',a:'False'},{q:'AUC for the ROC curve is applicable to supervised classification problems.',a:'True'},{q:'Artificial neural networks were initially designed to mimic the functioning of the human brain.',a:'True'},{q:'A deep neural network has only an input layer and an output layer with no hidden layers.',a:'False'},{q:'The activation value of a neuron is calculated using an activation function, connection weights, and the neuron\'s bias.',a:'True'},{q:'During training, connection weights are adjusted to minimise the difference between actual and expected outputs.',a:'True'},{q:'Traditional white-box code coverage (e.g., statement coverage) is highly effective for testing neural networks.',a:'False'},{q:'Neuron coverage requires each neuron to achieve an activation value greater than zero.',a:'True'},{q:'Threshold coverage is stricter than basic neuron coverage as it requires activation values to exceed a specified threshold.',a:'True'},{q:'Sign-Change coverage requires test cases to cause each neuron to achieve both positive and negative activation values.',a:'True'},{q:'Sign-Sign coverage is conceptually similar to MC/DC coverage for imperative source code.',a:'True'},{q:'Neural network coverage is a mature research area with extensive objective evidence of effectiveness available since the 1970s.',a:'False'},{q:'AI-based system specifications are typically easier to define than conventional system specifications.',a:'False'},{q:'Two new specialised test levels for AI-based systems are input data testing and ML model testing.',a:'True'},{q:'The objective of input data testing is to ensure data used for training and prediction is of the highest quality.',a:'True'},{q:'ML model testing evaluates the model against agreed ML functional performance criteria.',a:'True'},{q:'Component integration testing for AI systems checks that inputs from the data pipeline are received correctly by the model.',a:'True'},{q:'During system testing, ML functional performance criteria do not need to be re-tested.',a:'False'},{q:'Where AI is provided as a service, API testing is normally performed as part of component integration testing.',a:'True'},{q:'Big data (high-volume, high-velocity, high-variety) can be difficult to create and manage as test data.',a:'True'},{q:'Automation bias means humans are always more accurate when assisted by AI recommendations.',a:'False'},{q:'The second form of automation bias is where the human misses a system failure by not adequately monitoring the system.',a:'True'},{q:'AI component documentation should include details on known bias, ethical issues, and concept drift.',a:'True'},{q:'Concept drift causes model outputs to become increasingly less accurate as the operational environment changes.',a:'True'},{q:'Systems prone to concept drift should only be tested once a year.',a:'False'},{q:'After retraining to address concept drift, the new model may be compared to the old one using A/B testing.',a:'True'},{q:'The test approach for an ML system is based on a risk analysis including both conventional and AI-specific testing.',a:'True'},{q:'Overfitting in a deployed model may be detected by testing with a dataset completely independent from the training data.',a:'True'},{q:'Acceptance testing for AIaaS may be needed to determine whether ML functional performance criteria are sufficiently met.',a:'True'},{q:'When testers use the same data pipeline implementation as data scientists, defects in that pipeline may be masked.',a:'True'},{q:'The probabilistic nature of many AI systems makes it necessary to specify tolerances in quality requirements.',a:'True'},{q:'Quality characteristics such as adaptability and autonomy are easy to define and test due to established standards.',a:'False'},{q:'A self-learning system may change its behaviour in ways that make previously passing tests fail.',a:'True'},{q:'Testing self-learning systems may require automated continuous testing because changes can happen faster than manual execution.',a:'True'},{q:'Testing autonomous systems requires creating conditions for the system to exercise its decision-making about human intervention.',a:'True'},{q:'Boundary value analysis applied to the operating environment can help generate conditions for autonomy testing.',a:'True'},{q:'The LIME method provides a definitive reason for every model output.',a:'False'},{q:'Transparency can be tested by comparing documented information on data and algorithm to the actual implementation.',a:'True'},{q:'Testing interpretability and explainability typically uses user surveys and questionnaires.',a:'True'},{q:'Probabilistic and non-deterministic AI systems always produce the same result for the same inputs.',a:'False'},{q:'When testing probabilistic systems, running a test several times helps generate a statistically valid result.',a:'True'},{q:'A test oracle is the source used to determine the expected result of a test.',a:'True'},{q:'The test oracle problem is straightforward to solve for complex, non-deterministic AI systems.',a:'False'},{q:'A/B testing, back-to-back testing, and metamorphic testing can all help alleviate the test oracle problem.',a:'True'},{q:'Human experts used as test oracles always agree with each other when presented with the same information.',a:'False'},{q:'Testing for sample bias may include reviewing the source and pre-processing of training data.',a:'True'},{q:'ML systems can create unwanted bias using combinations of seemingly unrelated features.',a:'True'},{q:'For the \'Evolution\' quality characteristic, tests should check how well the system copes with concept drift.',a:'True'},{q:'For \'Reward Hacking\', independent tests should use the same success measure as the intelligent agent being tested.',a:'False'},{q:'Safety testing of AI systems may need to be carried out in a virtual test environment.',a:'True'},{q:'Repeating the same tests on a self-learning system may cause it to adapt, influencing its long-term behaviour.',a:'True'},{q:'The complexity of AI-based systems increases when multiple components each provide probabilistic results.',a:'True'},{q:'When an AI system is tested as a black box, the visible internal structure provides useful additional testing information.',a:'False'},{q:'Acceptance criteria for probabilistic systems can always be evaluated with precise, exact values.',a:'False'},{q:'Insufficient specification of the operational environment is a key challenge when testing self-learning systems.',a:'True'},{q:'For \'Freedom from inappropriate bias\', comparing test results with census data can check for bias on inferred variables.',a:'True'},{q:'Checking ethics of an AI system can involve using the EC Assessment List for Trustworthy AI as a checklist.',a:'True'},{q:'An adversarial attack involves subtly perturbing valid inputs to cause the model to produce incorrect predictions.',a:'True'},{q:'Adversarial examples were first noticed with image classifiers.',a:'False'},{q:'Adversarial examples are generally transferable between ML systems trained for the same task.',a:'True'},{q:'In a white-box adversarial attack, the attacker has full knowledge of the algorithm, settings, and parameters.',a:'True'},{q:'In a black-box adversarial attack, the attacker builds a duplicate model and uses white-box techniques on it.',a:'True'},{q:'Adversarial testing aims to identify vulnerabilities so preventative measures can be taken.',a:'True'},{q:'Data poisoning attacks only target the trained model, not the training data.',a:'False'},{q:'The Microsoft Tay chatbot is a well-known example of a data poisoning attack.',a:'True'},{q:'EDA can help detect data poisoning because poisoned data may appear as outliers.',a:'True'},{q:'Pairwise testing tests every possible combination of parameter values.',a:'False'},{q:'Pairwise testing significantly reduces the number of test cases needed while maintaining defect detection capability.',a:'True'},{q:'Back-to-back testing uses an alternative version of the system as a pseudo-oracle to compare outputs.',a:'True'},{q:'For pseudo-oracles to be effective, the pseudo-oracle and SUT should share as much code as possible.',a:'False'},{q:'A/B testing compares two variants of a system to determine which performs better.',a:'True'},{q:'A/B testing generates detailed test cases and provides guidance on how tests should be designed.',a:'False'},{q:'A/B testing can be used to test self-learning systems by comparing system characteristics before and after a change.',a:'True'},{q:'Metamorphic testing generates follow-up test cases based on a metamorphic relation applied to a source test case.',a:'True'},{q:'In metamorphic testing, the expected results of follow-up test cases are always identical to the source test case.',a:'False'},{q:'Research shows that three to six diverse metamorphic relations can reveal over 90% of detectable defects.',a:'True'},{q:'Metamorphic testing requires commercial tool support and is not yet applicable manually.',a:'False'},{q:'Exploratory testing is especially useful for AI-based systems due to poor specifications and test oracle problems.',a:'True'},{q:'A tour in exploratory testing is a set of strategies and goals organised around a special focus.',a:'True'},{q:'EDA involves interactive, hypothesis-driven exploration of data for patterns, trends, and outliers.',a:'True'},{q:'Adversarial testing is appropriate when mishandling adversarial examples could have significant impact.',a:'True'},{q:'Back-to-back testing compares two variants of the same system to choose the better one.',a:'False'},{q:'Virtual test environments allow dangerous scenarios to be tested without endangering people or the environment.',a:'True'},{q:'Virtual test environments can only be run one at a time, not in parallel.',a:'False'},{q:'Virtual test environments provide better observability because all digital parts of the environment can be monitored.',a:'True'},{q:'Big data requirements in AI test environments need careful planning to set up correctly.',a:'True'},{q:'AI-specific hardware such as AI-specific processors never needs to be included in the test environment.',a:'False'},{q:'AI can support defect triage by using NLP and clustering algorithms to categorise and identify duplicate defects.',a:'True'},{q:'AI-based test case generation always solves the test oracle problem automatically.',a:'False'},{q:'AI-based optimisation of regression test suites can reduce suite size by around 50% while still detecting most defects.',a:'True'},{q:'Defect prediction using ML is most effective when based on prior experience with a similar codebase or developers.',a:'True'},{q:'The best predictors for defect prediction have been found to be source code metrics such as lines of code.',a:'False'},{q:'Visual testing uses image recognition to interact with GUI objects through the same interface as an actual user.',a:'True'},{q:'AI-based GUI tools can check that the user interface works correctly across different browsers and platforms.',a:'True'},{q:'Specifying test oracles and challenging stakeholder assumptions are currently practical AI testing tasks.',a:'False'},{q:'AI can assist in optimising regression test suites by analysing previous test results and recent code changes.',a:'True'},{q:'A distinction should be drawn between narrow AI and general AI when discussing what AI can do for testing today.',a:'True'}];
var GENAI_BLITZ=[{q:'GenAI is a branch of AI that uses large pre-trained models to generate human-like output such as text, images, or code.',a:'True'},{q:'Symbolic AI uses neural networks to automatically learn features from large datasets.',a:'False'},{q:'LLMs are trained on very large textual datasets including books, articles, and websites.',a:'True'},{q:'Tokenization breaks text into smaller units called tokens, which can range from a character to a sub-word or word.',a:'True'},{q:'Embeddings are plain text representations of tokens stored in relational databases.',a:'False'},{q:'The transformer model predicts the next token in a sequence to generate coherent text.',a:'True'},{q:'LLMs always produce the same output when given identical input, making them fully deterministic.',a:'False'},{q:'A larger context window always reduces computational complexity.',a:'False'},{q:'Foundation LLMs are general-purpose models that typically require further adaptation for specific tasks.',a:'True'},{q:'Instruction-tuned LLMs are fine-tuned using datasets that pair prompts with expected responses.',a:'True'},{q:'Reasoning LLMs focus on logical inference, multi-step problem-solving, and chain-of-thought reasoning.',a:'True'},{q:'Multimodal LLMs can only process text input.',a:'False'},{q:'Vision-language models are a subset of multimodal LLMs that integrate visual and textual information.',a:'True'},{q:'Classical machine learning requires manual feature selection and model training.',a:'True'},{q:'GenAI models require an additional training phase before they can be applied to test tasks.',a:'False'},{q:'LLMs can support test tasks such as generating test cases, analyzing defect patterns, and producing synthetic test data.',a:'True'},{q:'Small language models (SLMs) have more parameters than LLMs.',a:'False'},{q:'Tokens with similar meanings have embeddings positioned closely together in high-dimensional space.',a:'True'},{q:'AI chatbots and LLM-powered applications are two ways testers can leverage GenAI.',a:'True'},{q:'Deep learning requires users to manually define all features before training.',a:'False'},{q:'A structured prompt for software testing typically includes six components: role, context, instruction, input data, constraints, and output format.',a:'True'},{q:'The \'role\' component of a prompt defines the expected output format of the LLM response.',a:'False'},{q:'Context in a prompt provides background information about the test object and specific functionality to be tested.',a:'True'},{q:'Constraints outline any restrictions or special considerations the LLM should adhere to.',a:'True'},{q:'Output format specifications have no effect on the shape of the LLM\'s response.',a:'False'},{q:'Prompt chaining breaks a complex task into a series of intermediate steps using multiple prompts.',a:'True'},{q:'In prompt chaining, the result of each step is checked before proceeding to the next step.',a:'True'},{q:'Zero-shot prompting provides one example to demonstrate the desired outcome.',a:'False'},{q:'Few-shot prompting provides more than one example to guide the model\'s response behavior.',a:'True'},{q:'Meta prompting leverages the AI\'s ability to generate or refine its own prompts.',a:'True'},{q:'Meta prompting is useful when the tester is unsure how to craft an effective prompt.',a:'True'},{q:'One-shot prompting provides exactly one example to the model.',a:'True'},{q:'A system prompt is visible and editable by the chatbot user in most interfaces.',a:'False'},{q:'The system prompt stays constant throughout an interaction session.',a:'True'},{q:'User prompts represent the actual input or question from the chatbot\'s user.',a:'True'},{q:'System prompts can contain role, context, and constraints components of a structured prompt.',a:'True'},{q:'GenAI can help identify ambiguities and inconsistencies in requirements during test analysis.',a:'True'},{q:'LLMs can suggest test techniques such as boundary value analysis or equivalence partitioning.',a:'True'},{q:'GenAI cannot perform coverage analysis because it does not understand requirements.',a:'False'},{q:'LLMs can prioritize test conditions based on risk likelihood and impact of failure.',a:'True'},{q:'GenAI can generate test cases for both functional and non-functional testing requirements.',a:'True'},{q:'AI-generated test data cannot preserve data privacy because it is based on real data.',a:'False'},{q:'GenAI can generate automated test scripts compatible with various test automation frameworks.',a:'True'},{q:'Prompt chaining is most suitable for repetitive tasks with a specific output format.',a:'False'},{q:'Few-shot prompting is particularly effective for tasks requiring a specific, constrained output pattern.',a:'True'},{q:'Meta prompting is useful for flexible, dynamic tasks where the tester needs to craft new prompts.',a:'True'},{q:'Multiple prompting techniques can be combined for a single use case.',a:'True'},{q:'GenAI can analyze code changes to identify high-risk areas for targeted regression testing.',a:'True'},{q:'Self-healing tests automatically adjust test scripts to handle minor UI or API changes.',a:'True'},{q:'GenAI cannot assist with test monitoring because it only generates text.',a:'False'},{q:'GenAI can help generate dynamic dashboards and natural language summaries of test metrics.',a:'True'},{q:'Accuracy measures the overall correctness of GenAI output against expert-written test cases.',a:'True'},{q:'Precision evaluates the ability to identify all relevant instances within a dataset.',a:'False'},{q:'Recall measures the model\'s ability to identify all relevant instances in a dataset.',a:'True'},{q:'Diversity ensures a wide range of inputs and scenarios are covered, avoiding repetition.',a:'True'},{q:'Execution Success Rate measures how many generated test scripts run without syntax errors.',a:'True'},{q:'Time Efficiency evaluates the time saved compared to manual test efforts.',a:'True'},{q:'Prompt evaluation metrics should be based on statistically relevant data due to GenAI\'s non-deterministic nature.',a:'True'},{q:'A/B testing of prompts involves creating multiple prompt versions and evaluating which produces better results.',a:'True'},{q:'Output analysis examines AI-generated output for inaccuracies against the test basis.',a:'True'},{q:'Iterative prompt modification starts with a finished prompt and is never changed again.',a:'False'},{q:'Shorter prompts always produce better results than longer prompts.',a:'False'},{q:'Sharing prompt libraries across the test team helps standardize techniques and maintain consistent quality.',a:'True'},{q:'GenAI can generate Gherkin-style test cases using few-shot prompting.',a:'True'},{q:'In keyword-driven automation, predefined keywords represent common test steps.',a:'True'},{q:'Test case prioritization by GenAI can consider risk, dependencies, and test objectives.',a:'True'},{q:'GenAI can help produce test completion reports highlighting successes and lessons learned.',a:'True'},{q:'GenAI for test monitoring can analyze trends and predict potential risks.',a:'True'},{q:'LLMs can generate test oracle outputs, i.e., expected results for test cases.',a:'True'},{q:'The quality of LLM output for test tasks is independent of the quality of the input provided.',a:'False'},{q:'Multimodal prompting can combine GUI wireframes and user stories to generate acceptance criteria.',a:'True'},{q:'Prompt chaining with human verification is useful for progressively refining acceptance criteria.',a:'True'},{q:'GenAI cannot help with API regression testing because APIs are not text-based.',a:'False'},{q:'LLMs can generate test scripts that are then updated or extended based on new requirements.',a:'True'},{q:'Relevance and contextual fit determines whether GenAI output is applicable for a given context.',a:'True'},{q:'GenAI chatbots are accessible only to technical stakeholders.',a:'False'},{q:'Prompt engineering is not required when using LLM-powered testing applications.',a:'False'},{q:'GenAI can classify test anomalies based on severity and priority.',a:'True'},{q:'A system prompt may define the LLM\'s tone, domain-specific rules, and operational parameters.',a:'True'},{q:'Hallucinations occur when an LLM generates output that appears factually incorrect or irrelevant.',a:'True'},{q:'Reasoning errors occur when LLMs correctly interpret all logical structures including conditional logic.',a:'False'},{q:'LLM biases come from the data on which the model was trained.',a:'True'},{q:'Hallucinations in software testing can manifest as fictitious test cases or non-functioning test scripts.',a:'True'},{q:'LLMs possess true logical reasoning capabilities identical to human reasoning.',a:'False'},{q:'Non-deterministic LLM behavior makes it easy to permanently fix hallucinations.',a:'False'},{q:'Cross-verification compares AI-generated output with existing documentation to detect hallucinations.',a:'True'},{q:'Domain expertise consultation can help validate the accuracy of AI-generated content.',a:'True'},{q:'Reasoning errors can be detected by evaluating the logical flow and coherence of AI-generated content.',a:'True'},{q:'Bias detection includes reviewing whether generated test data is fairly and accurately represented.',a:'True'},{q:'Providing complete context in a prompt is a mitigation technique for hallucinations.',a:'True'},{q:'Lowering the LLM temperature parameter reduces randomness and results in more consistent outputs.',a:'True'},{q:'Setting a random seed guarantees 100% reproducibility in all LLM implementations.',a:'False'},{q:'Dividing prompts into smaller segments using prompt chaining can help detect reasoning errors early.',a:'True'},{q:'Using clear, interpretable data formats helps the model focus on essential task aspects.',a:'True'},{q:'Data exfiltration is a security attack that attempts to extract confidential training data from an LLM.',a:'True'},{q:'Unintentional data exposure occurs when GenAI outputs accidentally reveal sensitive information.',a:'True'},{q:'GDPR explicitly restricts all applications of GenAI in testing environments.',a:'False'},{q:'Data minimization involves using only the necessary amount of non-sensitive data in AI testing.',a:'True'},{q:'Data anonymization replaces sensitive information with non-identifiable data.',a:'True'},{q:'Regular security audits and vulnerability assessments are recommended for GenAI systems.',a:'True'},{q:'Training and processing LLMs requires minimal computing resources.',a:'False'},{q:'Generating a single image with a powerful AI model can consume more energy than generating text.',a:'True'},{q:'The cumulative environmental impact of GenAI across millions of users is negligible.',a:'False'},{q:'ISO/IEC 42001:2023 specifies requirements for managing AI systems within an organization.',a:'True'},{q:'The EU AI Act classifies AI applications by risk level and mandates compliance in transparency.',a:'True'},{q:'The NIST AI Risk Management Framework focuses on fairness, transparency, and security.',a:'True'},{q:'Selecting an appropriate GenAI model for the specific task is a mitigation strategy for hallucinations.',a:'True'},{q:'Comparing results across multiple LLMs helps detect output errors.',a:'True'},{q:'Higher LLM temperature always improves the consistency of outputs.',a:'False'},{q:'An LLM-powered test infrastructure integrates an LLM to enhance automation, reasoning, and decision-making in testing.',a:'True'},{q:'The front-end of an LLM-powered test infrastructure is where testers input queries or commands.',a:'True'},{q:'Vector databases are used for semantic retrieval of related content using embeddings.',a:'True'},{q:'The back-end of an LLM test infrastructure only handles authentication and nothing else.',a:'False'},{q:'RAG enhances LLMs by incorporating additional data sources into the response generation process.',a:'True'},{q:'In RAG preprocessing, large documents are broken into smaller chunks for focused retrieval.',a:'True'},{q:'RAG retrieval is typically based on semantic similarity between embeddings of the prompt and chunks.',a:'True'},{q:'RAG allows LLMs to access enterprise data sources such as databases and documentation in real time.',a:'True'},{q:'LLM-powered agents can only handle conversational question-and-answer interactions.',a:'False'},{q:'Autonomous agents operate independently with minimal human intervention.',a:'True'},{q:'Semi-autonomous agents perform tasks with periodic human oversight.',a:'True'},{q:'Multi-agent architectures use coordinated effort among several specialized agents, known as orchestration.',a:'True'},{q:'LLM-powered agents are immune to hallucinations and reasoning errors.',a:'False'},{q:'Fine-tuning adapts a pre-trained model to perform specific tasks or tailor it to particular domains.',a:'True'},{q:'Fine-tuning can be applied to Small Language Models (SLMs) as well as LLMs.',a:'True'},{q:'Overfitting in fine-tuning means the model becomes too specialized and performs poorly on new data.',a:'True'},{q:'Fine-tuning always eliminates the need for high-quality training datasets.',a:'False'},{q:'LLMOps refers to practices and processes for deploying and maintaining LLMs in production environments.',a:'True'},{q:'Using an AI chatbot for testing requires no consideration of data privacy or security.',a:'False'},{q:'In-house development of GenAI test tools requires expertise in implementing LLM-powered infrastructure.',a:'True'},{q:'RAG and fine-tuning are mutually exclusive and cannot be used together.',a:'False'},{q:'The back-end enhances the LLM\'s raw output through post-processing before presenting it to the front-end.',a:'True'},{q:'Fine-tuning can enable an LLM to generate test cases in an organization-specific output format.',a:'True'},{q:'Opacity in fine-tuned models refers to the lack of transparency in the LLM\'s decision-making.',a:'True'},{q:'LLM-powered agents invoke predefined functions called \'tools\' to interact with external systems.',a:'True'},{q:'Shadow AI refers to the use of unapproved AI tools that can lead to security and compliance risks.',a:'True'},{q:'Vague intellectual property is not a risk associated with shadow AI.',a:'False'},{q:'Defining measurable test objectives is the first step in implementing a GenAI strategy in testing.',a:'True'},{q:'Data quality is not critical to the effectiveness of LLM-powered testing.',a:'False'},{q:'Recurring cost is a key criterion when selecting LLMs/SLMs for software test tasks.',a:'True'},{q:'The Discovery phase of GenAI adoption focuses on awareness and capability building.',a:'True'},{q:'In the Utilization and Iteration phase, organizations fully integrate GenAI into their test processes.',a:'True'},{q:'The three phases of GenAI adoption must always be completed sequentially across all use cases.',a:'False'},{q:'Testers working with GenAI must combine domain expertise with AI skills.',a:'True'},{q:'Data sanitization involves removing or masking sensitive information before sharing with LLMs.',a:'True'},{q:'Test managers in AI-enabled organizations only need to manage human testers.',a:'False'},{q:'Internal communities of practice help share prompt pattern libraries and lessons learned.',a:'True'},{q:'Model performance for targeted test tasks is a key criterion when selecting an LLM/SLM.',a:'True'},{q:'Fear of job displacement is not a concern during GenAI adoption in test organizations.',a:'False'},{q:'Testers evolve from test design specialists to AI-assisted test specialists who verify AI-generated testware.',a:'True'}];
const PACKS={"1":[{"q":"Match each type of AI technology (1-4) with its CORRECT description (A-D):\n1. Rule-based AI\n2. Supervised Machine Learning\n3. Deep Learning\n4. Foundation Models\nA. Learns patterns from large amounts of unlabeled data and can be adapted to many downstream tasks.\nB. Relies on manually coded if-then rules and logical reasoning with no learning from data.\nC. Requires human-labeled training data and learns to map inputs to specific outputs.\nD. Uses multi-layered neural networks to automatically discover complex patterns and representations in data.","opts":["1A, 2C, 3D, 4B","1B, 2C, 3D, 4A","1D, 2B, 3A, 4C","1C, 2A, 3B, 4D"],"correct":[1],"exp_count":1,"exp":"1. Rule-based AI → B (if-then rules, no learning)\n\n2. Supervised Machine Learning → C (needs labeled data, learns input → output mapping)\n\n3. Deep Learning → D (multi-layered neural nets that learn complex features)\n\n4. Foundation Models → A (large pre-trained models on vast data that can be fine-tuned)"},{"q":"In the context of Large Language Models (LLMs), which of the following options BEST explains why a limited context window negatively impacts their performance on long-document analysis tasks?","opts":["Because a small context window makes it difficult for LLMs to generate creative and diverse responses.","Because LLMs must compress or ignore parts of the earlier text when the input exceeds the context limit, potentially losing critical details required for accurate later analysis.","Because context windows prevent LLMs from understanding technical terminology and domain-specific language.","Because a limited context window forces the model to process text at extremely high speed, reducing accuracy."],"correct":[1],"exp_count":1,"exp":"b) is the correct answer. It clearly and directly describes the real technical consequence of a small context window: the model is forced to drop or compress earlier tokens, leading to loss of relevant information for later parts of the document.\n\nWhy not the others?\n\na) Creativity is not directly tied to context window size.\n\nc) Understanding terminology depends more on training data and embeddings than context window.\n\nd) Speed is not the main issue caused by context window limitations."},{"q":"Which of the following statements BEST describes the role of embeddings in how LLMs process language?","opts":["Embeddings break raw text into smaller units such as words or subwords.","Embeddings convert tokens into high-dimensional numerical vectors that capture semantic meaning and relationships between words.","Embeddings predict the most likely next token in a sequence based on previous context.","Embeddings are responsible for formatting the final output into readable sentences for the user."],"correct":[1],"exp_count":1,"exp":"b) is the correct answer. It precisely explains what embeddings do: they transform discrete tokens into dense vectors that allow the model to understand similarity, context, and meaning.\n\nWhy not the others?\n\na) Describes tokenization, not embeddings.\n\nc) Describes the next-token prediction mechanism (the training objective).\n\nd) Describes the final decoding/generation stage."},{"q":"In the context of software testing, which of the following statements (i-v) about different types of LLMs are CORRECT?\ni. Foundation LLMs are the best choice for generating well-structured defect reports that follow company templates.\nii. Instruction-tuned LLMs perform well when given clear instructions to generate traceability matrices between requirements and test cases.\niii. Reasoning LLMs are particularly effective at performing root cause analysis on complex intermittent defects.\niv. Foundation LLMs excel at autonomously creating complete test automation frameworks from scratch.\nv. Instruction-tuned LLMs are generally weak at following strict output formats such as JSON or Gherkin.","opts":["i, iii, and iv","ii and iii","i, ii, and v","ii, iii, and iv"],"correct":[1],"exp_count":1,"exp":"The answer is b) ii and iii. Only these two statements accurately reflect the typical strengths of the respective LLM types.\n\nWhy not the others?\n\ni and v wrongly attribute template/format adherence to Foundation models (it belongs to instruction-tuned).\n\niv overstates Foundation models’ capabilities (they are not good at autonomous complex framework creation)."},{"q":"Which of the following statements BEST describes the relationship between multimodal AI models and vision-language models (VLMs)?","opts":["Multimodal AI models are a narrow specialization that only processes images and text.","Vision-language models are a broader category that can handle any combination of data types including audio and video.","Multimodal AI models can process multiple data types (text, image, audio, video), while vision-language models are a specialized subset that primarily combines visual and textual information.","Multimodal AI models and vision-language models refer to exactly the same technology with no meaningful difference."],"correct":[2],"exp_count":1,"exp":"c) is the correct answer. It clearly explains that multimodal is the broader category (multiple modalities) and vision-language models are a specialized subset focused on vision + text. This matches current industry understanding and terminology.\n\nWhy not the others?\n\na) Reverses the scope (makes multimodal narrow instead of broad).\n\nb) Also reverses the relationship.\n\nd) Claims they are identical, which is not accurate."},{"q":"Which TWO of the following options represent key capabilities of LLMs in software testing tasks?","opts":["Directly executing performance tests and measuring response times under load.","Generating realistic test cases in Gherkin or BDD format from user stories.","Performing end-to-end security vulnerability scanning on live systems.","Detecting potential defects and risks in user stories or acceptance criteria.","Writing and maintaining automated test scripts in Selenium or Playwright without any human review. Select TWO options."],"correct":[1,3],"exp_count":2,"exp":"The answers b) and d) are the correct choices.\n\nb) LLMs are particularly strong at translating natural language (user stories) into structured test cases (Gherkin/BDD), which is a very common and valuable use case.\n\nd) LLMs are effective at reviewing user stories/acceptance criteria for clarity, testability, ambiguities, and potential risks which is a high-value early testing activity.\n\nWhy not the others?\n\na) and c) require direct interaction with running systems and specialized testing tools and LLMs alone cannot do this effectively.\n\ne) LLMs can help generate test scripts, but “writing and maintaining without any human review” is unrealistic and overstates their current capability."},{"q":"Which of the following statements BEST explains the difference between general-purpose LLMs and LLM-powered testing tools in the context of software testing?","opts":["General-purpose LLMs are highly specialized for testing activities, while LLM-powered testing tools are designed for casual conversations.","Both general-purpose LLMs and LLM-powered testing tools require the same level of integration and offer identical capabilities for test automation.","General-purpose LLMs excel at open-ended conversations and ad-hoc queries, while LLM-powered testing tools are built with domain-specific integrations, workflows, and features tailored for testing processes.","LLM-powered testing tools rely only on simple prompts, whereas general-purpose LLMs need complex configuration and test tool integration."],"correct":[2],"exp_count":1,"exp":"c) is the correct answer. It accurately differentiates the general-purpose nature (good for ad-hoc, conversational use) from the specialized nature (integrated, workflow-oriented, tailored for testing).\n\nWhy not the others?\n\na) Reverses the roles.\n\nb) Claims they are the same, which is false.\n\nd) Misrepresents both sides."},{"q":"A product owner is using a structured prompt to have an LLM generate user stories from high-level business needs. One of the components of this prompt reads: “Customer feedback survey results from the last quarter, competitor feature comparison spreadsheet, and internal stakeholder interview notes from three workshops.” In which component of the six-part prompt structure would this description MOST LIKELY appear?","opts":["Instructions","Input Data","Constraints","Role"],"correct":[1],"exp_count":1,"exp":"b) Input Data is the correct answer. The sentence lists concrete data sources and materials the LLM is expected to use as the basis for its work. This matches the definition of the Input Data section in structured prompting.\n\nWhy not the others?\n\na) Instructions: Would tell the LLM what to do with the data (e.g., “Generate detailed user stories and acceptance criteria”).\n\nc) Constraints: Would set rules or limitations (e.g., “Each user story must fit in one sprint”).\n\nd) Role: Would define the persona (e.g., “Act as an experienced Agile product owner”)."},{"q":"A developer is using a structured prompt to ask an LLM to review a piece of Python code for bugs and improvements. One line in the prompt reads: “Return your findings as a numbered list where each item includes: Issue ID, Code Snippet, Issue Type (Bug / Security / Performance / Style), Description, and Recommended Fix.” In which component of the six-part prompt structure would this line MOST LIKELY appear?","opts":["Role","Constraints","Output Format","Instructions"],"correct":[2],"exp_count":1,"exp":"c) Output Format is the correct answer. The line clearly dictates the structure and format of the final answer (numbered list with specific required fields/columns for each issue). This is the definition of the Output Format component in structured prompting.\n\nWhy not the others?\n\na) Role: Defines who the LLM should act as (e.g., “Act as a senior Python developer”).\n\nb) Constraints: Would restrict scope or rules (e.g., “Only report issues with severity High or above”).\n\nd) Instructions: Would say what to do (e.g., “Analyze the code for bugs, security issues, and performance problems”)."},{"q":"Which of the following BEST differentiates zero-shot prompting, chain-of-thought prompting, and self-consistency prompting techniques?","opts":["Zero-shot prompting uses multiple examples, chain-of-thought breaks tasks into steps with reasoning, and self-consistency generates one single response for reliability.","Zero-shot prompting provides no examples and relies on the model’s existing knowledge, chain-of-thought prompting encourages the model to show step-by-step reasoning, and self-consistency prompting generates multiple responses and selects the most consistent answer.","Chain-of-thought prompting provides examples, self-consistency focuses on breaking down tasks, and zero-shot prompting iteratively refines the output.","Self-consistency prompting gives no examples, zero-shot prompting generates multiple answers, and chain-of-thought relies on manual prompt optimization."],"correct":[1],"exp_count":1,"exp":"b) is the correct answer. It accurately describes the essence of each technique:\n\n- Zero-shot: No examples provided.\n\n- Chain-of-Thought: Forces explicit step-by-step reasoning.\n\n- Self-Consistency: Improves reliability by sampling multiple reasoning paths and choosing the best/consensus answer.\n\nWhy not the others?\n\na), c), and d) all mix up the definitions or assign wrong characteristics to the techniques."},{"q":"What is the primary purpose of a system prompt when configuring an LLM for a customer support chatbot?","opts":["To deliver the user’s specific question or complaint in each interaction.","To define the chatbot’s overall personality, response style, knowledge boundaries, and behavioral rules for the entire conversation.","To dynamically change the topic of discussion based on the user’s latest message.","To provide real-time data from external databases during the conversation."],"correct":[1],"exp_count":1,"exp":"b) is the correct answer. It accurately describes the main role of the system prompt which is setting the “rules of the game” (personality, tone, constraints, scope) that apply across all user interactions. This is what allows the chatbot to consistently act as a helpful, polite, knowledgeable support agent.\n\nWhy not the others?\n\na) Describes the user message, not the system prompt.\n\nc) Dynamic topic changes are handled by conversation history or user inputs, not the system prompt.\n\nd) Fetching real-time external data is typically done via tools/plugins, not the system prompt."},{"q":"You are tasked with using Generative AI and prompt chaining to perform a structured code review on a newly written Python module. The goals are: (1) identify all potential bugs and quality issues, (2) categorize and prioritize the issues by severity, and (3) suggest specific fixes for the highest-priority issues. The code has already passed basic syntax checking. Which of the following sequences of steps (i-v) should you follow to effectively apply prompt chaining for this code review task?\ni. Submit the code to the LLM and prompt it to identify all potential bugs, security issues, and code quality problems.\nii. Provide the list of identified issues to the LLM and prompt it to categorize and prioritize them by severity (Critical, High, Medium, Low).\niii. Submit the original code along with the prioritized issues to the LLM and prompt it to suggest concrete code fixes for all Critical and High severity issues.\niv. Submit the code to the LLM in one prompt and ask it to identify issues, prioritize them, and suggest fixes all at once.\nv. Ask the LLM to first check the code for compliance with the project’s coding style guide and naming conventions.","opts":["i, ii, and iii","iv only","i, v, and ii","v, i, and iii"],"correct":[0],"exp_count":1,"exp":"a) i, ii, and iii is the best answer. It follows true prompt chaining: each step uses the output of the previous step as input. It directly covers all three stated goals: issue identification, prioritization, and suggesting fixes. It respects the given context (code already passed syntax checking, so no need for basic checks).\n\nWhy not the others?\n\nb) Combines everything into one prompt and defeats the purpose of chaining.\n\nc) Inserts an unnecessary style guide check (v) that is not part of the defined goals.\n\nd) Starts with an optional style check and still doesn’t clearly separate the steps."},{"q":"You want to apply few-shot structured prompting to generate BDD-style user stories and acceptance criteria from a given set of high-level requirements. You have several high-quality predefined examples that show how to break down requirements into well-written user stories (As a ... I want ... So that ...) and clear, testable acceptance criteria. Your task is to create a prompt that guides the LLM to produce accurate, high-quality user stories and acceptance criteria aligned with the provided requirements. Which one of the following prompts is BEST suited to this task?","opts":["Prompt A Role: Act as a business analyst. Context: You are writing user stories for a new feature. Instruction: Generate user stories and acceptance criteria based on the requirement below. Input Data: <<< high-level requirement >>> Constraints: Follow best practices for user story writing. Output Format: Use standard user story template.","Prompt B Role: Act as a senior business analyst specializing in Agile user story writing. Context: You are breaking down high-level requirements into BDD-style user stories. Instruction: Generate user stories with acceptance criteria for the given requirement, using the following predefined examples as a guide: << predefined examples >>. Input Data: <<< high-level requirement >>> Constraints: Ensure each story follows the “As a [role], I want [goal], So that [benefit]” format and that acceptance criteria are clear, testable, and complete. Output Format: Present each user story followed by its acceptance criteria in bullet points.","Prompt C Role: Act as a business analyst. Context: You are writing user stories. Instruction: Create at least 3 user stories with acceptance criteria. Focus on both the happy path and edge cases. Input Data: <<< high-level requirement >>> Constraints: Use Given-When-Then where possible. Output Format: Number the stories clearly.","Prompt D Role: Act as a business analyst. Context: You are writing user stories for a new feature. Instruction: Generate user stories and acceptance criteria using best practices. Input Data: <<< high-level requirement >>> Constraints: Make them detailed and testable. Output Format: Use standard format."],"correct":[1],"exp_count":1,"exp":"Prompt B is the best answer because:\n\n- It clearly implements few-shot prompting by including predefined examples.\n\n- The role is specialized for higher quality output.\n\n- The instruction explicitly references the examples as a guide.\n\n- Constraints are precise (correct format + testable criteria).\n\n- Output format is clearly defined.\n\nThis matches structured prompt engineering best practices for few-shot scenarios.\n\nWhy not the others? \n\na) and d) are zero-shot (no examples) and too generic.\n\nc) lacks examples and forces arbitrary rules (“at least 3”, focus on edge cases) that may reduce alignment with the input requirement."},{"q":"You are tasked with applying structured prompting to generate a code review summary from static analysis tool outputs and git commit logs. Here is an initial draft of the prompt: Role: Act as a code reviewer. Context: Analyze outputs from static analysis tools and recent code changes. Instruction: Identify potential issues in the code. Input Data: Use the provided static analysis report and commit logs. Constraints: Focus only on high-severity findings. Output Format: List all issues in bullet points. You are asked to improve this prompt. Which of the following improvements would BEST align the prompt with structured prompt engineering best practices for producing a high-quality, comprehensive code review summary?","opts":["Change the role to “Senior Security-Focused Code Reviewer with 10+ years of experience”.","Add a constraint requiring the use of a specific tone that is polite and encouraging.","Expand the instruction to include categorizing issues by type (security, performance, maintainability, readability), assessing severity, suggesting fixes, and prioritizing them.","Instruct the LLM to first generate a summary of all files changed before identifying any issues."],"correct":[2],"exp_count":1,"exp":"The core problem is that the original instruction is too vague (“Identify potential issues”), and the best improvement comes from making the instruction more detailed and structured.\n\nc) is the best answer because it follows structured prompt engineering best practices by expanding the instruction with clear sub-tasks (categorization, severity assessment, fix suggestions, prioritization). This decomposition leads to more comprehensive, consistent, and actionable output which is exactly what good prompt engineering aims for in analytical/reporting tasks.\n\nWhy not the others?\n\na) Improving the role can help slightly but usually has limited effect compared to a stronger instruction.\n\nb) Tone constraints are secondary; they don’t improve the depth or accuracy of the analysis.\n\nd) Adding a preliminary summarization step is reasonable but less impactful than a full task breakdown in the main instruction."},{"q":"You are using an LLM to generate project status reports from raw Jira ticket data, sprint logs, and burndown charts. The goal is to produce reports that are accurate, visually clear, and, most importantly, help the project manager and team make better decisions quickly. Here is an initial draft of the prompt: Role: Act as a project coordinator. Context: You are given raw project data including tickets, timelines, and effort logs. Instruction: Analyze the data and generate a project status report covering progress, risks, and resource utilization. Input Data: Use the provided JSON file with project data. Constraints: Keep the report professional. Output Format: Present the information in a structured report. You are asked to improve this prompt. Which of the following improvements would BEST enhance the LLM’s ability to produce accurate and actionable reports?","opts":["Add a requirement to always include colorful visualizations and charts for every metric.","Instruct the LLM to first list all raw numbers and calculations before summarizing anything.","Expand the output format to include a clear executive summary, key insights, and specific recommended actions with owners and deadlines.","Strengthen the role to “Act as a senior project manager with 15 years of experience in agile methodologies.”"],"correct":[2],"exp_count":1,"exp":"### It directly tackles the biggest weakness of the original prompt - lack of actionability. Adding an executive summary, key insights, and concrete recommended actions (with owners and deadlines) turns a dry report into a decision-support tool. This is the single highest-impact improvement for helping stakeholders \"make better decisions quickly,\" which matches the goal.\n\nWhy not the others?\n\na) Focuses on visuals. They are nice to have, but visuals alone don’t guarantee actionability or accuracy.\n\nb) Forces a rigid thinking process (list raw numbers first) - this may improve transparency but often makes the report less readable and less actionable.\n\nd) Improving the role description is common but has limited effect compared to explicitly defining a better output structure that includes insights and actions."},{"q":"You are building a code generation system that translates natural language descriptions into Python functions. You have a small set of manually verified \"golden\" examples (input description to correct Python code). You have also identified consistent transformation rules, such as: \"If the original task involves processing a list, the transformed version should process a dictionary with the same logic\"; \"If the original returns a single value, the transformed version should return a list of values\"; and similar semantic-preserving mutations. Your goal is to use an LLM to automatically generate many more high-quality training examples by applying these rules to your golden examples. You will provide the LLM with the golden examples, the transformation rules, and instructions to generate new pairs by applying the rules correctly. Which prompting technique is BEST suited for this goal?","opts":["Few-shot prompting","Prompt chaining","Meta prompting","Zero-shot prompting"],"correct":[0],"exp_count":1,"exp":"### You have a limited number of high-quality seed examples (golden pairs) with known correct outputs, plus clear, well-defined transformation rules that preserve correctness (similar to metamorphic relations).\n\nFew-shot prompting excels here because: \n\n- The golden examples serve as direct demonstrations of what a correct input-output pair looks like.\n\n- The transformation rules can be explained in the prompt, and the model can see them applied (or be guided to apply them) on the provided examples.\n\n- This allows the LLM to reliably learn the pattern of rule application and generate new, semantically equivalent but varied examples with high accuracy. \n\n- It is particularly powerful for data augmentation tasks where fidelity to the rules is essential.\n\nWhy not the others?\n\nb) Prompt chaining would be overkill unless the transformation required many sequential complex steps.\n\nc) Meta prompting is unnecessary, we don't need the model to create prompts; we need it to generate data.\n\nd) Zero-shot prompting lacks concrete examples, making it more likely for the model to misapply the rules or produce lower-quality variations."},{"q":"You are using Generative AI to support testing of a financial banking application. The AI generates test scenarios for user transactions, compliance check scripts, and synthetic transaction data for various risk levels. To effectively evaluate the Generative AI model’s performance and improve your prompts, which combination of metrics and actions BEST ensures comprehensive assessment and continuous improvement?","opts":["Measure only the speed of generation and the number of test cases produced per hour.","Prioritize correctness and regulatory compliance for all generated outputs, while using diversity and coverage metrics to ensure broad risk scenario coverage.","Focus mainly on creativity of test scenarios and visual appeal of the generated test data.","Evaluate based on test execution success rate alone and compare total lines of code generated versus manual scripting."],"correct":[1],"exp_count":1,"exp":"b) is the best answer.\n\n- In banking/financial testing, correctness and regulatory compliance are non-negotiable (relevance and contextual fit).\n\n- Diversity and coverage are equally critical because financial systems must handle many risk levels, edge cases, and transaction variations.\n\n- This combination directly supports both quality evaluation and prompt refinement.\n\nWhy not the others?\n\na) and d) focus on productivity/speed metrics, which are secondary.\n\nc) “Creativity and visual appeal” is irrelevant for banking test generation."},{"q":"Which of the following techniques for evaluating and iteratively refining prompts is BEST suited for determining why an LLM repeatedly produces vague and incomplete test scripts when asked to generate automation code from user stories?","opts":["Increasing the number of few-shot examples in the prompt","Output analysis","Running multiple prompt variations in parallel (A/B testing)","Adding more detailed role descriptions"],"correct":[1],"exp_count":1,"exp":"b) Output analysis is still the correct answer. Carefully analyzing the flawed outputs (what is missing, which parts are vague, which parts are incorrect) provides the clearest insights into what is missing from the prompt, allowing targeted improvements.\n\nWhy not the others?\n\na) and d) are improvement actions you might take after diagnosis.\n\nc) A/B testing helps compare performance but does not deeply explain the root cause of vagueness/incompleteness."},{"q":"When it comes to LLMs, what is a hallucination?","opts":["When the LLM refuses to generate any test cases due to safety filters.","When the LLM generates plausible-sounding test cases or expected results that are factually incorrect or not supported by the given requirements.","When the LLM produces test scripts that run too slowly during execution.","When the LLM consistently generates overly short or incomplete responses."],"correct":[1],"exp_count":1,"exp":"b) is the correct answer. It clearly describes the typical hallucination problem in testing: the LLM inventing wrong test steps, incorrect expected outcomes, or non-existent conditions that sound reasonable but contradict the requirements.\n\nWhy not the others?\n\na) Refers to refusal behavior, not hallucination.\n\nc) Relates to performance issues, not hallucination.\n\nd) Describes brevity/incompleteness, which is a different prompt quality problem."},{"q":"You are using Generative AI to generate test cases for a banking mobile application. The project briefing explicitly mentions the following features only: • Fund transfer between accounts • Bill payment functionality • Transaction history viewing Based on these details, which of the following AI-generated test cases MOST LIKELY represents a hallucination?","opts":["Verify that a user can transfer funds from their savings account to a checking account.","Verify that a user can schedule a recurring bill payment for electricity.","Verify that a user receives a notification after completing a successful fund transfer.","Verify that a user can apply for a personal loan directly from the mobile app."],"correct":[3],"exp_count":1,"exp":"Options a), b), and c) are directly related to the three explicitly mentioned features (fund transfer, bill payment, transaction history).\n\nOption d) introduces an entirely new feature (personal loan application) that was never mentioned → clear hallucination."},{"q":"Which of the following options refers to a benefit that is MOST directly associated with using well-structured prompts (including clear role, instructions, constraints, and output format) when working with LLMs for software testing tasks?","opts":["It significantly increases the creativity and novelty of the generated test ideas.","It helps the LLM produce more consistent, accurate, and predictable outputs.","It reduces the need to use any examples or few-shot prompting.","It allows the LLM to handle much larger context windows effectively."],"correct":[1],"exp_count":1,"exp":"b) is the correct answer. Clear structure in prompts is known to dramatically improve consistency, accuracy, and predictability of LLM outputs, which is critical in software testing where reliability matters.\n\nWhy not the others?\n\na) Structure usually reduces uncontrolled creativity rather than increasing it.\n\nc) Good structure often works with few-shot prompting, not instead of it.\n\nd) Prompt structure has little to no direct impact on context window size."},{"q":"Which of the following strategies is MOST effective for reducing randomness and increasing consistency in LLM-generated test cases and expected results?","opts":["Raising the temperature parameter above 1.0","Setting a lower temperature value (e.g., 0.2 or 0.0)","Using a very large context window","Increasing the top-p (nucleus sampling) value to 0.95"],"correct":[1],"exp_count":1,"exp":"b) is the correct answer. Lowering temperature is the most direct and widely used method to make LLM outputs more deterministic and consistent, which is highly desirable when generating test artifacts that need to be reliable.\n\nWhy not the others?\n\na) Raising temperature increases randomness, it’s the opposite of what is needed.\n\nc) Context window size affects how much information the model can see, not randomness.\n\nd) Increasing top-p usually increases diversity (more randomness)."},{"q":"Which of the following statements about data privacy concerns when using Generative AI in software testing is INCORRECT?","opts":["Sending production data or real user information in prompts to public Generative AI services can lead to unintended data leaks.","Generative AI models may retain and reuse prompts containing sensitive test data for future training unless opted out.","Hallucinations in Generative AI are a major risk because they frequently cause the model to output real confidential information from its training data.","Failing to anonymize test data before using it with Generative AI tools can violate data protection laws."],"correct":[2],"exp_count":1,"exp":"c) is the incorrect statement. Hallucinations produce plausible but false information. They do not typically output real confidential data from training (modern LLMs are trained on vast public data and have safeguards). The real privacy risk comes from feeding sensitive data into the prompt, not from hallucinations themselves.\n\nWhy not the others?\n\na), b), and d) accurately reflect genuine and well-known data privacy risks when using GenAI in testing."},{"q":"During the training of an LLM used for generating security test cases, an attacker deliberately inserts thousands of malicious code snippets labeled as “safe” into the training dataset. As a result, the model starts recommending insecure coding practices as secure solutions. What type of attack vector does this description BEST refer to?","opts":["Prompt injection","Model inversion","Data poisoning","Adversarial example generation"],"correct":[2],"exp_count":1,"exp":"c) is the correct answer. The attacker manipulates the training data (inserting malicious examples with wrong labels), which directly matches the definition of data poisoning.\n\nWhy not the others?\n\na) Prompt injection: Happens at inference time by manipulating user prompts.\n\nb) Model inversion: Involves extracting training data from the model (a privacy attack).\n\nd) Adversarial example generation: Usually refers to crafting inputs that fool a deployed model, not poisoning its training data."},{"q":"Match each type of attack vector against an LLM (1-4) with the corresponding example (A-D):\n1. Prompt Injection\n2. Data Poisoning\n3. Model Inversion\n4. Output Manipulation\nA. An attacker feeds carefully crafted malicious requirements and fake test results into the training data so that the LLM starts recommending incorrect test strategies.\nB. An attacker submits a series of specially designed prompts that cause the LLM to leak internal project documentation and confidential test data.\nC. An attacker tricks the LLM into generating test cases that deliberately skip critical security checks by using deceptive instructions hidden in the prompt.\nD. An attacker analyzes multiple outputs from the LLM over time to reconstruct and extract sensitive information about the original training dataset.","opts":["1C, 2A, 3D, 4B","1B, 2A, 3D, 4C","1C, 2A, 3B, 4D","1C, 2D, 3A, 4B"],"correct":[0],"exp_count":1,"exp":"1. Prompt Injection → C (deceptive prompts to make the LLM skip security checks)\n\n2. Data Poisoning → A (corrupting training data with fake requirements/test results)\n\n3. Model Inversion → D (reconstructing training data from outputs)\n\n4. Output Manipulation → B (tricking the model to leak confidential data through outputs)"},{"q":"Which of the following strategies BEST addresses security and compliance risks when using Generative AI for automated code generation in a regulated industry (such as banking or healthcare)?","opts":["Sharing the full proprietary codebase with the public LLM to get more accurate code suggestions.","Using only anonymized or synthetic code snippets and internal/self-hosted LLMs with strict access controls.","Allowing the Generative AI model to train continuously on all production code to improve future suggestions.","Turning off logging and audit trails to reduce overhead when interacting with the AI code generation tool."],"correct":[1],"exp_count":1,"exp":"b) is the correct answer. It directly reduces exposure of sensitive/protected assets by using anonymized/synthetic data and keeping everything inside controlled, self-hosted environments.This approach balances usefulness with strong security and compliance (e.g., GDPR, HIPAA, PCI-DSS, etc.).\n\nWhy not the others?\n\na) and c) greatly increase risk by exposing real sensitive code to external models or continuous training.\n\nd) Removing logging/auditing weakens compliance and makes incidents harder to investigate."},{"q":"Which of the following statements about the environmental impact of using Generative AI in software development is CORRECT?","opts":["Training large AI models has minimal energy cost compared to running inference on a daily basis.","Using AI code generation tools always reduces the overall carbon footprint of a development team by replacing human programmers.","Inference tasks such as code generation or test case creation with LLMs consume noticeably more energy per request than simple traditional keyword searches or basic IDE operations.","Generative AI tools for developers have negligible environmental impact because modern data centers are highly energy-efficient."],"correct":[2],"exp_count":1,"exp":"c) is the correct answer. Each AI inference request (generating code, tests, summaries, etc.) requires running a large neural network, which uses significantly more electricity than a traditional Google-style search or local IDE autocomplete. While the per-request difference may seem small, it adds up at team or organizational scale.\n\nWhy not the others?\n\na) Training is extremely energy-intensive; inference is lighter but still substantial when scaled.\n\nb) AI tools can increase productivity but do not automatically reduce carbon footprint — they often add net energy use.\n\nd) Even with efficient data centers, the rapid growth and scale of GenAI usage create a measurable and growing environmental footprint."},{"q":"Which TWO of the following standards, or parts of them, are MOST relevant to the use of Generative AI for requirements elicitation and analysis in software projects?","opts":["ISO/IEC/IEEE 29148:2018","ISO/IEC 42001:2023","ISO/IEC/IEEE 15288:2023","ISO/IEC 23053:2022","ISO/IEC 25059:2023"],"correct":[1,3],"exp_count":2,"exp":"b) ISO/IEC 42001:2023 Provides the management system and governance framework needed when using GenAI for requirements work.\n\nd) ISO/IEC 23053:2022 Offers the foundational framework for AI systems using machine learning, directly applicable to Generative AI tools.\n\nWhy not the others?\n\na) Requirements engineering standard (general, not AI-specific)\n\nc) System life cycle processes (broad, not AI-focused)\n\ne) AI quality model (related but narrower than 42001 and 23053)"},{"q":"Which of the following components of an LLM-powered code generation tool is responsible for retrieving relevant code snippets from a vector database and combining them with the user’s natural language request to build the final prompt sent to the LLM?","opts":["Front-end interface","Prompt engineering & retrieval module","Output validation component","User authentication service"],"correct":[1],"exp_count":1,"exp":"b) is the correct answer. The component that actively retrieves semantically similar data (via vector search) and combines it with user input to craft a high-quality prompt is best described as the Prompt engineering & retrieval module (this is typically part of the back-end or a dedicated middleware layer in RAG-based systems).\n\nWhy the other options are incorrect:\n\na) Front-end only collects user requests and shows results.\n\nc) Output validation happens after the LLM generates code.\n\nd) Authentication is about security and access control."},{"q":"You are a developer working on an e-commerce platform that includes features such as product search, shopping cart, checkout, and payment processing. The system documentation, including API specifications, user stories, and performance requirements, is stored in a vector database, while previous code snippets and unit tests are stored in a code repository. Your task is to generate new unit tests using a Retrieval-Augmented Generation (RAG) framework to ensure the tests align with current specifications and best practices. Which of the following options represents the MOST appropriate use of the RAG framework in this scenario?","opts":["Submit a broad query asking for unit tests for the entire e-commerce platform. The RAG framework will retrieve all related documents and generate tests for every feature in one go.","Submit a focused query for a single feature (e.g., “checkout process”). The RAG framework will retrieve relevant API specifications, user stories, and similar existing unit tests, then generate accurate, context-aware unit tests through the LLM.","Use the RAG framework only to retrieve documents, then manually combine them with your own knowledge before writing the unit tests yourself.","Let the LLM generate unit tests based solely on its internal knowledge while occasionally checking the vector database separately for reference."],"correct":[1],"exp_count":1,"exp":"b) is the correct answer. RAG performs best with focused, specific queries rather than broad ones. It properly leverages retrieval of relevant context (specifications + similar artifacts) to augment the LLM’s generation. This leads to higher quality, more accurate, and better-aligned outputs.\n\nWhy not the others?\n\na) Broad query → poor retrieval precision and lower quality results.\n\nc) Adds heavy manual effort, reducing the benefit of automation.\n\nd) Does not fully utilize RAG (retrieval is not integrated into prompt generation)."},{"q":"Which of the following options BEST describes the enhancements that autonomous and semi-autonomous LLM-powered agents bring to code generation and code review processes?","opts":["They can enhance both speed and code quality by completely removing the need for any human review or oversight.","They can enhance both efficiency and quality by operating effectively with different levels of human collaboration and supervision.","They primarily improve efficiency but tend to reduce overall code quality due to occasional hallucinations.","They enhance quality significantly but slow down the development process because they require constant human approval for every generated snippet."],"correct":[1],"exp_count":1,"exp":"b) is the correct answer. It accurately highlights the balanced benefit: agents can work independently for speed/efficiency while still allowing human collaboration/supervision when higher quality or risk mitigation is needed.\n\nWhy not the others?\n\na) and d) present unrealistic extremes (completely removing human review or requiring constant approval).\n\nc) assumes a negative trade-off, which is not the case with well-designed agent systems."},{"q":"Which of the following statements about prompt engineering for LLM-based testing tasks is INCORRECT?","opts":["Prompt engineering involves carefully designing inputs to guide the LLM toward producing more accurate and relevant outputs without changing the model’s parameters.","Prompt engineering is a low-cost alternative to fine-tuning that can significantly improve performance on testing-related tasks.","A well-crafted prompt can completely eliminate hallucinations and ensure the LLM always produces factually correct test cases.","Effective prompt engineering often includes techniques such as few-shot examples, clear instructions, and structured output formats."],"correct":[2],"exp_count":1,"exp":"c) is the incorrect statement. Even with excellent prompt engineering, LLMs can still hallucinate or produce incorrect outputs. Prompt engineering reduces hallucinations but cannot completely eliminate them. Claiming it ensures the LLM “always produces factually correct test cases” is unrealistic.\n\nWhy not the others?\n\na), b), and d) accurately describe the nature, benefits, and common techniques of prompt engineering."},{"q":"Which of the following BEST describes the primary focus of MLOps (Machine Learning Operations) when deploying and managing machine learning models for software testing and quality assurance tasks?","opts":["Completely eliminating the use of machine learning in testing activities to avoid complexity.","Managing the end-to-end lifecycle of ML models, including deployment, monitoring, scalability, and governance.","Restricting ML models to only simple classification tasks within the testing process.","Ensuring all test automation is performed exclusively by ML models with zero human involvement."],"correct":[1],"exp_count":1,"exp":"b) is the correct answer. MLOps is fundamentally about managing the full lifecycle of ML models in production, from training and deployment to continuous monitoring, scaling, and governance. This is exactly parallel to what LLMOps does for LLMs.\n\nWhy not the others?\n\na) and c) are overly restrictive and go against the purpose of MLOps.\n\nd) Promotes an unrealistic “zero human involvement” approach."},{"q":"Which of the following statements about Shadow AI is CORRECT?","opts":["Shadow AI helps organizations maintain full visibility and control over all AI tool usage.","Shadow AI significantly lowers the risk of data breaches and compliance violations.","Shadow AI can result in the unintentional exposure of confidential business data to external AI providers.","Shadow AI ensures that all AI tools used by employees are properly licensed and approved."],"correct":[2],"exp_count":1,"exp":"c) is the correct answer. It accurately describes one of the biggest dangers of Shadow AI: employees may paste sensitive or confidential data into public AI tools, leading to potential data leaks to third-party providers.\n\nWhy not the others?\n\na), b), and d) present positive or protective effects, which are the opposite of reality. Shadow AI reduces visibility and control, and increases risks."},{"q":"What is a key aspect to consider when defining a Generative AI strategy for software development and code generation?","opts":["Prioritize using the largest possible LLMs regardless of cost or integration effort.","Ensure that the selected LLMs can integrate seamlessly with existing IDEs, version control systems, and CI/CD pipelines.","Focus primarily on collecting massive amounts of proprietary code to fine-tune the models internally.","Require all developers to complete advanced certifications on every LLM platform before using them."],"correct":[1],"exp_count":1,"exp":"b) is the correct answer. Developers rely heavily on IDEs (VS Code, IntelliJ), Git, and CI/CD tools. A GenAI strategy will only succeed if the LLMs integrate well into these daily tools (e.g., GitHub Copilot, Cursor, Tabnine, etc.).\n\nWhy not the others?\n\na) and c) focus on size or volume of data, which are secondary to integration and usability.\n\nd) Overemphasizes certifications, which is not a strategic priority."},{"q":"Which of the following statements BEST describes one of the key criteria to select an appropriate LLM for code generation and developer productivity tasks within a software development team?","opts":["A key selection criterion is to choose the LLM with the highest number of parameters, regardless of cost or integration effort.","A key selection criterion involves evaluating the LLM’s licensing model, API pricing, and expected recurring token consumption costs.","A key selection criterion is to only consider LLMs that perform well on general knowledge benchmarks such as MMLU or GPQA.","A key selection criterion is to focus exclusively on open-source LLMs to completely avoid any recurring costs."],"correct":[1],"exp_count":1,"exp":"b) is the correct answer. For development teams, factors like API pricing, token costs, and licensing directly impact the total cost of ownership and scalability of using the LLM daily.\n\nWhy not the others?\n\na) and c) focus on model size or general benchmarks, which are secondary.\n\nd) Open-source does not mean zero recurring costs (inference, hosting, maintenance still cost money)."},{"q":"What are the key phases in the adoption of Generative AI in a software development organization?","opts":["Awareness, tool selection, daily usage, and optimization","Discovery, initiation and usage definition, utilization and iteration","Training, pilot projects, full rollout, and maintenance","Requirement gathering, implementation, testing, and deployment"],"correct":[1],"exp_count":1,"exp":"b) is still the correct answer. The adoption journey for Generative AI remains fundamentally the same whether in testing or development:\n\n- Discover potential use cases,\n\n- Initiate and clearly define how it will be used (policies, tools, guidelines),\n\n- Utilize it in real work and continuously iterate/improve.\n\nThis phased approach ensures controlled, responsible, and effective adoption.\n\nWhy not the others?\n\na) and c) are plausible but miss the critical “usage definition” phase.\n\nd) Mirrors a traditional SDLC rather than GenAI adoption."},{"q":"Which of the following options BEST refers to an example of knowledge and/or skills required for developers to work effectively with LLMs in code generation and code review processes?","opts":["Mastering advanced prompt engineering techniques to guide LLMs in producing high-quality, secure, and maintainable code.","Writing perfect unit tests manually for every generated code snippet to ensure correctness.","Deep knowledge of compiler design and low-level optimization techniques.","Selecting the most suitable LLM or AI coding assistant based on factors such as context window size, coding style alignment, integration with the team’s IDE, and licensing model."],"correct":[3],"exp_count":1,"exp":"d) is the correct answer. Just like testers, developers need the ability to evaluate and choose the right LLM/tool for their specific needs (context length, coding accuracy, integration, cost, etc.). This is a key new competency in AI-assisted development.\n\nWhy not the others?\n\na) Prompt engineering is useful, but the question asks for a broad “knowledge and/or skills” example. Selection capability is more strategic.\n\nb) and c) are either too traditional or unrelated to LLM-specific skills."},{"q":"What is the BEST approach for cultivating skills within development teams to support the adoption of Generative AI for code generation and code review?","opts":["Send all developers to intensive external bootcamps and expect them to start using AI coding tools for every task immediately.","Allow developers to experiment freely with any AI coding assistant without any guidelines or structured learning path.","Implement a gradual, hands-on learning program that includes practical coding exercises, pair programming with AI, internal knowledge-sharing sessions, and communities of practice.","Focus primarily on theoretical webinars and online lectures about how LLMs work, followed by slow integration into daily development work."],"correct":[2],"exp_count":1,"exp":"c) is the correct answer. It promotes sustainable skill development through practice, collaboration, and community support — which is widely regarded as best practice for adopting AI coding tools (e.g., GitHub Copilot, Cursor, etc.).\n\nWhy not the others?\n\na) Too rapid and risky (“at once”).\n\nb) Lacks structure and guidance.\n\nd) Overemphasizes theory over practice."},{"q":"Which of the following answers BEST describes how the roles and responsibilities of developers and development managers are impacted by the widespread adoption of Generative AI for code generation and code review?","opts":["Developers shift their focus from writing code line-by-line to reviewing, refining, and validating AI-generated code.","Development managers shift their focus from managing people and processes to becoming experts in the technical architecture of large language models.","Developers shift their focus entirely to writing prompts instead of doing any coding themselves.","Development managers shift their focus to relying completely on AI tools to replace human developers and reduce team size."],"correct":[0],"exp_count":1,"exp":"a) is the correct answer. It accurately reflects the current industry trend: developers become “AI pair programmers” who spend more time reviewing and improving AI suggestions rather than typing every line of code.\n\nWhy not the others?\n\nb) Managers don’t need to become LLM experts.\n\nc) and d) present extreme and unrealistic views (“entirely” or “completely replace”)."}],"2":[{"q":"Match each type of AI technology (1–4) with its CORRECT description (A–D):\n1. Symbolic AI\n2. Classical machine learning\n3. Deep learning\n4. Generative AI\nA. A data-driven approach that requires data preparation, feature selection, and model training.\nB. Uses rule-based systems and logical rules to mimic human decision-making.\nC. Uses deep learning techniques to create new content by learning and mimicking patterns from training data.\nD. Uses neural networks to automatically learn features from large and complex datasets without manual feature engineering.","opts":["1B, 2A, 3D, 4C","1A, 2B, 3C, 4D","1B, 2D, 3A, 4C","1C, 2A, 3B, 4D"],"correct":[0],"exp_count":1,"exp":"This directly matches syllabus section 1.1.1 (LO GenAI-1.1.1 K1). Symbolic AI = rule-based (B), Classical ML = data-driven with feature selection (A), Deep learning = neural networks that auto-learn features (D), Generative AI = deep learning that creates new content (C).\n\nWhy others are incorrect:\n\nb, c, d mix up the definitions (e.g., assigning rule-based to classical ML or deep learning to symbolic AI)."},{"q":"Which of the following statements BEST explains the role of the context window in Large Language Models (LLMs)?","opts":["It limits the number of tokens the model can process at once, affecting coherence over long inputs such as large test logs.","It determines the exact number of parameters the model was trained on.","It controls the randomness of token prediction during inference.","It converts raw text into high-dimensional vector representations."],"correct":[0],"exp_count":1,"exp":"Syllabus 1.1.2 explicitly states: “the context window refers to the amount of preceding text, measured in tokens, that the model can consider… A larger context window allows the model to maintain coherence over longer passages, for example when analyzing large test logs.” Option a) is the only one that correctly describes this limitation and its practical impact on testing.\n\nWhy others are incorrect:\n\nb) confuses context window with model size/parameters; c) refers to temperature/randomness; d) describes embeddings."},{"q":"Which of the following statements BEST describes tokenization in the context of processing text for LLMs?","opts":["It converts tokens into numerical vectors that capture semantic and syntactic relationships.","It breaks down text into smaller units (tokens) that the model can process while maintaining overall context.","It predicts the next token in a sequence based on learned relationships from the training data.","It automatically learns features from raw data without any human involvement."],"correct":[1],"exp_count":1,"exp":"Syllabus 1.1.2 (HO-1.1.2): “Tokenization… is the process of breaking down text into smaller units called tokens… while maintaining the overall context.” This is the exact definition.\n\nWhy others are incorrect:\n\na) describes embeddings; c) describes inference/next-token prediction; d) describes deep learning in general."},{"q":"In the context of software testing, which of the following statements (i–v) about foundation, instruction-tuned, and reasoning LLMs are CORRECT?\ni. Foundation LLMs are general-purpose models trained on vast datasets and typically require further adaptation for specific test tasks.\nii. Reasoning LLMs are optimized for high-cognitive-load tasks such as multi-step problem-solving and synthesis of defect trends.\niii. Instruction-tuned LLMs are designed exclusively for generating synthetic test data without any prompt engineering.\niv. Foundation LLMs can directly generate test cases from high-level requirements without any additional fine-tuning.\nv. Instruction-tuned LLMs are fine-tuned on prompt-response pairs to better follow human instructions for test-related tasks.","opts":["i, ii, and v","ii, iii, and iv","i, iii, and iv","iii, iv, and v"],"correct":[0],"exp_count":1,"exp":"Syllabus 1.1.3 (LO GenAI-1.1.3 K2):\n\ni → Foundation LLMs are general-purpose and “typically require further adaptation”.\n\nii → Reasoning LLMs emphasize “logical inference, multi-step problem-solving, and synthesis of complex information”.\n\nv → Instruction-tuned LLMs are “fine-tuned using datasets that pair prompts with expected responses”. Exactly matches the syllabus.\n\nWhy others are incorrect:\n\niii and iv are false statements (instruction-tuned are not “exclusively” for synthetic data; foundation models usually need adaptation)."},{"q":"Which of the following statements BEST describes the relationship between multimodal LLMs and vision-language models?","opts":["Vision-language models are a subset of multimodal LLMs that specifically integrate visual and textual information.","Multimodal LLMs are a subset of vision-language models focused only on GUI elements.","Vision-language models and multimodal LLMs are interchangeable terms with identical capabilities.","Multimodal LLMs cannot process images, while vision-language models are limited to text only."],"correct":[0],"exp_count":1,"exp":"Syllabus 1.1.4 (LO GenAI-1.1.4 K2): “Vision-language models, a subset of multimodal LLMs, specifically integrate visual and textual information…”\n\nWhy others are incorrect:\n\nb, c, d reverse the subset relationship or invent false limitations."},{"q":"Which TWO of the following options represent key capabilities of LLMs that are particularly useful for software test tasks?","opts":["Generating synthetic test data with various combinations and boundary values.","Automatically executing all test scripts on the production environment without human oversight.","Identifying ambiguities and inconsistencies in requirements or user stories.","Deploying the complete application code to production servers.","Performing fully autonomous exploratory testing of the entire application."],"correct":[0,2],"exp_count":2,"exp":"Syllabus 1.2.1 (LO GenAI-1.2.1 K2) explicitly lists these as key LLM capabilities for test tasks: generating synthetic test data and identifying ambiguities/inconsistencies in requirements.\n\nWhy others are incorrect:\n\nb, d, e describe capabilities beyond current LLM scope in testing (execution/deployment/exploratory testing still require human oversight or additional tools)."},{"q":"Which of the following statements BEST explains the difference between AI chatbots and LLM-powered testing applications in the context of software testing?","opts":["AI chatbots provide conversational interfaces suitable for ad-hoc test tasks, while LLM-powered testing applications are integrated into test tools and processes for specific, customized test tasks.","Both AI chatbots and LLM-powered testing applications are limited to the same ad-hoc interactions and require no configuration.","LLM-powered testing applications focus only on general conversation, while AI chatbots are designed exclusively for automated regression testing.","AI chatbots require no integration with test processes, while LLM-powered testing applications cannot handle conversational prompts."],"correct":[0],"exp_count":1,"exp":"Syllabus 1.2.2 (LO GenAI-1.2.2 K2): “AI chatbots offer conversational interfaces for ad hoc test tasks, while LLM-powered testing applications provide customized solutions for specific test tasks” and are integrated into test tools/processes.\n\nWhy others are incorrect:\n\nb, c, d completely reverse or fabricate the differences described in the syllabus"},{"q":"A tester is writing a prompt to generate test conditions from a user story about a payment processing feature. One sentence in the prompt reads: “You are a senior test analyst with 10 years of experience in e-commerce testing.” In which component of the six-part prompt structure would this sentence MOST LIKELY appear?","opts":["Context","Role","Instruction","Constraints"],"correct":[1],"exp_count":1,"exp":"Syllabus 2.1.1 (LO GenAI-2.1.1 K2): “Role: The role defines the perspective or persona that the GenAI model should take… such as acting as a tester, test manager, or test automation engineer.” The sentence clearly assigns the persona.\n\nWhy others are incorrect: a) Context is background information about the test object; c) Instruction is the task directive; d) Constraints are restrictions."},{"q":"A tester includes the following in a structured prompt for generating regression test cases: “Use only the attached user story, acceptance criteria, and the list of already covered test conditions. Do not invent new requirements.” In which component of the six-part prompt structure would this instruction MOST LIKELY appear?","opts":["Input data","Constraints","Output format","Context"],"correct":[1],"exp_count":1,"exp":"Syllabus 2.1.1 (LO GenAI-2.1.1 K2): “Constraints outline any restrictions or special considerations that the LLM should adhere to.” The sentence explicitly limits what the LLM may use or invent.\n\nWhy others are incorrect: a) Input data is the actual information supplied; c) Output format is about response structure; d) Context is background."},{"q":"Which of the following BEST differentiates prompt chaining, few-shot prompting, and meta prompting techniques?","opts":["Prompt chaining breaks a complex test task into sequential subtasks with human verification between steps; few-shot prompting supplies multiple examples in a single prompt; meta prompting lets the LLM iteratively create or improve its own prompts.","Few-shot prompting breaks tasks into subtasks; prompt chaining supplies examples; meta prompting focuses only on zero-shot generation.","Meta prompting always requires multiple examples; prompt chaining relies on the model refining its own instructions; few-shot prompting is limited to single-step tasks.","Prompt chaining uses only one example; few-shot prompting involves the LLM generating its own prompts; meta prompting is restricted to regression testing."],"correct":[0],"exp_count":1,"exp":"Syllabus 2.1.2 (LO GenAI-2.1.2 K2): Exact definitions — prompt chaining = breaking into sequential steps with checking; few-shot = providing multiple examples; meta prompting = LLM generates/refines its own prompts. Option a) matches verbatim.\n\nWhy others are incorrect: b, c, d reverse or misstate the core differences described in the syllabus."},{"q":"What is the primary function of a system prompt when interacting with an LLM for software testing tasks?","opts":["To provide the specific test data, user stories, or screenshots needed for the current task.","To define the overall behaviour, tone, and rules that the LLM should follow for the entire conversation or session.","To specify the exact output format (e.g., markdown table or Gherkin syntax) for the final response.","To supply real-time user instructions that change with every new query."],"correct":[1],"exp_count":1,"exp":"Syllabus 2.1.3 (LO GenAI-2.1.3 K2): System prompt sets the overall behaviour, tone, and rules for the entire conversation/session.\n\nWhy others are incorrect: a) and d) describe user prompts; c) is part of the six-part structure (output format)."},{"q":"You are applying prompt chaining to generate and refine acceptance criteria for a new “search functionality” user story that has already been reviewed for ambiguities. Which of the following sequences of steps (i–v) should you follow to effectively apply prompt chaining?\ni. Submit the user story to the LLM and ask it to generate initial acceptance criteria.\nii. Provide the generated acceptance criteria back to the LLM and ask it to identify any remaining ambiguities or gaps.\niii. Provide the refined acceptance criteria to the LLM and ask it to generate corresponding test conditions.\niv. Submit the user story directly and ask the LLM to produce both acceptance criteria and test conditions in one step.\nv. Ask the LLM to generate test conditions first, then derive acceptance criteria from them.","opts":["i, ii, and iii","iv and iii","i, iii, and v","ii and iv"],"correct":[0],"exp_count":1,"exp":"Syllabus 2.1.2 & HO-2.1.2b (K2/K3): Prompt chaining breaks the task into intermediate steps with verification/refinement between prompts (generate → check ambiguities → generate test conditions).\n\nWhy others are incorrect: b, c, d either skip verification or reverse the logical order required for chaining."},{"q":"You want to use few-shot prompting to generate Gherkin-style test cases for the following user story and acceptance criterion:\n- User story: “As a registered user, I want to search for products so that I can quickly find items I need.”\n- Acceptance criterion: “When a user enters a valid search term, the system displays a list of matching products sorted by relevance.”You have predefined examples of correct Gherkin test cases from previous features. Which one of the following prompts is BEST suited for this task using few-shot prompting?","opts":["Prompt A Role: Act as a test analyst. Context: You are testing search functionality. Instruction: Generate Gherkin-style test cases for the user story and acceptance criterion. Input Data: <<< user story >>> and <<< acceptance criterion >>>. Constraints: Use best practices. Output Format: Gherkin format.","Prompt B Role: Act as a test analyst specializing in Gherkin test cases. Context: You are testing search functionality. Instruction: Generate Gherkin-style test cases for the user story and acceptance criterion, using the following predefined examples as a guide: << predefined examples >>. Input Data: <<< user story >>> and <<< acceptance criterion >>>. Constraints: Use “Given-When-Then” syntax and ensure alignment with the acceptance criterion. Output Format: Respect the given Gherkin-style test case format.","Prompt C Role: Act as a test analyst. Context: You are testing search functionality. Instruction: Generate at least five Gherkin test cases focusing on edge cases. Input Data: <<< user story >>> and <<< acceptance criterion >>>. Constraints: Use “Given-When-Then” syntax. Output Format: Respect the given Gherkin-style test case format.","Prompt D Role: Act as a test analyst. Context: You are testing search functionality. Instruction: Generate Gherkin-style test cases using the predefined examples. Input Data: <<< user story >>> and <<< acceptance criterion >>>. Constraints: None. Output Format: Any readable format."],"correct":[1],"exp_count":1,"exp":"Syllabus 2.1.2 (LO GenAI-2.1.2 K2) and HO-2.2.2b (H2): Few-shot prompting requires “providing the LLM with examples… using the following predefined examples as a guide” plus explicit constraints on syntax and alignment. Prompt B does exactly this.\n\nWhy others are incorrect: a) and c) lack or weaken the few-shot example requirement; d) removes constraints and examples."},{"q":"You are tasked with applying structured prompting to generate test conditions from a complex user story about a checkout process. Here is an initial draft of the prompt: Role: Act as a test analyst. Context: Analyze the checkout user story. Instruction: Generate test conditions. Input Data: Use the attached user story. Constraints: None. Output Format: List them. Which of the following improvements would BEST align the prompt with structured prompt engineering best practices?","opts":["Add a detailed role (“senior test analyst experienced in payment flows”), expand the instruction to include risk-based prioritization, add constraints on regulatory compliance, and specify output as a prioritized markdown table.","Change the role to “software developer” and remove all constraints.","Make the output format “plain text only” and shorten the instruction to one sentence.","Remove the context and input data sections completely."],"correct":[0],"exp_count":1,"exp":"Syllabus 2.1.1 (LO GenAI-2.1.1 K2) + 2.2.1 (K3): Best practice is to enrich Role, Instruction, Constraints, and Output format for precision, especially for risk-based prioritisation and compliance.\n\nWhy others are incorrect: b, c, d degrade the structure or remove essential components."},{"q":"You are using an LLM to assist in test design for a mobile app login feature. Your goal is to produce complete Gherkin test cases that are consistent, cover positive/negative scenarios, and respect organisational templates. Here is an initial draft of the prompt: Role: Act as a tester. Context: Login feature. Instruction: Generate test cases. Input Data: Use the attached login user story. Constraints: None. Output Format: Gherkin. Which of the following improvements would BEST enhance the LLM’s ability to produce accurate, consistent, and usable test cases?","opts":["Specify the role as “test analyst expert in Gherkin and mobile testing”, add context about the app’s authentication flow, expand the instruction to use few-shot examples and prompt chaining if needed, add constraints on following the company’s Gherkin template, and define output format as a complete feature file.","Remove the output format specification and add more input data.","Change the instruction to “generate code instead of test cases”.","Make the constraints “ignore all examples” and keep everything else the same."],"correct":[0],"exp_count":1,"exp":"Syllabus 2.1.1, 2.1.2, and HO-2.2.2a/2.2.2b (K3/H2): Combines structured prompt + few-shot + clear constraints + precise output format for consistent Gherkin test cases.\n\nWhy others are incorrect: b, c, d weaken or contradict the required structure and techniques."},{"q":"Your goal is to prioritise an existing set of 50 test cases for a high-risk payment module where dependencies and risk levels are known. You can only provide the LLM with the test case list, risk ratings, and dependency matrix. The LLM must produce a prioritised ordered list with justification. Which of the following prompting techniques is BEST suited to achieve your goal in this scenario?","opts":["Zero-shot prompting","Prompt chaining","Meta prompting","Few-shot prompting"],"correct":[1],"exp_count":1,"exp":"Syllabus 2.1.2 (LO GenAI-2.1.2 K2) and 2.2.2 (K3): Prompt chaining is ideal for complex, multi-step tasks requiring decomposition, verification of intermediate results, and ordering (exactly the case for prioritisation with dependencies).\n\nWhy others are incorrect: a) Zero-shot lacks guidance for complex ordering; c) Meta prompting is for prompt optimisation, not direct prioritisation; d) Few-shot is for pattern matching, not sequential processing of 50 items."},{"q":"Which THREE of the following are core prompting techniques explicitly recommended in the syllabus for software testing tasks when combined with the six-part prompt structure?","opts":["Prompt chaining","Temperature tuning","Few-shot prompting","Random seed adjustment","Meta prompting"],"correct":[0,2,4],"exp_count":3,"exp":"Syllabus 2.1.2 (LO GenAI-2.1.2 K2): Explicitly names these three core techniques.\n\nWhy others are incorrect: b) and d) are hyper-parameters, not prompting techniques."},{"q":"A tester wants the LLM to maintain consistent behaviour (e.g., always act as a test analyst and never generate production code) across an entire 30-minute interactive session of test case generation. Which type of prompt should the tester use to achieve this?","opts":["User prompt (updated with every query)","System prompt (set once at the beginning of the session)","Few-shot prompt only","Meta prompt only"],"correct":[1],"exp_count":1,"exp":"Syllabus 2.1.3 (LO GenAI-2.1.3 K2): System prompt defines persistent behaviour for the entire session.\n\nWhy others are incorrect: a) User prompts change per query; c/d) are specific techniques, not session-wide behaviour setters."},{"q":"What is a hallucination in the context of LLM outputs for software testing tasks?","opts":["A logical error where the LLM fails to follow a multi-step reasoning process accurately.","A generation of factually incorrect or fabricated information that is presented as true.","A bias in the LLM output caused by imbalanced training data.","Non-deterministic variation in the same prompt producing different outputs."],"correct":[1],"exp_count":1,"exp":"Syllabus 3.1 (GenAI-3.1.1 K1): “A hallucination is the generation of irrelevant or factually incorrect output by the LLM for a given task.” Option b) is the exact definition.\n\nWhy others are incorrect: a) = reasoning error; c) = bias; d) = non-deterministic behaviour."},{"q":"You are using an LLM to generate test cases for an e-commerce checkout feature. The prompt provides the user story and acceptance criteria, but the LLM output includes the following test case: “Verify that after successful payment, the system sends a confirmation SMS to the user’s registered phone number.” The original acceptance criteria only mention email confirmation. There is no requirement for SMS. Which of the following BEST classifies this output?","opts":["Reasoning error","Hallucination","Bias","Non-deterministic behaviour"],"correct":[1],"exp_count":1,"exp":"Syllabus 3.1.2 (GenAI-3.1.2 K2) + HO-3.1.2: The test case fabricates an SMS requirement that does not exist in the provided acceptance criteria — classic hallucination (inventing facts).\n\nWhy others are incorrect: a) would be incorrect logical steps; c) would require demographic skew; d) would be different outputs for the same prompt."},{"q":"Which of the following statements BEST describes a reasoning error in GenAI outputs?","opts":["The LLM generates content that is factually correct but irrelevant to the test task.","The LLM fails to perform logical inference or multi-step problem-solving correctly.","The LLM produces different outputs for identical prompts due to probabilistic inference.","The LLM output favours certain user demographics based on training data."],"correct":[1],"exp_count":1,"exp":"Syllabus 3.1 (GenAI-3.1.1 K1): “Reasoning errors occur when the LLM fails to perform logical inference, multi-step problem-solving, or chain-of-thought reasoning correctly.”\n\nWhy others are incorrect: a) and d) describe other issues; c) is non-determinism"},{"q":"You have identified hallucinations and reasoning errors in LLM-generated test cases for a banking application. Which THREE of the following techniques are effective mitigation strategies for these issues in software testing tasks?","opts":["Increasing the temperature setting to encourage more creative outputs.","Using chain-of-thought prompting and providing explicit verification steps in the prompt.","Cross-checking LLM outputs against authoritative sources or requirements documents.","Removing all constraints from the prompt to reduce model restrictions.","Applying few-shot examples that demonstrate correct reasoning patterns."],"correct":[1,2,4],"exp_count":3,"exp":"Syllabus 3.1.3 (GenAI-3.1.3 K2): Explicit mitigation techniques include chain-of-thought prompting, providing verification steps, and using few-shot examples that demonstrate correct reasoning. Cross-checking (c) is also valid \n\nWhy others are incorrect: a) and d) actually increase hallucinations/reasoning errors."},{"q":"Which of the following is the BEST way to mitigate the non-deterministic behaviour of LLMs when generating regression test cases?","opts":["Set the temperature to 0 and fix the random seed value.","Increase the context window size.","Use only zero-shot prompting.","Remove the system prompt entirely."],"correct":[0],"exp_count":1,"exp":"Syllabus 3.1.4 (GenAI-3.1.4 K2): “Mitigation of non-deterministic behaviour… can be achieved by setting temperature to 0 and fixing the random seed.”\n\nWhy others are incorrect: b, c, d do not control randomness."},{"q":"Which of the following statements (i–iv) about data privacy and security risks of using Generative AI in software testing are CORRECT?\ni. Submitting production test data containing personal information to a public LLM can lead to data leakage.\nii. Prompt injection attacks can trick the LLM into revealing sensitive test data or system information.\niii. Using private or on-premise LLMs completely eliminates all privacy risks.\niv. Test tools that log prompts and LLM responses may inadvertently store sensitive information.","opts":["i, ii, and iv","i, iii, and iv","ii and iii only","i and iii only"],"correct":[0],"exp_count":1,"exp":"Syllabus 3.2.1 & 3.2.2 (GenAI-3.2.1/3.2.2 K2): All three are explicitly listed risks (production data leakage, prompt injection, logged prompts storing sensitive info). Statement iii is false.\n\nWhy others are incorrect: b, c, d include the false statement iii."},{"q":"In the context of software testing with GenAI, which of the following is an example of a security vulnerability specific to test processes?","opts":["The LLM consumes more energy than traditional test tools.","Prompt injection that causes the LLM to bypass test environment access controls.","The LLM generates biased test data that favours certain user groups.","Non-deterministic outputs causing flaky test results."],"correct":[1],"exp_count":1,"exp":"Syllabus 3.2.2 (GenAI-3.2.2 K2): Prompt injection is a specific security vulnerability in GenAI test tools/processes.\n\nWhy others are incorrect: a) and d) are environmental/non-determinism; c) is bias."},{"q":"You are defining a strategy to protect data privacy and enhance security when using GenAI for test data generation and defect analysis. Which of the following combinations represents the MOST effective mitigation strategies?","opts":["Use only public LLMs with no data filtering and share all test data openly.","Apply data anonymisation/pseudonymisation, use private/on-premise LLMs, implement prompt sanitisation, and enforce strict access controls on prompt logs.","Increase model temperature and rely solely on few-shot prompting for privacy.","Disable all logging and avoid any form of prompt engineering."],"correct":[1],"exp_count":1,"exp":"Syllabus 3.2.3 (GenAI-3.2.3 K2): Mitigation strategies explicitly include data anonymisation, private/on-premise LLMs, prompt sanitisation, and access controls on logs.\n\nWhy others are incorrect: a, c, d increase or ignore the risks."},{"q":"Which of the following statements BEST explains the environmental impact of using Generative AI in software testing?","opts":["GenAI usage has negligible energy consumption compared to manual testing.","Inference tasks (e.g., generating large numbers of test cases) can significantly increase energy consumption and CO₂ emissions, especially with large models and long prompts.","Only the training phase of LLMs contributes to CO₂ emissions; inference has zero impact.","Using GenAI always reduces the overall carbon footprint of testing activities."],"correct":[1],"exp_count":1,"exp":"Syllabus 3.3.1 (GenAI-3.3.1 K2): “The impact of using GenAI on energy consumption and CO₂ emissions… inference tasks can significantly increase energy consumption.”\n\nWhy others are incorrect: a, c, d contradict the syllabus facts."},{"q":"Which of the following is the BEST summary of AI regulations, standards, and best practice frameworks relevant to GenAI in software testing?","opts":["Testers only need to comply with ISO 25010 and can ignore AI-specific regulations.","Relevant frameworks include the EU AI Act, ISO/IEC 42001, and best practices such as data minimisation, transparency, and human oversight.","There are currently no regulations or standards applicable to GenAI in testing.","Only national data protection laws apply; AI-specific standards do not exist."],"correct":[1],"exp_count":1,"exp":"Syllabus 3.4.1 (GenAI-3.4.1 K2): “AI regulations, standards, and best practice frameworks relevant to GenAI in software testing” include the EU AI Act, ISO/IEC 42001, and principles such as transparency, data minimisation, and human oversight.\n\nWhy others are incorrect: a, c, d are false or incomplete."},{"q":"Which of the following BEST describes a key architectural component of an LLM-powered test infrastructure?","opts":["A traditional test management tool that stores only manual test cases.","A vector database that stores embeddings of test artifacts for efficient semantic retrieval.","A rule-based engine that executes test scripts without any GenAI involvement.","A standalone LLM that operates without any external data sources or agents."],"correct":[1],"exp_count":1,"exp":"Syllabus 4.1.1 (LO GenAI-4.1.1 K2): Key architectural components of LLM-powered test infrastructure explicitly include vector databases for storing embeddings of test artifacts (requirements, defects, etc.) to enable semantic retrieval.\n\nWhy others are incorrect: a, c, d describe traditional or incomplete architectures that do not represent the core GenAI-powered components."},{"q":"You are designing an LLM-powered test infrastructure for a large-scale banking application where requirements, user stories, and historical defect reports must be referenced accurately during test case generation. Which of the following architectural approaches is MOST suitable?","opts":["Pure zero-shot prompting with a foundation LLM and no external data retrieval.","Retrieval-Augmented Generation (RAG) that retrieves relevant documents from a vector database before generating test cases.","Fine-tuning the LLM on the entire production database.","Using only an AI chatbot interface without any integration to test tools."],"correct":[1],"exp_count":1,"exp":"Syllabus 4.1.2 (LO GenAI-4.1.2 K2): RAG is the recommended architectural approach when accurate referencing of external documents (requirements, defects) is needed to ground LLM outputs and reduce hallucinations in test case generation.\n\nWhy others are incorrect: a) lacks grounding; c) is not scalable and raises privacy issues; d) is too basic."},{"q":"Which of the following statements BEST describes the role of LLM-powered agents in automating test processes?","opts":["They act as simple chat interfaces for manual test execution.","They can autonomously plan, reason, use tools (such as test execution engines or defect trackers), and complete multi-step test tasks with minimal human intervention.","They are limited to generating static test scripts that must be executed manually.","They replace the need for any test data or requirements documents."],"correct":[1],"exp_count":1,"exp":"Syllabus 4.1.3 (LO GenAI-4.1.3 K2): “The Role of LLM-Powered Agents in Automating Test processes”, agents can plan, reason, call tools (test runners, defect systems), and execute multi-step tasks autonomously.\n\nWhy others are incorrect: a, c, d severely understate or misrepresent agent capabilities."},{"q":"Which of the following statements (i–iv) about Retrieval-Augmented Generation (RAG) in the context of LLM-powered test infrastructure are CORRECT?\ni. RAG improves the accuracy of LLM outputs by retrieving relevant context from external knowledge bases before generation.\nii. RAG eliminates the need for any prompt engineering.\niii. RAG helps reduce hallucinations by grounding the LLM’s responses in verified test artifacts.\niv. RAG requires fine-tuning the LLM on domain-specific data.","opts":["i and iii","ii and iv","i, iii, and iv","i, ii, and iii"],"correct":[0],"exp_count":1,"exp":"Syllabus 4.1.2 (LO GenAI-4.1.2 K2): RAG retrieves relevant context (i) and reduces hallucinations by grounding responses in verified artifacts (iii). Statements ii and iv are false (RAG works with prompt engineering and does not require fine-tuning).\n\nWhy others are incorrect: b, c, d include false statements."},{"q":"What is the primary benefit of fine-tuning an LLM for specific software test tasks (e.g., generating Gherkin test cases for a particular domain)?","opts":["It reduces the context window size required.","It adapts the model to produce more accurate, consistent, and domain-specific outputs without needing extensive prompt engineering for every task.","It completely removes all privacy and security risks.","It makes the model non-deterministic."],"correct":[1],"exp_count":1,"exp":"Syllabus 4.2.1 (LO GenAI-4.2.1 K2): Fine-tuning adapts the model to produce more accurate and consistent outputs for specific test tasks, reducing reliance on extensive prompting.\n\nWhy others are incorrect: a, c, d are incorrect or unrelated benefits/limitations."},{"q":"You are implementing LLMOps practices when deploying and managing LLMs for software testing in a regulated industry. Which TWO of the following are key LLMOps activities that must be considered?","opts":["Continuous monitoring of model performance, drift detection, and automated retraining pipelines.","Manual execution of every generated test case without any automation.","Version control and governance of prompts, fine-tuned models, and retrieved knowledge bases.","Disabling all logging to protect data privacy.","Treating the LLM as a black-box with no observability."],"correct":[0,2],"exp_count":2,"exp":"Syllabus 4.2.2 (LO GenAI-4.2.2 K2): LLMOps includes continuous monitoring, drift detection, automated pipelines, version control, and governance of prompts/models/knowledge bases.\n\nWhy others are incorrect: b, d, e contradict LLMOps principles (automation, observability, governance)."},{"q":"Which of the following BEST describes the difference between fine-tuning and Retrieval-Augmented Generation (RAG) in an LLM-powered test infrastructure?","opts":["Fine-tuning permanently modifies the model weights with domain-specific data, while RAG dynamically retrieves external information at inference time without changing the model.","RAG permanently modifies the model weights, while fine-tuning only retrieves data.","Both techniques permanently change the model and require full retraining each time.","Neither technique can be used together in the same infrastructure."],"correct":[0],"exp_count":1,"exp":"Syllabus 4.1.2 & 4.2.1 (LO GenAI-4.1.2 / 4.2.1 K2): Clear distinction – fine-tuning = permanent weight update; RAG = dynamic retrieval at inference time.\n\nWhy others are incorrect: b, c, d reverse or misrepresent the fundamental difference."},{"q":"In the context of LLM-powered test infrastructure, what is the main purpose of LLMOps?","opts":["To manually review every prompt before it is sent to the LLM.","To operationalise the deployment, monitoring, maintenance, and governance of LLMs and related components in a scalable and reliable way for testing activities.","To replace all human testers with fully autonomous agents.","To limit the use of GenAI to only exploratory testing."],"correct":[1],"exp_count":1,"exp":"Syllabus 4.2.2 (LO GenAI-4.2.2 K2): LLMOps focuses on operationalising, deploying, monitoring, and governing LLMs reliably for testing.\n\nWhy others are incorrect: a, c, d misrepresent the purpose of LLMOps."},{"q":"Which of the following BEST describes the main risk of “Shadow AI” in a test organization?","opts":["Testers openly using approved GenAI tools that are fully governed by the company.","Testers secretly using unapproved public LLMs for test tasks, bypassing security, privacy, and compliance controls.","The official adoption of a company-wide GenAI strategy with full management support.","The use of only small language models (SLMs) that have been pre-approved."],"correct":[1],"exp_count":1,"exp":"Syllabus 5.1.1 (LO GenAI-5.1.1 K2): “Risks of Shadow AI” is explicitly defined as testers using unapproved public LLMs without organisational oversight, leading to serious security, privacy, compliance, and governance risks.\n\nWhy others are incorrect: a) and d) describe approved/governed usage; c) is the opposite of Shadow AI."},{"q":"You are helping a test organization define its Generative AI adoption roadmap. Which of the following sequences of phases (i–iv) represents the CORRECT order of the main phases when adopting Generative AI for software testing?\ni. Pilot projects with selected test tasks and measurement of benefits/risks.\nii. Define a clear GenAI strategy aligned with business and testing goals.\niii. Full-scale rollout across all test teams with updated processes and governance.\niv. Assess current test team skills and identify required upskilling.","opts":["ii → i → iv → iii","i → ii → iii → iv","iv → ii → i → iii","ii → iv → i → iii"],"correct":[3],"exp_count":1,"exp":"Syllabus 5.1.4 (LO GenAI-5.1.4 K2): The syllabus describes a structured adoption roadmap with the logical order: (1) Define strategy, (2) Assess skills and gaps, (3) Run pilots, (4) Full rollout with process changes. Option d) exactly matches this phased approach.\n\nWhy others are incorrect: a, b, c present incorrect or illogical sequences that skip critical assessment or put pilots before strategy definition."},{"q":"Which of the following is the MOST important essential skill that testers must develop when adopting Generative AI?","opts":["Advanced programming skills to fine-tune LLMs from scratch.","The ability to craft effective prompts and critically evaluate LLM outputs for accuracy, relevance, and risks.","Deep knowledge of hardware infrastructure for running large models.","Expertise in training new foundation models on company data."],"correct":[1],"exp_count":1,"exp":"Syllabus 5.2.1 (LO GenAI-5.2.1 K2): “Essential Skills and Knowledge for Testing with Generative AI” highlights prompt engineering and critical evaluation of LLM outputs as the core new competency required for all testers.\n\nWhy others are incorrect: a, c, d describe advanced AI-engineering skills that are not required for testers (these belong to LLMOps or data scientists)."},{"q":"In an AI-enabled test organization, how should test processes evolve to best integrate Generative AI?","opts":["Keep all existing manual test processes unchanged and treat GenAI as an optional extra tool.","Redesign test processes to include GenAI-supported activities (e.g., prompt-based test design, automated review, and agent-driven execution) while maintaining human oversight and governance.","Replace all human testers with fully autonomous LLM agents.","Limit GenAI usage exclusively to test data generation and exclude it from test strategy or planning."],"correct":[1],"exp_count":1,"exp":"Syllabus 5.2.3 (LO GenAI-5.2.3 K2): “Evolving Test Processes in AI-Enabled Test organizations” states that test processes must be redesigned to incorporate GenAI capabilities while preserving human oversight, governance, and quality gates.\n\nWhy others are incorrect: a) ignores integration; c) is unrealistic and against the syllabus (human oversight remains essential); d) is too narrow and contradicts the holistic adoption approach."}],"3":[{"q":"Match each GenAI concept (1–4) with its CORRECT description (A–D):\n1. Embeddings\n2. Non-deterministic behaviour\n3. Small Language Models (SLMs)\n4. Transformer architecture\nA. Compact models with fewer parameters that provide lightweight and focused GenAI solutions for resource-constrained test environments.\nB. Numerical vector representations of tokens that capture semantic and contextual relationships, enabling the model to understand similarities between test terms or requirements.\nC. The probabilistic nature of inference that causes the same prompt to produce varying outputs even under identical conditions.\nD. The neural network design that processes entire sequences in parallel and learns relationships between tokens for coherent text generation.","opts":["1B, 2C, 3A, 4D","1A, 2B, 3D, 4C","1C, 2A, 3B, 4D","1D, 2B, 3C, 4A"],"correct":[0],"exp_count":1,"exp":"This matches syllabus 1.1.2 exactly: embeddings are numerical vectors capturing semantic relationships; non-deterministic behaviour comes from probabilistic inference; SLMs are described as compact models with fewer parameters for lightweight solutions; the transformer model processes sequences and learns token relationships. All four descriptions are taken directly from the syllabus text without overlap from Set B.\n\nWhy others are incorrect:\n\nb, c, d incorrectly assign the definitions (e.g., mixing embeddings with SLMs or non-determinism with transformer architecture)."},{"q":"Which of the following statements BEST explains the importance of embeddings when using LLMs for software testing tasks?","opts":["They limit the amount of text the model can consider at one time.","They convert tokens into high-dimensional vectors so the model can understand semantic similarity between requirements, defects, or test terms.","They control the randomness of the model’s output during test case generation.","They break down input text into smaller units before processing."],"correct":[1],"exp_count":1,"exp":"Syllabus 1.1.2 explicitly defines embeddings as “numerical representations of tokens… in a high-dimensional space, capturing nuanced information about its meaning and usage” and notes that “Tokens with similar meanings… have embeddings that are positioned closely together.” This is critical for test tasks such as linking similar requirements or defect patterns.\n\nWhy others are incorrect:\n\na) describes context window; c) refers to temperature/random seed; d) is the definition of tokenization."},{"q":"Which of the following statements BEST describes the impact of non-deterministic behaviour on software testing when using LLMs?","opts":["It guarantees identical outputs for the same prompt, improving test repeatability.","It can cause the same prompt to generate slightly different test cases or results on different runs, requiring testers to verify consistency.","It only affects the speed of token processing and has no influence on output quality.","It forces the model to always use the same token sequence regardless of temperature settings."],"correct":[1],"exp_count":1,"exp":"Syllabus 1.1.2 states: “LLMs exhibit non-deterministic behavior primarily due to the probabilistic nature of their inference mechanisms… This inherent randomness can lead to variations in outputs even when the same input is provided multiple times.” This is a key limitation testers must manage in repeatable test generation.\n\nWhy others are incorrect:\n\na) is the opposite of non-determinism; c) and d) misrepresent the concept."},{"q":"In the context of software testing, which of the following statements (i–v) about foundation, instruction-tuned, reasoning LLMs and SLMs are CORRECT?\ni. SLMs are preferred in test environments with limited computing resources because they are compact and lightweight.\nii. Reasoning LLMs are specifically trained to excel at multi-step logical inference needed for complex defect analysis.\niii. Foundation LLMs can be used directly for test tasks with no further adaptation required.\niv. Instruction-tuned LLMs are optimised to follow tester instructions more reliably than foundation models.\nv. All LLMs behave deterministically once the prompt is fixed.","opts":["i, ii, and iv","ii, iii, and v","i, iii, and v","iii, iv, and v"],"correct":[0],"exp_count":1,"exp":"Syllabus 1.1.2 and 1.1.3: SLMs = compact and lightweight (i); Reasoning LLMs = structured cognitive abilities and multi-step problem-solving (ii); Instruction-tuned LLMs = fine-tuned on prompt-response pairs for better instruction following (iv). Statements iii and v are false per the syllabus.\n\nWhy others are incorrect:\n\nb, c, d include one or more false statements (iii or v)."},{"q":"Which of the following statements BEST describes the relationship between multimodal LLMs and vision-language models in software testing?","opts":["Vision-language models are a specialised subset of multimodal LLMs that combine visual input (e.g., screenshots) with textual test descriptions.","Multimodal LLMs can only process text, while vision-language models handle images exclusively.","Vision-language models are unrelated to multimodal LLMs and are not used in testing.","Multimodal LLMs and vision-language models are identical in scope and capabilities."],"correct":[0],"exp_count":1,"exp":"Syllabus 1.1.4: “Vision-language models, a subset of multimodal LLMs, specifically integrate visual and textual information…” and the syllabus highlights their use in testing screenshots, GUI wireframes, and defect reports.\n\nWhy others are incorrect:\n\nb, c, d reverse the subset relationship or contradict the syllabus."},{"q":"Which TWO of the following options represent key capabilities of LLMs that are particularly useful for software test tasks?","opts":["Analysing defect reports to detect patterns and trends across test cycles.","Automatically deploying the full application to production.","Generating synthetic test data that respects complex business rules and boundary conditions.","Executing performance tests directly on live systems without any test harness.","Creating automated documentation of test results and traceability matrices."],"correct":[0,2],"exp_count":2,"exp":"Syllabus 1.2.1 (LO GenAI-1.2.1 K2) lists analysing defect patterns and generating synthetic test data as explicit key capabilities. \n\nWhy others are incorrect:\n\nb and d exceed LLM scope and are not listed in the syllabus; e is useful but secondary to the core testing capabilities highlighted."},{"q":"Which of the following statements BEST explains when a tester should prefer an LLM-powered testing application over a simple AI chatbot for software testing activities?","opts":["When the task requires only quick ad-hoc questions with no integration into existing test tools or workflows.","When the task needs deep integration with test management tools, requirements repositories, and automated pipelines for repeatable test generation.","When the tester wants maximum creative freedom without any structured constraints.","When the task involves only conversational entertainment and not actual testing."],"correct":[1],"exp_count":1,"exp":"Syllabus 1.2.2 (LO GenAI-1.2.2 K2): LLM-powered testing applications are integrated into test tools and processes for specific, customised test tasks, while AI chatbots are for ad-hoc conversational use. This distinction is new in phrasing and focus compared with Set B.\n\nWhy others are incorrect:\n\na, c, d reverse the recommended usage or misrepresent the syllabus comparison."},{"q":"A tester is preparing a prompt to analyse a set of logged defects for root-cause patterns. The sentence “Analyse only the defects logged in the last sprint and ignore any defects older than 30 days” appears in the prompt. In which component of the six-part prompt structure would this sentence MOST LIKELY appear?","opts":["Role","Context","Constraints","Output format"],"correct":[2],"exp_count":1,"exp":"Syllabus 2.1.1 explicitly lists “Constraints” as the component that outlines any restrictions or special considerations the LLM must adhere to (e.g., limiting scope to specific data). This is a fresh scenario (defect log analysis) not used in previous packs.\n\nWhy others are incorrect:\n\na) Role defines the persona; b) Context provides background information; d) Output format specifies response structure."},{"q":"Which of the following statements BEST describes the difference between a system prompt and a user prompt when performing test analysis with an LLM?","opts":["The system prompt changes with every new query, while the user prompt remains fixed for the entire session.","The system prompt defines the persistent role, tone, and rules for the whole conversation, while the user prompt supplies the specific test task or data for each interaction.","The system prompt is only used for few-shot examples, while the user prompt is used for meta prompting.","Both prompts serve the same purpose and can be used interchangeably."],"correct":[1],"exp_count":1,"exp":"Syllabus 2.1.3 (LO GenAI-2.1.3 K2) clearly distinguishes: system prompt sets overall behaviour for the session; user prompt provides the actual task/input. New phrasing focused on test analysis.\n\nWhy others are incorrect:\n\na, c, d reverse or confuse the definitions given in the syllabus."},{"q":"Which of the following BEST differentiates meta prompting from prompt chaining and few-shot prompting?","opts":["Meta prompting lets the LLM itself generate, evaluate, and iteratively improve the prompt structure for a test task.","Meta prompting supplies multiple concrete examples within a single prompt.","Meta prompting breaks a large test task into sequential subtasks with verification steps.","Meta prompting is limited to defining output formats only."],"correct":[0],"exp_count":1,"exp":"Syllabus 2.1.2 (LO GenAI-2.1.2 K2) describes meta prompting as the technique where the model is instructed to create or refine its own prompts. This angle (LLM self-improvement) was not covered in previous packs.\n\nWhy others are incorrect:\n\nb = few-shot prompting; c = prompt chaining; d is not mentioned in the syllabus."},{"q":"Which THREE of the following are core prompting techniques that the syllabus recommends for software testing tasks?","opts":["Prompt chaining","Temperature scaling","Few-shot prompting","Random seed adjustment","Meta prompting"],"correct":[0,2,4],"exp_count":3,"exp":"Syllabus 2.1.2 (LO GenAI-2.1.2 K2) explicitly names prompt chaining, few-shot prompting, and meta prompting as the core techniques. The question focuses on the two most practical for test tasks.\n\nWhy others are incorrect:\n\nb and d are hyper-parameter settings, not prompting techniques."},{"q":"You are using prompt chaining to support test monitoring and control for an ongoing agile sprint. The goal is to first identify test coverage gaps, then suggest mitigation actions. Which of the following sequences of steps (i–v) should you follow?\ni. Submit the current test results and coverage report to the LLM and ask it to identify coverage gaps.\nii. Provide the identified gaps back to the LLM and ask it to propose specific mitigation actions.\niii. Submit the full sprint backlog and ask the LLM to generate both gaps and actions in one single prompt.\niv. Ask the LLM to generate mitigation actions first, then derive coverage gaps from them.\nv. Provide the gaps and proposed actions to the LLM for a final consistency check.","opts":["i, ii, and v","iii and ii","i, iv, and v","ii and iii"],"correct":[0],"exp_count":1,"exp":"Syllabus 2.1.2 and 2.2.4 (LO GenAI-2.2.4 K2) describe prompt chaining as breaking complex monitoring/control tasks into sequential steps with verification. The sequence follows the logical flow for test monitoring (identify → act → verify). New scenario (agile sprint monitoring).\n\nWhy others are incorrect:\n\nb and d skip verification or reverse the logical order; c uses incorrect sequence."},{"q":"You want to apply few-shot prompting to generate test conditions for a new “two-factor authentication” feature. You have three high-quality examples of correctly derived test conditions from similar security features. Which one of the following prompts is BEST suited for this few-shot task?","opts":["Prompt A Role: Act as a test analyst. Context: Two-factor authentication feature. Instruction: Generate test conditions using the following examples as a guide: << three examples >>. Input Data: <<< user story and acceptance criteria >>>. Constraints: Follow risk-based prioritisation. Output Format: Numbered list with risk level.","Prompt B Role: Act as a test analyst. Context: Two-factor authentication feature. Instruction: Generate test conditions. Input Data: <<< user story and acceptance criteria >>>. Constraints: None. Output Format: Any format.","Prompt C Role: Act as a test analyst. Context: Two-factor authentication feature. Instruction: Generate at least ten test conditions focusing on edge cases. Input Data: <<< user story and acceptance criteria >>>. Constraints: Use “Given-When-Then”. Output Format: Gherkin only.","Prompt D Role: Act as a test analyst. Context: Two-factor authentication feature. Instruction: Generate test conditions using best practices. Input Data: <<< user story and acceptance criteria >>>. Constraints: None. Output Format: Bullet list."],"correct":[0],"exp_count":1,"exp":"Syllabus 2.1.2 and 2.2.1 (LO GenAI-2.2.1 / 2.1.2 K2) state that few-shot prompting requires providing concrete examples as a guide plus clear constraints and output format. Prompt A does exactly this. New security-feature scenario.\n\nWhy others are incorrect:\n\nb, c, d either lack examples or weaken the few-shot element."},{"q":"You are improving an initial prompt for test design of a complex “order fulfilment” workflow. Initial draft: Role: Act as a tester. Context: Order fulfilment workflow. Instruction: Generate test conditions. Input Data: Use the attached workflow. Constraints: None. Output Format: List. Which of the following improvements BEST aligns with structured prompt engineering best practices for test design?","opts":["Add a precise role, expand the instruction to include risk-based prioritisation and negative scenarios, add constraints on regulatory compliance, and specify output as a prioritised markdown table with traceability.","Remove the context section and shorten the instruction to one sentence.","Change the role to “business analyst” and delete all constraints.","Make the output format “plain paragraph text” only."],"correct":[0],"exp_count":1,"exp":"Syllabus 2.1.1 and 2.2.2 (LO GenAI-2.2.2 K3) recommend enriching Role, Instruction, Constraints, and Output format for complex test design tasks to achieve precision and traceability. New workflow scenario.\n\nWhy others are incorrect:\n\nb, c, d degrade the structure required by the syllabus."},{"q":"You are creating a prompt for automated regression test script generation. Your goal is to produce scripts that are maintainable and follow the organisation’s coding standards. Here is the initial draft: Role: Act as a tester. Context: Regression suite. Instruction: Generate test scripts. Input Data: Use the attached test cases. Constraints: None. Output Format: Code. Which of the following improvements would BEST enhance the quality and usability of the generated scripts?","opts":["Specify the role as “test automation engineer expert in the organisation’s framework”, add context about the tech stack and coding standards, expand the instruction to include maintainability rules, add constraints on using page-object pattern and avoiding hard-coded values, and define output as complete, ready-to-run scripts with comments.","Remove the output format and add more input data.","Change the instruction to “generate documentation instead of scripts”.","Delete all constraints to give the LLM maximum freedom."],"correct":[0],"exp_count":1,"exp":"Syllabus 2.2.3 (LO GenAI-2.2.3 K3) and 2.1.1 emphasise detailed role, context, constraints, and output format for automated regression testing to ensure maintainable, standards-compliant scripts. New automation-focused scenario.\n\nWhy others are incorrect:\n\nb, c, d weaken or contradict the structured approach required."},{"q":"For the task of prioritising a large set of existing test cases based on risk, business impact, and dependencies, which prompting technique is MOST suitable?","opts":["Zero-shot prompting","Prompt chaining","Meta prompting only","Temperature scaling"],"correct":[1],"exp_count":1,"exp":"Syllabus 2.2.5 and 2.1.2 (LO GenAI-2.2.5 K2) recommend prompt chaining for multi-step tasks such as prioritisation that require sequential analysis and verification.\n\nWhy others are incorrect:\n\na is too basic; c is for prompt refinement; d is a hyper-parameter."},{"q":"Which of the following is a metric explicitly recommended in the syllabus for evaluating the results of GenAI on test tasks?","opts":["Model training time","Contextual fit and relevance to the provided test artefacts","Number of tokens used in the prompt","GPU temperature during inference"],"correct":[1],"exp_count":1,"exp":"Syllabus 2.3.1 (LO GenAI-2.3.1 K2) lists metrics such as contextual fit, relevance, accuracy, and completeness for evaluating GenAI outputs on test tasks.\n\nWhy others are incorrect:\n\na, c, d are not evaluation metrics for test-task results."},{"q":"A tester notices that an LLM repeatedly generates incomplete test conditions for a payment feature. Which technique for iteratively refining prompts is MOST effective to address this?","opts":["Increasing the temperature setting","Adding explicit verification steps and chain-of-thought instructions in the prompt","Shortening the prompt length","Removing the output format specification"],"correct":[1],"exp_count":1,"exp":"Syllabus 2.3.2 (LO GenAI-2.3.2 K2) recommends chain-of-thought and explicit verification steps as key techniques for iteratively refining prompts and reducing incomplete outputs. New payment-feature scenario.\n\nWhy others are incorrect:\n\na increases variability; c and d reduce prompt quality."},{"q":"What is a hallucination in the context of LLM outputs when used for software testing tasks?","opts":["A logical error where the LLM fails to follow a multi-step reasoning process accurately.","The generation of factually incorrect or fabricated information presented as if it were true.","A systematic bias in the output caused by imbalanced training data.","Variation in outputs caused by changes in temperature settings."],"correct":[1],"exp_count":1,"exp":"Syllabus 3.1.1 (LO GenAI-3.1.1 K1) defines a hallucination as “the generation of irrelevant or factually incorrect output by the LLM for a given task.” This is the exact definition, presented in a fresh testing context.\n\nWhy others are incorrect:\n\na) describes reasoning error; c) describes bias; d) describes non-deterministic behaviour."},{"q":"You are using an LLM to generate test conditions for a healthcare patient portal feature. The prompt includes only the user story and acceptance criteria about secure login. The LLM output includes this test condition: “Verify that after login the system automatically displays the patient’s full medical history from the national health database.” The provided acceptance criteria mention only “display basic profile information” and make no reference to medical history or external databases. Which of the following BEST classifies this output?","opts":["Reasoning error","Hallucination","Bias","Non-deterministic behaviour"],"correct":[1],"exp_count":1,"exp":"Syllabus 3.1.2 (LO GenAI-3.1.2 K2) classifies this as a hallucination because the LLM invented a requirement (access to national health database and full medical history) that does not exist in the input. New healthcare scenario.\n\nWhy others are incorrect:\n\na) would require incorrect logical steps from existing information; c) would involve demographic skew; d) would be different outputs for the same prompt."},{"q":"Which of the following statements BEST describes a reasoning error in GenAI outputs for software testing?","opts":["The LLM produces content that is factually correct but irrelevant to the given test task.","The LLM fails to perform correct logical inference or multi-step problem-solving on the provided test artefacts.","The LLM generates different outputs for identical prompts due to probabilistic inference.","The LLM output favours certain user groups based on patterns in the training data."],"correct":[1],"exp_count":1,"exp":"Syllabus 3.1.1 (LO GenAI-3.1.1 K1) defines reasoning errors as failures in logical inference, multi-step problem-solving, or chain-of-thought reasoning.\n\nWhy others are incorrect:\n\na) and d) describe other risk categories; c) is non-deterministic behaviour."},{"q":"You have observed hallucinations and reasoning errors in LLM-generated test data for a financial trading system. Which TWO of the following techniques are effective mitigation strategies specifically recommended for software testing tasks?","opts":["Increasing the temperature setting to make outputs more diverse.","Using Retrieval-Augmented Generation (RAG) to ground outputs in verified requirements and defect logs.","Applying chain-of-thought prompting combined with explicit verification steps against source documents.","Removing all constraints from the prompt to allow maximum creativity.","Using few-shot examples that demonstrate correct reasoning and fact-checking patterns."],"correct":[1,2],"exp_count":2,"exp":"Syllabus 3.1.3 (LO GenAI-3.1.3 K2) lists RAG and chain-of-thought prompting with verification as key mitigation techniques for hallucinations and reasoning errors in test tasks. New financial trading scenario.\n\nWhy others are incorrect:\n\na) and d) increase the risk; e) is useful but the syllabus highlights RAG and chain-of-thought as primary for this context."},{"q":"Which of the following is the MOST effective way to mitigate non-deterministic behaviour of LLMs when generating test conditions that must be repeatable across test runs?","opts":["Set the temperature parameter to 0 and fix the random seed value.","Increase the context window size significantly.","Use only zero-shot prompting without any examples.","Remove the system prompt for every new session."],"correct":[0],"exp_count":1,"exp":"Syllabus 3.1.4 (LO GenAI-3.1.4 K2) states that non-deterministic behaviour can be mitigated by setting temperature to 0 and fixing the random seed.\n\nWhy others are incorrect:\n\nb, c, d do not control randomness."},{"q":"Which of the following statements (i–iv) about data privacy and security risks when using Generative AI in software testing are CORRECT?\ni. Sending production-like test data containing personally identifiable information to a public LLM can result in unintended data leakage.\nii. Prompt injection attacks can cause the LLM to reveal sensitive test environment credentials or internal system details.\niii. Using only private on-premise LLMs completely eliminates all privacy and security risks.\niv. Test tools that automatically log prompts and LLM responses may store sensitive information in audit trails.","opts":["i, ii, and iv","i, iii, and iv","ii and iii only","i and iii only"],"correct":[0],"exp_count":1,"exp":"Syllabus 3.2.1 & 3.2.2 (LO GenAI-3.2.1 / 3.2.2 K2) explicitly list data leakage from production-like data, prompt injection, and risks from logged prompts. Statement iii is false. New scenario covering test environment credentials.\n\nWhy others are incorrect:\n\nb, c, d include the false statement iii."},{"q":"In the context of software testing with GenAI, which of the following is an example of a security vulnerability specific to test processes and tools?","opts":["The LLM consuming more electricity than traditional test execution tools.","A prompt injection attack that causes the LLM to bypass test environment access controls or leak API keys.","The LLM generating test data that is biased toward certain user demographics.","Non-deterministic outputs causing flaky test results in CI/CD pipelines."],"correct":[1],"exp_count":1,"exp":"Syllabus 3.2.2 (LO GenAI-3.2.2 K2) identifies prompt injection as a specific security vulnerability in GenAI test tools and processes.\n\nWhy others are incorrect:\n\na) is environmental impact; c) is bias; d) is non-determinism."},{"q":"You are defining mitigation strategies to protect data privacy and enhance security when using GenAI for generating synthetic test data in a regulated insurance application. Which of the following combinations represents the MOST effective set of mitigation strategies?","opts":["Use only public LLMs, share all test data openly, and disable prompt logging.","Apply data anonymisation and pseudonymisation techniques, use private/on-premise LLMs or secure APIs, implement prompt sanitisation and input validation, and enforce strict access controls and audit logging on prompt history.","Increase model temperature and rely solely on few-shot prompting.","Turn off all logging and avoid any form of prompt engineering or constraints."],"correct":[1],"exp_count":1,"exp":"Syllabus 3.2.3 (LO GenAI-3.2.3 K2) lists exactly these mitigation strategies: anonymisation, private LLMs, prompt sanitisation, and access controls. New regulated insurance scenario.\n\nWhy others are incorrect:\n\na, c, d increase or ignore the risks described in the syllabus."},{"q":"Which of the following statements BEST explains the environmental impact of using Generative AI in software testing?","opts":["GenAI inference for large-scale test case generation has negligible energy consumption.","Running inference on large models with long prompts and high token volumes can significantly increase energy consumption and CO₂ emissions.","Only the initial training phase of LLMs contributes to CO₂ emissions; inference has no environmental impact.","Using GenAI always lowers the overall carbon footprint of the testing process."],"correct":[1],"exp_count":1,"exp":"Syllabus 3.3.1 (LO GenAI-3.3.1 K2) states that inference tasks (especially with large models and long prompts) can significantly increase energy consumption and CO₂ emissions.\n\nWhy others are incorrect:\n\na, c, d contradict the syllabus facts."},{"q":"Which of the following is the BEST summary of AI regulations, standards, and best practice frameworks relevant to GenAI use in software testing?","opts":["Testers only need to follow ISO 25010 and can ignore all AI-specific regulations.","Relevant frameworks include the EU AI Act (risk classification), ISO/IEC 42001 for AI management systems, and best practices such as transparency, data minimisation, human oversight, and accountability.","There are currently no regulations or standards that apply to GenAI in testing activities.","Only national data protection laws apply; no AI-specific standards exist."],"correct":[1],"exp_count":1,"exp":"Syllabus 3.4.1 (LO GenAI-3.4.1 K2) explicitly mentions the EU AI Act, ISO/IEC 42001, and best practices including transparency, data minimisation, and human oversight.\n\nWhy others are incorrect:\n\na, c, d are incomplete or false according to the syllabus."},{"q":"Which of the following BEST describes the role of a vector database in an LLM-powered test infrastructure?","opts":["It stores only executable test scripts in traditional format.","It stores embeddings of test artefacts (requirements, defects, logs) to enable semantic search and retrieval.","It executes test scripts automatically without any LLM involvement.","It replaces the need for any prompt engineering or fine-tuning."],"correct":[1],"exp_count":1,"exp":"Syllabus 4.1.1 (LO GenAI-4.1.1 K2) states that a key architectural component is a vector database that stores embeddings of test artefacts for efficient semantic retrieval. New scenario focused on infrastructure building blocks.\n\nWhy others are incorrect:\n\na, c, d describe traditional or unrelated components not mentioned in the syllabus."},{"q":"You are designing an LLM-powered test infrastructure for a mobile banking app where accurate referencing of user stories, API specifications, and past defect reports is critical during test case generation. Which of the following architectural approaches is MOST suitable?","opts":["Pure zero-shot prompting with a foundation LLM and no external retrieval.","Retrieval-Augmented Generation (RAG) combined with a vector database containing embeddings of all test artefacts.","Fine-tuning the LLM once on the entire production database and never updating it.","Using only a basic AI chatbot interface without integration to any test repositories."],"correct":[1],"exp_count":1,"exp":"Syllabus 4.1.2 (LO GenAI-4.1.2 K2) recommends RAG as the architectural approach that retrieves relevant context from external knowledge bases (via vector DB) before generation, improving accuracy and reducing hallucinations. Fresh mobile banking scenario.\n\nWhy others are incorrect:\n\na) lacks grounding; c) is not scalable and raises privacy issues; d) is too basic."},{"q":"Which of the following statements BEST describes the role of LLM-powered agents in an LLM-powered test infrastructure?","opts":["They act only as simple conversational interfaces for manual test execution.","They can autonomously plan multi-step test tasks, call external tools (test runners, defect trackers), and complete complex workflows with minimal human intervention.","They are limited to generating static test scripts that must always be executed manually.","They replace the need for any requirements documents or test data."],"correct":[1],"exp_count":1,"exp":"Syllabus 4.1.3 (LO GenAI-4.1.3 K2) describes LLM-powered agents as capable of planning, reasoning, using tools, and automating multi-step test processes.\n\nWhy others are incorrect:\n\na, c, d understate or misrepresent agent capabilities as per the syllabus."},{"q":"Which of the following statements (i–iv) about Retrieval-Augmented Generation (RAG) in LLM-powered test infrastructure are CORRECT?\ni. RAG dynamically retrieves relevant test artefacts before generating responses, improving factual accuracy.\nii. RAG permanently modifies the underlying LLM weights with domain data.\niii. RAG helps reduce hallucinations by grounding outputs in verified requirements or defect logs.\niv. RAG requires no prompt engineering and works with any foundation model.","opts":["i and iii","ii and iv","i, ii, and iii","i, iii, and iv"],"correct":[0],"exp_count":1,"exp":"Syllabus 4.1.2 (LO GenAI-4.1.2 K2) states that RAG retrieves context (i) and reduces hallucinations by grounding responses (iii). Statements ii and iv are false.\n\nWhy others are incorrect:\n\nb, c, d include one or more false statements."},{"q":"What is the primary advantage of fine-tuning an LLM specifically for test tasks such as generating compliant test reports?","opts":["It reduces the need for any vector database or external retrieval.","It adapts the model weights so the LLM produces more consistent, domain-specific outputs with less reliance on complex prompts.","It completely eliminates all non-deterministic behaviour.","It makes the model suitable only for exploratory testing."],"correct":[1],"exp_count":1,"exp":"Syllabus 4.2.1 (LO GenAI-4.2.1 K2) explains that fine-tuning adapts the model for specific test tasks, improving consistency and reducing heavy prompt engineering.\n\nWhy others are incorrect:\n\na, c, d are not stated benefits in the syllabus."},{"q":"You are implementing LLMOps practices for an LLM-powered test infrastructure in a safety-critical automotive project. Which TWO of the following are essential LLMOps activities?","opts":["Continuous monitoring of model performance, detection of concept drift, and automated retraining pipelines.","Manual review of every single generated test case without automation.","Version control, governance, and lifecycle management of prompts, fine-tuned models, and knowledge bases.","Disabling all logging and observability features to protect data privacy.","Treating the LLM as a complete black box with no performance metrics."],"correct":[0,2],"exp_count":2,"exp":"Syllabus 4.2.2 (LO GenAI-4.2.2 K2) lists monitoring/drift detection/retraining and version control/governance as core LLMOps activities. New automotive safety-critical scenario.\n\nWhy others are incorrect:\n\nb, d, e contradict LLMOps principles of automation and observability."},{"q":"Which of the following BEST describes the difference between fine-tuning and Retrieval-Augmented Generation (RAG)?","opts":["Fine-tuning permanently updates the model weights with domain data, while RAG retrieves external information dynamically at inference time without changing the model.","RAG permanently updates the model weights, while fine-tuning only retrieves data.","Both techniques permanently change the model weights and require full retraining for every update.","Neither technique can be combined in the same test infrastructure."],"correct":[0],"exp_count":1,"exp":"Syllabus 4.1.2 & 4.2.1 clearly distinguish the two: fine-tuning = permanent weight change; RAG = dynamic retrieval.\n\nWhy others are incorrect:\n\nb, c, d reverse or misrepresent the difference."},{"q":"What is the main purpose of LLMOps in the context of LLM-powered test infrastructure?","opts":["To manually review every prompt before sending it to the LLM.","To operationalise the deployment, monitoring, maintenance, governance, and scaling of LLMs and related components for reliable testing activities.","To replace all human testers with fully autonomous agents.","To restrict GenAI usage to only one specific test phase."],"correct":[1],"exp_count":1,"exp":"Syllabus 4.2.2 (LO GenAI-4.2.2 K2) defines LLMOps as operationalising deployment, monitoring, and governance of LLMs for testing.\n\nWhy others are incorrect:\n\na, c, d misrepresent the purpose."},{"q":"What is the primary risk associated with Shadow AI in a test organization?","opts":["Testers using officially approved and governed GenAI tools.","Testers secretly using unapproved public LLMs, bypassing company security, privacy, and compliance policies.","The organisation running official pilot projects with full management support.","The mandatory use of only small language models (SLMs) across all teams."],"correct":[1],"exp_count":1,"exp":"Syllabus 5.1.1 (LO GenAI-5.1.1 K2) defines Shadow AI as the unauthorised use of public LLMs without organisational oversight.\n\nWhy others are incorrect:\n\na, c, d describe approved or controlled usage."},{"q":"You are helping a test organisation build its Generative AI adoption roadmap. Which of the following sequences of phases represents the CORRECT order according to the syllabus?\ni. Conduct a skills gap assessment and plan upskilling.\nii. Define the overall GenAI strategy aligned with testing goals.\niii. Run pilot projects on selected test tasks and measure outcomes.\niv. Proceed to full-scale rollout with updated processes and governance.","opts":["ii → i → iii → iv","i → ii → iii → iv","iv → i → ii → iii","iii → ii → i → iv"],"correct":[0],"exp_count":1,"exp":"Syllabus 5.1.4 (LO GenAI-5.1.4 K2) describes the adoption roadmap in this logical order: strategy first, then skills assessment, pilots, and full rollout.\n\nWhy others are incorrect:\n\nb, c, d present illogical or reversed sequences."},{"q":"Which of the following is the MOST critical essential skill testers must develop when GenAI is introduced into test organisations?","opts":["Advanced skills to train new foundation models from scratch.","Proficiency in prompt engineering and the ability to critically evaluate and validate LLM outputs for testing purposes.","Deep expertise in managing the hardware infrastructure required to run large models.","Skills to manually execute every test case generated by the LLM."],"correct":[1],"exp_count":1,"exp":"Syllabus 5.2.1 (LO GenAI-5.2.1 K2) identifies prompt engineering and critical evaluation of outputs as the essential new skills for testers.\n\nWhy others are incorrect:\n\na, c, d describe advanced engineering or manual tasks not required for testers."},{"q":"How should test processes evolve in an AI-enabled test organisation according to the syllabus?","opts":["Keep all existing manual processes unchanged and use GenAI only as an optional add-on.","Redesign test processes to incorporate GenAI-supported activities (prompt-based design, agent-driven execution, automated reviews) while maintaining human oversight and governance.","Replace all human testers with fully autonomous LLM agents.","Limit GenAI usage exclusively to generating synthetic test data."],"correct":[1],"exp_count":1,"exp":"Syllabus 5.2.3 (LO GenAI-5.2.3 K2) states that test processes must evolve to integrate GenAI capabilities while preserving human oversight and governance.\n\nWhy others are incorrect:\n\na) ignores integration; c) is unrealistic; d) is too narrow."}]};
const CTAI_PACKS={"1":[{"q":"Which statement BEST illustrates the concept of the AI Effect? Select ONE option.","opts":["Rule-based flight booking systems are now considered legacy software rather than AI","AI-based spam filters often misclassify emails, requiring user corrections","AI-driven chatbots are capable of holding conversations with users","The development of superintelligent AI is widely considered a distant goal"],"correct":[0],"exp_count":1,"exp":"Option A: Correct. Technologies once considered AI (like rule-based systems) are no longer considered as such—this is the essence of the AI Effect.\nOption B: Incorrect. This describes an issue related to accuracy in ML models for email classification. It does not reflect how AI technologies lose their novelty over time. Instead, it highlights challenges in current implementations.\nOption C: Incorrect. This highlights a current AI capability, not the reclassification of past AI as non-AI.\nOption D: Incorrect. This discusses future expectations of AI, not the retrospective downgrading of prior AI achievements."},{"q":"A team at an insurance company is building a claims approval model. During a design review, the lead data scientist suggests using a simple algorithm that splits decisions based on feature thresholds, such as claim amount, customer risk profile, and prior history. Which technology is the data scientist MOST likely referring to? Select ONE option.","opts":["Decision table","Decision tree","High frequency broker","Docker container"],"correct":[1],"exp_count":1,"exp":"Option A: Incorrect. A decision table is a tabular representation of complex decision-making processes, but it does not inherently involve splitting decisions based on feature thresholds in the same way decision trees do.\nOption B: Correct. Decision tree is an ML algorithm that uses a tree-like model of decisions and their possible consequences. It splits decisions based on feature thresholds, such as claim amount, customer risk profile, and prior history, which aligns with the description provided.\nOption C: Incorrect. This term is related to financial trading and is not relevant to the context of building a claims approval model.\nOption D: Incorrect. This is a technology used for packaging and deploying software applications, and it is not related to the decision-making process described."},{"q":"Why are GPUs generally preferred over CPUs for training ML models?  Select ONE option.","opts":["CPUs have more memory than GPUs","GPUs are specifically designed for power efficiency","GPUs offer thousands of cores for parallel processing","CPUs are not compatible with most AI development frameworks"],"correct":[2],"exp_count":1,"exp":"Option A: Incorrect. This statement is misleading. Modern GPUs usually come with a substantial amount of memory, enabling efficient handling of large matrices and tensors crucial for training ML models. The advantage of GPUs is not memory size but their architectural design.\nOption B: Incorrect. This statement is misleading. GPUs are power-hungry under load (e.g., NVIDIA’s high-end GPUs can consume 300W+). What sets GPUs apart is their unique architecture tailored for high-speed parallel computing, not power efficiency.\nOption C: Correct. GPUs support massively parallel processing, making them ideal for ML tasks.\nOption D: Incorrect. Popular AI frameworks like TensorFlow, PyTorch, and Scikit-Learn fully support both CPUs and GPUs, but CPUs run far slower compared to GPUs. Compatibility is not the issue – performance is."},{"q":"A product company is considering an AI as a Service (AIaaS) solution for classifying customer documents. While the team has concerns about limited model transparency and lack of access to training data, they are under time pressure and lack in-house ML expertise. What is the MOST likely reason they would still choose the AIaaS solution? Select ONE option.","opts":["The vendor guarantees the model is fully explainable","AIaaS removes the need for test and validation effort","It allows the team to use advanced AI without developing their own models","The AIaaS solution always comes with built-in compliance with absolutely all legal regulations"],"correct":[2],"exp_count":1,"exp":"Option A: Incorrect. While explainability is important, it is not guaranteed by all AIaaS vendors, and the team has concerns about limited model transparency. Therefore, this is not the most likely reason.\nOption B: Incorrect. AIaaS solutions still require testing and validation to ensure they meet the company's needs and perform as expected. The team would still need to validate the AIaaS solution.\nOption C: Correct. The company lacks in-house ML expertise and is under time pressure, so using an AIaaS solution allows them to leverage advanced AI capabilities without having to develop their own models from scratch. This saves time and resources, making it a practical choice given their constraints.\nOption D: Incorrect. AIaaS solutions do not automatically guarantee compliance with all legal regulations. The company would still need to ensure that the solution meets their specific regulatory requirements."},{"q":"Which of the following BEST describes *flexibility* in an AI-based system? Select ONE option.","opts":["The system uses multiple neural networks in parallel without them conflicting","The system can be used across various devices without retraining","The system can adapt to changes in its environment without manual intervention","The system is transparent in how it makes decisions and changes"],"correct":[2],"exp_count":1,"exp":"Option A: Incorrect. Using multiple neural networks in parallel addresses scalability and performance issues but does not necessarily indicate flexibility. Flexibility involves adapting to new situations or inputs dynamically.\nOption B: Incorrect. Being able to operate effectively across diverse devices is certainly valuable, but this feature focuses more on portability or compatibility rather than flexibility. True flexibility implies adjusting to dynamic environmental conditions.\nOption C: Correct. Flexibility refers to the system's ability to adapt automatically to new conditions or contexts.\nOption D: Incorrect. Transparency, while desirable for accountability and trustworthiness, is distinct from flexibility. Knowing how decisions are made does not equate to adapting dynamically to evolving requirements."},{"q":"An online recruitment platform uses a model trained on historic hiring data. The model consistently scores male candidates higher than equally qualified female candidates. Which type of bias is MOST likely responsible? Select ONE option. a) Algorithmic bias","opts":["Data drift","Complacency bias","Sample bias"],"correct":[2],"exp_count":1,"exp":"Option A: Incorrect. Algorithmic bias refers to biases that arise from the design or implementation of the algorithm itself. While it could be a factor, the description suggests that the bias originates from the data rather than the algorithm.\nOption B: Incorrect. Data drift refers to changes in the data distribution over time, which can affect the model's performance. It does not explain the consistent bias towards male candidates.\nOption C: Incorrect. Complacency bias is when the human accepts recommendations provided by the system and fails to consider inputs from other sources. It does not explain the consistent bias towards male candidates.\nOption D: Correct. Sample bias occurs when the training data used to build the model is not representative of the population it is intended to serve. In this case, the historic hiring data may have been biased towards male candidates, leading the model to learn and perpetuate this bias. This results in the model favoring male candidates over equally qualified female candidates."},{"q":"Which of the following is the BEST example of reward hacking? Select ONE option.","opts":["A model incorrectly classifies some input due to limited training data","A customer satisfaction model penalises negative reviews more than it rewards positives","A test framework fails to run all regression tests","A chatbot begins repeating phrases to increase measured engagement"],"correct":[3],"exp_count":1,"exp":"Option A: Incorrect. Misclassification due to insufficient training data is a common problem in ML, but it does not reward hacking. This is simply a limitation caused by inadequate dataset coverage.\nOption B: Incorrect. Assigning greater penalties to negatives relative to positive reinforcement can lead to imbalanced evaluations, but there is no evidence of the reward hacking here.\nOption C: Incorrect. This is a software testing oversight, not reward hacking.\nOption D: Correct. Reward hacking occurs when the system finds a shortcut to maximise its reward signal, often in unintended ways. This scenario depicts clear reward hacking. The chatbot discovers that repetitive phrasing boosts engagement metrics artificially, thereby maximising its rewards through undesirable behaviour. It achieves higher scores but at the cost of genuine interaction quality."},{"q":"An automotive software company is evaluating whether to use a neural network to control a braking system in an autonomous vehicle. During testing, the AI model occasionally responds differently to identical sensor inputs under identical conditions. Which characteristic MOST likely makes the system unsuitable for this safety-critical application? Select ONE option. a) Explainability","opts":["Adaptability","Non-determinism","Traceability"],"correct":[1],"exp_count":1,"exp":"Option A: Incorrect. Explainability refers to the ability to understand and explain the decisions made by the AI model. While explainability is important for trust and debugging, it is not the primary concern in this scenario.\nOption B: Incorrect. Adaptability refers to the system's ability to adjust to changing conditions or new data. Adaptability can be beneficial in many applications, but it is not the main issue here.\nOption C: Correct. For safety-critical applications, systems must be deterministic, meaning they should produce the same output for the same input every time. The observed variation in identical scenarios is due to non-determinism, which poses a risk when consistent, repeatable decisions are essential.\nOption D: Incorrect. Traceability refers to the ability to track and document the system's behaviour and decisions. While traceability is important for accountability and debugging, it is not the primary concern in this scenario."},{"q":"Which of the following statements BEST describes unsupervised learning? Select ONE option.","opts":["The algorithm learns by using labelled examples of input-output pairs","The model is trained using rewards and punishments based on actions","The algorithm identifies patterns in unlabelled data","The system requires little user intervention during training"],"correct":[2],"exp_count":1,"exp":"Option A: Incorrect. This describes supervised learning. Unsupervised learning does NOT utilise labels. It works on raw, unstructured data to discover hidden patterns and relationships.\nOption B: Incorrect. This describes Reinforcement Learning. This approach involves trial-and-error optimisation guided by feedback signals (rewards/punishments), and it differs fundamentally from unsupervised learning.\nOption C: Correct. Unsupervised learning involves identifying structures or groupings in data without labels.\nOption D: Incorrect. While reduced human involvement can apply to unsupervised learning, it is not a defining trait. Rather, identifying patterns in unlabelled data is the distinguishing feature."},{"q":"A logistics company wants an AI agent to learn how to optimise delivery routes based on real-time traffic, fuel efficiency, and delivery success rates. The model learns by interacting with a simulated environment and receives rewards based on delivery efficiency. Which ML approach is BEST suited for this task? Select ONE option. a) Supervised learning","opts":["Reinforcement learning","Semi-supervised learning","Unsupervised learning"],"correct":[0],"exp_count":1,"exp":"Option A: Incorrect. Supervised learning involves training a model on labelled data to make predictions. It is not suitable here because there are no labelled examples of optimal routes; the agent must learn through interaction.\nOption B: Correct. Reinforcement learning involves an agent learning to make decisions by interacting with an environment and receiving rewards or penalties based on its actions. In the given scenario, the AI agent learns to optimise delivery routes by interacting with a simulated environment and receives rewards based on delivery efficiency. This aligns perfectly with reinforcement learning, where the agent learns through trial and error to maximise its rewards.\nOption C: Incorrect. Semi-supervised learning combines labelled and unlabelled data for training. It is not applicable here since the focus is on learning through interaction and rewards.\nOption D: Incorrect. Unsupervised learning involves finding patterns or structures in unlabelled data. It is not suitable for this task because the goal is to optimise routes based on specific criteria (traffic, fuel efficiency, delivery success rates), which requires a reward-based learning approach."},{"q":"A team is building an AI-based model to recommend personalised workout plans. They have the following options for ML approaches: I. Clustering users based on fitness history. II. Using user preferences and fitness outcomes to train a model. III. Training a model with labelled data showing user goals and resulting improvements. IV. Allowing the model to try different plans and receive feedback on user satisfaction. Which of these options are MOST appropriate for supervised learning? Select ONE option.","opts":["I and III","II and III","I and IV","II and IV"],"correct":[1],"exp_count":1,"exp":"Option A: Incorrect. Option I describes clustering which refers to unsupervised learning.\nOption B: Correct. Option I is unsupervised learning, as it involves grouping users by similarities without predefined labels. Option II involves supervised learning because user preferences act as input features, and fitness outcomes (e.g., weight loss, muscle gain) serve as labelled targets. The model learns to map inputs to known outputs. Option III is supervised learning, as the data is labelled with user goals as inputs and resulting improvements as outputs. The model is trained to predict improvements based on goals. Option IV resembles reinforcement learning, where the model iteratively tries different actions and receives feedback (reward) to guide its learning, rather than learns on labelled data. The correct choice is II and III.\nOption C: Incorrect. Option I describes clustering which refers to unsupervised learning. Option IV is reinforcement learning.\nOption D: Incorrect. Option IV is reinforcement learning."},{"q":"Which of the following BEST describes overfitting in an ML model? Select ONE option.","opts":["The model produces poor results because the dataset has missing values","The model performs well on training data but poorly on unseen data","The model consistently predicts the same output regardless of input","The model fails to identify clear patterns in the training dataset"],"correct":[1],"exp_count":1,"exp":"Option A: Incorrect. This relates to data quality issues (missing values) which can affect model performance, but this is unrelated to overfitting.\nOption B: Correct. Option B exactly matches the definition of overfitting. When a model memorises the training data too closely, including its noise and outliers, it loses the ability to generalise effectively to new, unseen data.\nOption C: Incorrect. This describes underfitting (when a model is too simplistic to capture underlying patterns in the data) or a completely broken model (e.g., predicting a constant value).\nOption D: Incorrect. This indicates underfitting, where the model fails to capture patterns even in the training data."},{"q":"A retail analytics team is troubleshooting poor performance in a customer churn prediction model. On review, they find that the model was trained on data containing inconsistent date formats, several duplicate customer records, and missing values in key fields such as income and location. Which activity was MOST likely neglected or insufficient during the development process? Select ONE option. a) Feature engineering","opts":["Hyperparameter tuning","Model calibration","Data preparation"],"correct":[2],"exp_count":1,"exp":"Option A: Incorrect. Feature engineering involves selecting and extracting features to improve model performance. While feature engineering is important, the issues described are more related to data quality and preparation.\nOption B: Incorrect. Hyperparameter tuning involves optimising the parameters of the model to improve its performance. It is not directly related to the issues of inconsistent data formats, duplicates, or missing values.\nOption C: Incorrect. Model calibration involves adjusting the model's predictions to better match the true outcomes. It is not directly related to the issues described.\nOption D: Correct. The presence of inconsistencies, duplicates, and missing values suggests that the data preparation step, which includes cleaning and transforming input data, was incomplete or insufficient."},{"q":"Which of the following BEST describes a dataset quality issue? Select ONE option.","opts":["The model was trained on a CPU rather than a GPU","The AI service license expired during development","The system failed during integration testing","Some input fields contain invalid values"],"correct":[3],"exp_count":1,"exp":"Option A: Incorrect. This relates to hardware/resource constraints, not data quality.\nOption B: Incorrect. Involves licensing/administrative problems, unrelated to the dataset quality.\nOption C: Incorrect. This describes a system failure during testing, which is an infrastructure/engineering issue.\nOption D: Correct. Inconsistent or invalid data values are clear signs of data quality problems."},{"q":"How does data quality impact the performance of an ML model? Select ONE option.","opts":["It determines whether the model should be supervised or unsupervised","It controls how explainable the model is to users","High-quality data enables better training and more reliable predictions","Data quality only affects the speed of model execution"],"correct":[2],"exp_count":1,"exp":"Option A: Incorrect. The choice between supervised and unsupervised learning depends on the presence or absence of labels in the dataset, not the overall quality of the data\nOption B: Incorrect. Explainability is largely dependent on the model architecture and techniques applied (e.g., interpretable vs. black box models). Data quality does not directly control this aspect.\nOption C: Correct. Good data quality improves the training process and leads to better model generalisation and accuracy.\nOption D: Incorrect. While poor data quality can indirectly slow down preprocessing steps, it primarily impacts model accuracy and robustness, not execution speed."},{"q":"A team developing a voice assistant wants to build a supervised learning model that identifies user intent from spoken commands. During data preparation, they assign the correct intent (e.g., \"play music\", \"set alarm\") to each recorded utterance. Which activity are they performing? Select ONE option. a) Data labelling","opts":["Dataset anonymisation","Feature selection","Concept drift detection"],"correct":[],"exp_count":1,"exp":"Option A: Correct. Data labelling involves assigning labels or categories to data points. In this case, the team is assigning the correct intent (e.g., \"play music\", \"set alarm\") to each recorded utterance.\nOption B: Incorrect. Dataset anonymisation refers to the process of removing or obscuring personally identifiable information from a dataset. It is not relevant to the scenario described.\nOption C: Incorrect. This involves choosing the most relevant features from the data to use in the model. It is not the primary activity described.\nOption D: Incorrect. Concept drift detection refers to detecting changes in the underlying data distribution over time. It is not relevant to the scenario described."},{"q":"You are evaluating a binary classification model. The confusion matrix shows: - True Positives: 80 - False Positives: 20 - True Negatives: 70 - False Negatives: 30 Which of the following formulas corresponds to the Recall metric? Select ONE option.","opts":["80 / (80 + 20) * 100","80 / (80 + 30) * 100","(80 + 70) / (80 + 20 + 70 + 30) * 100","2 × (80 / (80 + 20)) × (80 / (80 + 30)) / [(80 / (80 + 20)) + (80 / (80 + 30))]"],"correct":[1],"exp_count":1,"exp":"Option A: Incorrect. It is the formula for the Precision calculation, not Recall.\nOption B: Correct. Recall = TP / (TP + FN) or in our case  80 / (80 + 30)  100\nOption C: Incorrect. This corresponds to the Accuracy, not Recall.\nOption D: Incorrect. The formula represents the F1-score, which is the harmonic mean of Precision and Recall."},{"q":"A real estate firm is testing an AI model that segments property listings into market categories based on patterns in features like location, size, and historical sale price. The QA team is evaluating how well these groupings reflect meaningful distinctions between different property types, as well as how internally consistent each group is. Which type of metric is MOST appropriate for this evaluation? Select ONE option. a) Classification accuracy","opts":["Confusion matrix","Regression metrics","Clustering performance metrics"],"correct":[2],"exp_count":1,"exp":"Option A: Incorrect. This metric is used to evaluate the performance of classification models, which assign data points to predefined classes. It is not suitable for evaluating clustering algorithms.\nOption B: Incorrect. This is a table used to visualise the performance of a classification model. It is not applicable to clustering algorithms.\nOption C: Incorrect. These are used to evaluate the performance of regression models, which predict continuous values. They are not relevant to clustering algorithms.\nOption D: Correct. Clustering performance metrics are used to evaluate the quality of clustering algorithms, which group data points into meaningful clusters. In this case, the AI model is segmenting property listings into market categories based on features like location, size, and historical sale price. Clustering performance metrics, such as silhouette score, can be used to assess how well the groupings reflect meaningful distinctions between different property types and how internally consistent each group is."},{"q":"You are comparing two ML models for fraud detection: - **Model I** has higher precision but lower recall - **Model II** has higher recall but lower precision • Which statement BEST describes the trade-off between the two? Select ONE option.","opts":["Model I detects more frauds but includes many false alarms","Model II minimises false alarms at the cost of missing many fraud cases","Model I prioritises fewer false positives, possibly missing some frauds","Model II has both higher false positives and false negatives"],"correct":[2],"exp_count":1,"exp":"Option A: Incorrect. Precision measures correctness of detected frauds, meaning Model I actually has fewer false alarms compared to Model II.\nOption B: Incorrect. Higher recall implies detecting more fraud cases, not minimising false alarms. False alarm reduction is indicated by higher precision, which Model I possesses.\nOption C: Correct. Higher precision in Model I means it makes fewer false alarms (false positives). Lower recall means it misses more actual frauds (false negatives).This is the textbook trade-off when precision is prioritised over recall.\nOption D: Incorrect. Lower precision in Model II indicates higher false positives, but higher recall signifies fewer false negatives (frauds missed)."},{"q":"A startup is building a handwriting recognition system using a neural network. Their data scientist explains that each input pixel is connected to a unit that applies a weighted sum, adds a bias, and passes the result through an activation function like ReLU. Which concept is the data scientist describing? Select ONE option. a) A visible layer","opts":["A decision tree node","A perceptron","A coverage filter"],"correct":[1],"exp_count":1,"exp":"Option A: Incorrect. This term is not commonly used in the context of neural networks. It may refer to the input layer in some contexts, but it is not the correct term for the described concept.\nOption B: Incorrect. This is a component of decision trees, which are a different type of ML model. Decision trees do not involve weighted sums, biases, or activation functions in the same way as neural networks.\nOption C: Correct. A perceptron is a fundamental unit in neural networks that takes inputs, applies weights and a bias, and passes the result through an activation function (such as ReLU). It is the basic building block of neural networks and is used to perform computations on input data.\nOption D: Incorrect. This term is not commonly used in the context of neural networks or machine learning. It may refer to a filtering mechanism in some contexts, but it is not the correct term for the described concept."},{"q":"Which statement BEST describes the use of coverage measures in testing neural networks? Select ONE option.","opts":["They measure the training coverage time of the neural network model","They evaluate how diverse the training dataset is","They assess the number of different neuron activation patterns during testing","They check for syntax errors in the neural network code"],"correct":[2],"exp_count":1,"exp":"Option A: Incorrect. Coverage measures focus on structural properties, not training duration.\nOption B: Incorrect. Dataset diversity is assessed via data analysis, not coverage measures.\nOption C: Correct. Coverage measures in neural networks quantify how many neurons or paths activate differently during inference. Assessing varied activation patterns reveals whether testing adequately explores the model's possible behaviours.\nOption D: Incorrect. Syntax errors are caught by code compilers/linters, not coverage metrics."},{"q":"A finance firm is developing an AI model to assess creditworthiness. The product owner asks the team to document system expectations such as: input boundaries, acceptable false positive rates, training dataset limitations, and required explanation methods. Which testing-related artefact are they MOST likely working on? Select ONE option. a) Training pipeline","opts":["Model deployment script","Specification for the AI-based system","Concept drift detector"],"correct":[1],"exp_count":1,"exp":"Option A: Incorrect. Training pipeline refers to the implementation of data preparation activities to provide input data to support training by an ML algorithm. It does not directly address the system expectations mentioned.\nOption B: Incorrect. This is a script used to deploy the trained model into production. It does not address the system expectations mentioned.\nOption C: Correct. Specification for an AI-based system provides the basis for testers to check whether actual system behaviour aligns with the specified system requirements and design specifications.\nOption D: Incorrect. This is a tool used to detect changes in the data distribution over time. It is not directly related to the system expectations mentioned."},{"q":"What is typically used as *test data* in the context of AI-based system testing? Select ONE option.","opts":["The same data used to train the model for easier comparison","Unseen data not used during training or validation","Random strings of characters in different combinations","A duplicate of the original training dataset with altered labels"],"correct":[1],"exp_count":1,"exp":"Option A: Incorrect. Using the same data for training and testing causes overfitting illusions. The model will likely achieve perfect performance on familiar data, but fails on unknown data.\nOption B: Correct. Test data should be new/unseen data to evaluate how well the model generalises. Separating training/validation and test datasets ensures the model has not encountered the test data previously. This separation evaluates the model's ability to generalise effectively to unfamiliar inputs, giving a realistic assessment of its performance.\nOption C: Incorrect. While generating synthetic data might occasionally be helpful, relying exclusively on arbitrary character sequences ignores the structure and semantics of real-world data. Testing should ideally mirror authentic conditions.\nOption D: Incorrect. Modifying labels does not alter the core characteristics of the data, rendering it less informative for assessing generalisation. The test dataset should ideally differ from the training dataset to ensure fair evaluation."},{"q":"A health insurance chatbot suggests denying coverage for a patient. The support agent later realises the chatbot’s recommendation was clearly flawed, but they had trusted it because \"the AI said so\". Which issue does this MOST clearly illustrate? Select ONE option. a) Automation bias","opts":["Underfitting","Model drift","Feature leakage"],"correct":[],"exp_count":1,"exp":"Option A: Correct. Automation bias occurs when users overly trust or blindly follow AI outputs, even when they are clearly wrong – a major concern in critical domains like healthcare.\nOption B: Incorrect. Underfitting refers to a model that is too simple to capture the underlying patterns in the data, leading to poor performance. It is not relevant to the scenario described.\nOption C: Incorrect. Model drift occurs when the performance of a model degrades over time due to changes in the data distribution. It is not relevant to the scenario described.\nOption D: Incorrect. Feature leakage refers to the inclusion of information in the training data that should not be available at prediction time. It is not relevant to the scenario described."},{"q":"You are testing an ML system for loan approval. Which TWO of the following  statements would MOST likely influence your choice of test approach? Select TWO options.","opts":["The system is based on supervised learning using labelled financial history data","The acceptance criteria are based solely on prediction accuracy","The stakeholders require high explainability and fairness","The system integrates with a legacy loan processing system","The choice can be arbitrary to increase the non-determinism factor"],"correct":[0,2],"exp_count":2,"exp":"Option A: Correct. The form of ML (e.g., supervised learning) and quality expectations (like fairness/explainability) strongly influence the testing approach.\nOption B: Incorrect. Clear metric-focused criteria shape test strategy (e.g., benchmarking against accuracy thresholds). Limiting criteria to accuracy might ignore other critical aspects like fairness or robustness.\nOption C: Correct. The form of ML (e.g., supervised learning) and quality expectations (like fairness/explainability) strongly influence the testing approach.\nOption D: Incorrect. Legacy integration affects system-level testing (e.g., APIs, data flow) but not core ML test strategy.\nOption E: Incorrect. Arbitrary non-determinism contradicts reliable testing principles and is irrelevant."},{"q":"Which of the following scenarios BEST demonstrates *sample bias*? Select ONE option.","opts":["A recommendation engine trained only on data from premium users","A voice assistant that misinterprets words due to noisy input","A classification model that uses incorrectly labelled training data","A test suite that does not include edge cases"],"correct":[0],"exp_count":1,"exp":"Option A: Correct. Restricting training data to a narrow segment (premium users) leads to biased predictions favoring this subgroup.\nOption B: Incorrect. Noise issues affect accuracy but do not inherently demonstrate sample bias.\nOption C: Incorrect. Labelling errors do not indicate sample bias, they reflect annotation mistakes.\nOption D: Incorrect. Missing edge cases reflect inadequate test coverage, not sample bias."},{"q":"A content platform uses an AI model to recommend articles based on user profiles. Testers notice that submitting the same profile multiple times in a row sometimes results in different recommended articles even though the model has not changed and the input is identical. Which characteristic of the AI system MOST likely explains this behaviour? Select ONE option. a) Model drift","opts":["Overfitting","Probabilistic output","Data imbalance"],"correct":[1],"exp_count":1,"exp":"Option A: Incorrect. Model drift occurs when the performance of a model degrades over time due to changes in the data distribution. It is not relevant in this scenario, as the model has not changed.\nOption B: Incorrect. Overfitting occurs when a model is too closely fit to the training data and performs poorly on new, unseen data. It does not explain the variability in recommendations for the same input.\nOption C: Correct. Most probabilistic systems are also non-deterministic, so there may be multiple, valid outcomes from a test with the same set of preconditions and inputs. This makes the definition of expected results more challenging and can cause difficulties.\nOption D: Incorrect. Data imbalance refers to a situation where the training data is not evenly distributed across different classes or categories. It is not relevant in this scenario, as the issue is with the model's output variability, not the training data."},{"q":"A smart home system’s AI behaves inconsistently depending on environmental noise and network load. Testers find it difficult to replicate bugs, as outcomes vary from test to test with identical inputs. Which factor is MOST responsible for these testing challenges? Select ONE option.","opts":["Lack of labelling","Concept drift","Model complexity and probabilistic behaviour","Sample bias"],"correct":[2],"exp_count":1,"exp":"Option A: Incorrect. This refers to the absence of labelled data, which is not relevant to the issue of inconsistent behaviour.\nOption B: Incorrect. Concept drift occurs when the data distribution changes over time, leading to a degradation in model performance. It is not relevant in this scenario, as the issue is with the model's behaviour under varying conditions.\nOption C: Correct. Complex AI-based systems, especially those with probabilistic and non-deterministic components, can exhibit varying outcomes even with identical inputs. Environmental noise and network load can introduce variability in the model's behaviour, making it difficult to replicate bugs consistently.\nOption D: Incorrect. This refers to a bias in the training data that leads to unfair or inaccurate predictions. While it could be a factor, it is not the primary cause of the inconsistent behaviour described."},{"q":"You are defining acceptance criteria for an AI-based system that performs medical image diagnosis. Which TWO criteria are MOST appropriate? Select TWO options.","opts":["The system should be more accurate than an average medical student","The system must produce results interpretable by physicians","The training dataset must include only public-domain images","The system’s predictions should align with at least 85% of expert assessments","The system should only be tested by data scientists"],"correct":[1,3],"exp_count":2,"exp":"Option A: Incorrect. \"Average medical student\" is vague and may not be a sufficiently high bar for a production system.\nOption B: Correct. Medical AI systems require explainability, interpretability and validated performance against human experts.\nOption C: Incorrect. This limits dataset diversity and realism, potentially harming model performance.\nOption D: Correct. Medical AI systems require explainability, interpretability and validated performance against human experts.\nOption E: Incorrect. This excludes clinical practitioners who are ultimate users."},{"q":"A security team tests an image recognition system by subtly altering pixel values in a stop sign photo. The model suddenly classifies it as a speed limit sign – even though the image still looks like a stop sign to humans. Which technique is the team applying? Select ONE option.","opts":["Image inversion","Data augmentation","Adversarial testing","Pairwise testing"],"correct":[2],"exp_count":1,"exp":"Option A: Incorrect. This refers to the process of reversing the colours or values of an image. It is not relevant to the scenario described.\nOption B: Incorrect. Data augmentation involves modifying the training data to improve the model's performance. It is not relevant to the scenario described.\nOption C: Correct. Adversarial testing involves introducing subtle changes to input data (such as altering pixel values in an image) to test the robustness of an ML model. In this case, the team is altering the stop sign photo in a way that causes the model to misclassify it as a speed limit sign, even though the image still looks like a stop sign to humans. This is a classic example of adversarial testing, which is used to identify vulnerabilities in the model's decision-making process.\nOption D: Incorrect. This is a technique used to test combinations of input parameters. It is not relevant to the scenario described."},{"q":"Which of the following is the MAIN purpose of *pairwise testing* in AI-based systems? Select ONE option.","opts":["To test all possible input combinations exhaustively","To ensure the dataset is balanced and unbiased","To optimise test coverage by focusing on combinations of input values","To validate the performance of a trained model"],"correct":[2],"exp_count":1,"exp":"Option A: Incorrect. Pairwise testing is specifically designed to avoid exhaustive testing.\nOption B: Incorrect. This relates to data preprocessing, not test design.\nOption C: Correct. Pairwise testing is a combinatorial technique that efficiently covers all possible value pairs.\nOption D: Incorrect. Pairwise testing primarily addresses input-value combinations, not global model validation."},{"q":"What is the key characteristic of *back-to-back testing* for AI-based systems? Select ONE option.","opts":["Testing multiple output types for a single input","Comparing results from two different systems on the same input","Switching between real and synthetic training data","Validating user feedback after prediction errors"],"correct":[1],"exp_count":1,"exp":"Option A: Incorrect. Back-to-back testing compares outputs from comparable systems, not multiple outputs from a single system.\nOption B: Correct. Back-to-back testing compares outputs from different systems or models to identify inconsistencies.\nOption C: Incorrect. Back-to-back testing compares outputs, not data type switching.\nOption D: Incorrect. Back-to-back testing compares outputs, it does not validate user feedback."},{"q":"A team is using metamorphic testing to validate a job-matching model. They define test inputs and expected relationships. Which of the following metamorphic relations are MOST appropriate? Select TWO options.","opts":["If a candidate gains a new certification, their match score for relevant jobs should increase","If two identical résumés are submitted with names swapped, the match scores should differ","If a job location is changed to a closer city, the match score should increase","If an applicant’s employment history is removed, the score should improve","If job descriptions include more spelling mistakes, all scores should rise"],"correct":[0,2],"exp_count":2,"exp":"Options A, C: Correct. Metamorphic testing checks whether expected changes in input lead to expected changes in output. Gaining a new certification should improve a candidate's qualifications and thus increase their match score for relevant jobs. A job located closer to the candidate's location should be more attractive and thus increase the match score.\nOption B: Incorrect. This relation is not appropriate because identical résumés should result in the same match scores regardless of the names.\nOption D: Incorrect. This relation is counterintuitive because removing employment history would likely decrease the match score, not improve it.\nOption E: Incorrect. This relation is illogical because spelling mistakes in job descriptions should not affect the match scores."},{"q":"What is a defining trait of *exploratory testing* for AI-based systems? Select ONE option.","opts":["Test cases are derived entirely from formal specifications","The tester follows a fixed and approved checklist of test conditions","The tester investigates system behaviour interactively, often using domain expertise","Testing is only performed on pre-deployment models"],"correct":[2],"exp_count":1,"exp":"Option A: Incorrect. This describes specification-based testing.\nOption B: Incorrect. This refers to checklist-based testing.\nOption C: Correct. Exploratory testing is adaptive, unscripted, and relies on the tester’s intuition and domain knowledge.\nOption D: Incorrect. Exploratory testing happens throughout development (including post-deployment monitoring)."},{"q":"A bank uses a black-box deep learning model for credit scoring. It processes structured data (income, debt) and unstructured text (loan application notes). Regulators demand that decisions follow fundamental financial principles (e.g., “higher income must never reduce a credit score”) and match outcomes of their legacy rule-based system. Which of the following test techniques are MOST critical? Select TWO options.","opts":["Back-to-back testing","A/B testing","Metamorphic testing","White-box testing","Usability testing"],"correct":[0,2],"exp_count":2,"exp":"Options A, C: Correct. Back-to-back testing involves comparing the outputs of the new model (the black-box deep learning model) with the outputs of the legacy rule-based system. This ensures that the new model's decisions align with the outcomes of the legacy system, which is a key requirement from the regulators.\nMetamorphic testing involves defining test inputs and expected relationships between them. For example, if a higher income should never reduce a credit score, metamorphic testing can be used to verify that this relationship holds true across different scenarios. This ensures that the model follows fundamental financial principles.\nOption B: Incorrect. This involves comparing two versions of a system to determine which performs better. It is not directly relevant to the scenario described.\nOption D: Incorrect. This involves testing the internal structure and logic of the system. It is not relevant in this scenario, as the model is a black-box deep learning model.\nOption E: Incorrect. This involves evaluating the ease of use and user experience of the system. It is not relevant to the scenario described."},{"q":"A drone company is testing its autonomous flight model. Because flying real drones during early testing is risky and costly, the team simulates weather, GPS signal loss, and obstacle detection in a controlled digital replica of the real-world environment. What type of test environment are they MOST likely using? Select ONE option.","opts":["Production deployment with real telemetry","Shadow environment","Virtual environment","Hybrid cloud platform"],"correct":[2],"exp_count":1,"exp":"Option A: Incorrect. This involves deploying the system in a real-world environment with actual data. It is not relevant to the scenario described.\nOption B: Incorrect. This refers to a parallel environment that mirrors the production environment but does not affect real operations. It is not relevant to the scenario described.\nOption C: Correct. A virtual environment replicates operational conditions without interacting with the real world, enabling safe and repeatable AI testing. In this case, the team is simulating weather, GPS signal loss, and obstacle detection in a controlled digital replica, which is characteristic of a virtual environment.\nOption D: Incorrect. This involves using a combination of computing, storage, and services in different environments. It is not relevant to the scenario described."},{"q":"A large enterprise receives thousands of bug reports each month. Their testing team uses an AI-based tool that groups similar tickets together and highlights recurring failure patterns for prioritisation. How is AI supporting the testing process in this case? Select ONE option.","opts":["By automating test case design","By performing mutation testing","By clustering and analysing defect reports","By generating synthetic training data"],"correct":[2],"exp_count":1,"exp":"Option A: Incorrect. This involves generating test cases automatically. It is not relevant to the scenario described.\nOption B: Incorrect. This involves introducing small changes to the code to test its robustness. It is not relevant to the scenario described.\nOption C: Correct. An AI-based tool groups related bug reports to identify trends. This is defect clustering and analysis, a common AI use case in large-scale testing environments.\nOption D: Incorrect. This involves creating artificial data to train ML models. It is not relevant to the scenario described."},{"q":"What is the MAIN benefit of using AI to generate test cases? Select ONE option.","opts":["It can discover unexpected scenarios based on data and model behaviour","It eliminates the need for any human testers","It guarantees code coverage for all possible inputs","It ensures compliance with regulatory standards"],"correct":[0],"exp_count":1,"exp":"Option A: Correct. AI-generated test cases can uncover edge cases or patterns not obvious through manual test design.\nOption B: Incorrect. AI-assisted testing supplements humans, not replacing them entirely.\nOption C: Incorrect. AI cannot guarantee 100% coverage (especially for infinite input spaces). It improves coverage but does not ensure exhaustiveness.\nOption D: Incorrect. Regulations require interpretation, often beyond AI’s autonomous abilities. AI may support compliance, but is not a primary benefit of test generation."},{"q":"How does AI support *regression test suite optimisation*? Select ONE option.","opts":["By removing functional test cases from the suite","By identifying and prioritising tests based on past defect prediction and impact","By replacing test cases with code snippets","By rewriting outdated documentation automatically"],"correct":[1],"exp_count":1,"exp":"Option A: Incorrect. AI does not remove functional tests arbitrarily.\nOption B: Correct. AI can analyse historical defect data and execution patterns to streamline regression suites effectively.\nOption C: Incorrect. AI generates/optimises test cases, it does not replace them with code snippets.\nOption D: Incorrect. Documentation updates are unrelated to test suite optimisation."},{"q":"A mobile app team uses an AI tool to predict which components are likely to contain defects before writing any new tests. The prediction is based on complexity metrics, past failures, and commit history. What is this technique an example of? Select ONE option.","opts":["Defect seeding","Defect prediction","Data drift detection","Test oracle generation"],"correct":[1],"exp_count":1,"exp":"Option A: Incorrect. This involves intentionally introducing defects into the system to test the effectiveness of the testing process. It is not relevant to the scenario described.\nOption B: Correct. Defect prediction can be used to predict whether a defect is present, how many defects are present, or whether defects can be found. Defect prediction is typically based on source code metrics, process metrics and/or people and organisational metrics.\nOption C: Incorrect. This involves monitoring changes in the data distribution over time. It is not relevant to the scenario described.\nOption D: Incorrect. This involves creating test oracles, which are expected outputs for given inputs. It is not relevant to the scenario described."}]};
const GLOSSARY=[{"term":"Cost of quality","definition":"The total costs incurred on quality activities and issues and often split into prevention costs, appraisal costs, internal failure costs and external failure costs"},{"term":"Coverage","definition":"The degree to which specified coverage items are exercised by a test suite, expressed as a percentage"},{"term":"Debugging","definition":"The process of finding, analysing and removing the causes of failures in a component or system."},{"term":"Defect","definition":"An imperfection or deficiency in a work product where it does not meet its requirements or specifications"},{"term":"Dynamic testing","definition":"Testing that involves the execution of the test item"},{"term":"Error","definition":"A human action that produces an incorrect result"},{"term":"Failure","definition":"An event in which a component or system does not perform a required function within specified limits"},{"term":"QA","definition":"Activities focused on providing confidence that quality requirements will be fulfilled"},{"term":"QC","definition":"Activities designed to evaluate the quality of a component or system"},{"term":"Quality","definition":"The degree to which a work product satisfies stated and implied needs of its stakeholders"},{"term":"Quality management","definition":"The process of establishing and directing a quality policy, quality objectives, quality planning, quality control, quality assurance, and quality improvement for an organisation"},{"term":"Root cause","definition":"A source of a defect such that if it is removed, the occurrence of the defect type is decreased or removed"},{"term":"Static testing","definition":"Testing that does not involve the execution of a test item"},{"term":"Test analysis","definition":"The activity that identifies test conditions by analysing the test basis"},{"term":"Test basis","definition":"The body of knowledge used as the basis for test analysis and design"},{"term":"Test case","definition":"A set of preconditions, inputs, actions (where applicable), expected results and postconditions, developed based on test conditions"},{"term":"Test completion","definition":"The activity that makes testware available for later use, leaves test environments in a satisfactory condition and communicates the results of testing to relevant stakeholders"},{"term":"Test condition","definition":"A testable aspect of a component or system identified as a basis for testing"},{"term":"Test control","definition":"The activity that develops and applies corrective actions to get a test project on track when it deviates from what was planned"},{"term":"Test data","definition":"Data needed for test execution"},{"term":"Test design","definition":"The activity that derives and specifies test cases from test conditions"},{"term":"Test environment","definition":"An environment containing hardware, instrumentation, simulators, software tools, and other support elements needed to conduct a test"},{"term":"Test execution","definition":"The activity that runs a test on a component or system producing actual results"},{"term":"Test implementation","definition":"The activity that prepares the testware needed for test execution based on test analysis and design"},{"term":"Test manager","definition":"The person responsible for project management of testing activities, resources, and evaluation of a test object"},{"term":"Test monitoring","definition":"The activity that checks the status of testing activities, identifies any variances from planned or expected, and reports status to stakeholders"},{"term":"Test object","definition":"The work product to be tested"},{"term":"Test item","definition":"A part of a test object used in the test process"},{"term":"Test objective","definition":"The purpose for testing"},{"term":"Test oracle","definition":"A source to determine an expected result to compare with the actual result of the system under test"},{"term":"Test planning","definition":"The activity of establishing or updating a test plan"},{"term":"Test procedure","definition":"A sequence of test cases in execution order, and any associated actions that may be required to set up the initial preconditions and any wrap up activities post execution"},{"term":"Test process","definition":"The set of interrelated activities comprising of test planning, test monitoring and control, test analysis, test design, test implementation, test execution, and test completion"},{"term":"Test result","definition":"The consequence/outcome of the execution of a test"},{"term":"Test run","definition":"The execution of a test suite on a specific version of the test object"},{"term":"Test suite","definition":"A set of test scripts or test procedures to be executed in a specific test run"},{"term":"Tester","definition":"A person who performs testing"},{"term":"Testing","definition":"The process within the software development lifecycle that evaluates the quality of a component or system and related work products"},{"term":"Testware","definition":"Work products produced during the test process for use in planning, designing, executing, evaluating and reporting on testing"},{"term":"Traceability","definition":"The ability to establish explicit relationships between related work products or items within work products"},{"term":"Validation","definition":"Confirmation by examination that a work product matches a stakeholder's needs"},{"term":"Verification","definition":"Confirmation by examination and through provision of objective evidence that specified requirements have been fulfilled"},{"term":"Alpha testing","definition":"A type of acceptance testing performed in the developer's test environment by roles outside the development organisation"},{"term":"Acceptance testing","definition":"A test level that focuses on determining whether to accept the system"},{"term":"Agile software development","definition":"A group of software development methodologies based on iterative incremental development, where requirements and solutions evolve through collaboration between self-organising cross-functional teams"},{"term":"ATDD","definition":"A collaboration-based test-first approach that defines acceptance tests in the stakeholders' domain language"},{"term":"BDD","definition":"A collaborative approach to development in which the team is focusing on delivering expected behaviour of a component or system for the customer, which forms the basis for testing"},{"term":"beta testing","definition":"A type of acceptance testing performed at an external site to the developer's test environment by roles outside the development organisation"},{"term":"Black-box testing","definition":"Testing based on an analysis of the specification of the component or system"},{"term":"CAT","definition":"A type of acceptance testing performed to verify whether a system satisfies its contractual requirements"},{"term":"Change-related testing","definition":"A type of testing initiated by modification to a component or system"},{"term":"Component integration testing","definition":"The integration testing of components"},{"term":"Component testing","definition":"A test level that focuses on individual hardware or software components"},{"term":"Confirmation testing","definition":"A type of change-related testing performed after fixing a defect to confirm that a failure caused by that defect does not reoccur."},{"term":"CD","definition":"A software engineering approach in which teams produce software in short cycles, ensuring that the software can be reliably released at any time and, following a pipeline through a \"production-like environment\", without doing so manually"},{"term":"CI","definition":"An automated software development procedure that merges, integrates and tests all changes as soon as they are committed"},{"term":"COTS","definition":"A type of product developed in an identical format for a large number of customers in the general market"},{"term":"DDD","definition":"A software development approach that focuses on building software systems that closely align with the business domain they serve"},{"term":"DevOps","definition":"An organisational approach aiming to create synergy by getting development (including testing) and operations to work together to achieve a set of common goals"},{"term":"Driver","definition":"A component or tool that temporarily replaces another component and controls or calls a test item in isolation"},{"term":"FDD","definition":"An iterative and incremental software development process driven from a client-valued functionality (feature) perspective. Feature-driven development is mostly used in Agile software development"},{"term":"FN result","definition":"A test result which fails to identify a defect that is actually present in a test object."},{"term":"FP result","definition":"A test result in which a defect is reported although no such defect actually exists in the test object"},{"term":"Functional testing","definition":"Testing performed to evaluate if a component or system satisfies functional requirements (ISO 24765)"},{"term":"Impact analysis","definition":"The identification of all work products affected by a change, including an estimate of the resources needed to accomplish the change (ISO 24765)"},{"term":"Incremental development model","definition":"A type of software development lifecycle model in which the component or system is developed through a series of increments"},{"term":"Integration testing","definition":"A test level that focuses on interactions between components or systems"},{"term":"Iterative development model","definition":"A type of software development lifecycle model in which the component or system is developed through a series of repeated cycles"},{"term":"Kanban","definition":"A visual management method and agile project management framework that aims to optimise workflow, improve efficiency, and increase transparency in software development and various other industries, originally inspired by the Toyota production system"},{"term":"Lean IT","definition":"A systematic approach to identifying and eliminating waste in processes to deliver more value to customers with fewer resources"},{"term":"Maintenance testing","definition":"Testing the changes to an operational system or the impact of a changed environment to an operational system"},{"term":"Non-functional testing","definition":"Testing performed  to evaluate that a component or system complies with non-functional requirements"},{"term":"OAT","definition":"A type of acceptance testing performed to determine if operations and/or systems administration staff can accept a system"},{"term":"RAT","definition":"A type of acceptance testing performed to determine the compliance of the test object"},{"term":"Regression testing","definition":"A type of change-related testing to detect whether defects have been introduced or uncovered in unchanged areas of the software"},{"term":"Retrospective","definition":"A regular event in which team members discuss results, review their practices, and identify ways to improve"},{"term":"Scrum","definition":"An agile framework for managing and organising software development projects providing a flexible and iterative approach to project management, emphasising collaboration, self-organisation, and continuous improvement"},{"term":"SDLC","definition":"The activities performed at each stage in software development, and how they relate to one another logically and chronologically"},{"term":"Sequential development model","definition":"A type of software development lifecycle model in which a complete system is developed in a linear way of several discrete and successive phases with no overlap between them"},{"term":"Shift-left","definition":"An approach to performing testing and quality assurance activities as early as possible in the software development lifecycle"},{"term":"Sprint","definition":"A short, time-boxed period when a scrum team works to complete a set amount of work of typically lasting two to four weeks"},{"term":"Stub","definition":"A skeletal or special-purpose implementation of a software component, used to develop or test a component that calls or is otherwise dependent on it. It replaces a called component"},{"term":"System integration testing","definition":"The integration testing of systems"},{"term":"System testing","definition":"A test level that focuses on verifying that a system as a whole meets specified requirements"},{"term":"TDD","definition":"A software development technique in which the test cases are developed, automated and then the software is developed incrementally to pass those test cases"},{"term":"Test level","definition":"A specific instantiation of a test process"},{"term":"Test type","definition":"A group of test activities based on specific test objectives aimed at specific characteristics of a component or system"},{"term":"UAT","definition":"A type of acceptance testing performed to determine if intended users accept the system"},{"term":"V-model","definition":"A sequential software development lifecycle model describing a one-for-one relationship between major phases of software development from business requirements specification to delivery, and corresponding test levels from acceptance testing to component testing"},{"term":"White-box testing","definition":"Testing based on an analysis of the internal structure of the component or system"},{"term":"XP","definition":"An Agile software development methodology intended to improve software quality and responsiveness to changing customer requirements"},{"term":"Anomaly","definition":"A condition that deviates from expectation (ISO 24765)"},{"term":"Dynamic testing","definition":"Testing that involves the execution of the test item (ISO 29119-1)"},{"term":"Epic","definition":"A large user story that cannot be delivered as defined within a single iteration or is large enough that it can be split into smaller user stories."},{"term":"Formal review","definition":"A review that follows a defined process with a formally documented output (ISO 20246)"},{"term":"Informal review","definition":"A type of review that does not follow a defined process and has no formally documented output."},{"term":"Inspection","definition":"A type of formal review that uses defined team roles and measurement to identify defects in a work product, and improve the review process and the software development process (ISO 20246)"},{"term":"Moderator","definition":"The person responsible for running review meetings"},{"term":"Requirement specification","definition":"A formal document that defines the requirements, objectives and expectations for a system, product, or service"},{"term":"Review","definition":"A type of static testing in which the quality of a work product or process is evaluated by individuals"},{"term":"Reviewer","definition":"A participant in a review who identifies defects in the work product (ISO 20246)"},{"term":"Scribe","definition":"A person who records information at a review meeting"},{"term":"Static analysis","definition":"The process of evaluating a component or system without executing it, based on its form, structure, content, or documentation (ISO 24765)"},{"term":"Static testing","definition":"Testing that does not involve the execution of a test item"},{"term":"Technical review","definition":"A formal review by technical experts that examine the quality of a work product and identify discrepancies from specifications and standards (IEEE 1028)"},{"term":"User story","definition":"A user or business requirement consisting of one sentence expressed in the everyday or business language which is capturing the functionality a user needs, the reason behind it, any non-functional criteria, and also including acceptance criteria"},{"term":"Walkthrough","definition":"A type of review in which an author leads members of the review through a work product and the members ask questions and make comments about possible issues (ISO 20246)"},{"term":"Acceptance criteria","definition":"The criteria that a work product must satisfy to be accepted by the stakeholders"},{"term":"Black-box test technique","definition":"A test technique based on the specification of a component or system"},{"term":"Boundary value","definition":"A minimum or maximum value of an ordered equivalence partition"},{"term":"Branch","definition":"A transfer of control between two consecutive nodes in the control flow graph of a test item"},{"term":"Branch coverage","definition":"The coverage of branches in a control flow graph"},{"term":"Branch testing","definition":"A white-box test technique in which the test conditions are branches"},{"term":"BVA","definition":"A black-box test technique in which test cases are designed based on boundary values"},{"term":"Checklist-based testing","definition":"An experience-based test technique in which test cases are designed to exercise the items of a checklist"},{"term":"Collaboration-based test approach","definition":"An approach to testing that focuses on defect avoidance by collaborating among stakeholders"},{"term":"Coverage","definition":"The degree to which specified coverage items are exercised by a test suite, expressed as a percentage."},{"term":"Coverage item","definition":"An attribute or combination of attributes derived from one or more test conditions by using a test technique"},{"term":"Decision table testing","definition":"A black-box test technique in which test cases are designed to exercise the combinations of conditions and the resulting actions shown in a decision table"},{"term":"Each Choice coverage","definition":"It is required that test cases exercise each partition from each set of partitions at least once"},{"term":"EP","definition":"A black-box test technique in which test conditions are equivalence partitions exercised by one representative member of each partition (ISO 29119-1)"},{"term":"Equivalence partition","definition":"A subset of the value domain of a variable within a component or system in which all values are expected to be treated the same based on the specification"},{"term":"Error guessing","definition":"A test technique in which tests are derived on the basis of the tester's knowledge of past failures, or general knowledge of failure modes (ISO 29119-1)"},{"term":"Experience-based test technique","definition":"A test technique based on the tester's experience, knowledge and intuition"},{"term":"Exploratory testing","definition":"An approach to testing in which the testers dynamically design and execute tests based on their knowledge, exploration of the test item and the results of previous tests (ISO 29119-1)"},{"term":"Fault attack","definition":"A test technique to evaluate a specific quality characteristic of a test object by attempting to trigger specific failures"},{"term":"Invalid partition","definition":"A partition containing invalid values"},{"term":"Session-based testing","definition":"A test approach in which test activities are planned as test sessions"},{"term":"State transition testing","definition":"A black-box test technique in which test cases are designed to exercise elements of a state transition model (ISO 29119-4)"},{"term":"Statement","definition":"An entity in a programming language, which is typically the smallest indivisible unit of execution"},{"term":"Statement coverage","definition":"The coverage of executable statements"},{"term":"Statement testing","definition":"A white-box test technique in which test cases are designed to execute statements"},{"term":"Test charter","definition":"Documentation of the goal or objective for a test session"},{"term":"Test session","definition":"An uninterrupted period of time spent in executing tests"},{"term":"Test technique","definition":"A procedure used to define test conditions, design test cases, and specify test data"},{"term":"User story","definition":"A user or business requirement consisting of one sentence expressed in the everyday or business language which is capturing the functionality a user needs, the reason behind it, any non-functional criteria, and also including acceptance criteria"},{"term":"Valid partition","definition":"A partition containing valid values"},{"term":"White-box test technique","definition":"A test technique based on the internal structure of a component or system"},{"term":"Actual result","definition":"The behaviour produced/observed when a component or system is tested"},{"term":"CM","definition":"A discipline applying technical and administrative direction and surveillance to identify and document the functional and physical characteristics of a configuration item, control changes to those characteristics, record and report change processing and implementation status, and verify that it complies with specified requirements"},{"term":"Defect management","definition":"The process of recognising, recording, classifying, investigating, fixing and disposing of defects"},{"term":"Defect report","definition":"Documentation of the occurrence, nature, and status of a defect"},{"term":"Entry criteria","definition":"The set of conditions for officially starting a defined task"},{"term":"Exit criteria","definition":"The set of conditions for officially completing a defined task"},{"term":"Expected result","definition":"The observable predicted behaviour of a test item under specified conditions based on its test basis (ISO 29119-1)"},{"term":"Planning poker","definition":"A consensus-based estimation technique, mostly used to estimate effort or relative size of user stories in Agile software development. It is a variation of the Wideband Delphi method using a deck of cards with values representing the units in which the team estimates"},{"term":"Priority","definition":"The level of (business) importance assigned to an item, e.g., defect"},{"term":"Product risk","definition":"A risk that impacts the quality of a product"},{"term":"Project risk","definition":"A risk that impacts project success"},{"term":"Risk","definition":"A factor that could result in future negative consequences"},{"term":"Risk analysis","definition":"The overall process of risk identification and risk assessment"},{"term":"Risk assessment","definition":"The process to examine identified risks and determine the risk level"},{"term":"Risk control","definition":"The overall process of risk mitigation and risk monitoring"},{"term":"Risk identification","definition":"The process of finding, recognising and describing risks (ISO 31000)"},{"term":"Risk impact","definition":"The damage that will be caused if a risk becomes an actual outcome or event"},{"term":"Risk level","definition":"The measure of a risk defined by risk impact and risk likelihood"},{"term":"Risk likelihood","definition":"The probability that a risk will become an actual outcome or event"},{"term":"Risk management","definition":"The process for handling risks (ISO 24765)"},{"term":"Risk matrix","definition":"A matrix that is used during risk assessment to define the level of risk by considering the category of likelihood against the category of impact"},{"term":"Risk mitigation","definition":"The process through which decisions are reached and protective measures are implemented for reducing or maintaining risks to specified levels"},{"term":"Risk monitoring","definition":"The activity that checks and reports the status of known risks to stakeholders"},{"term":"Risk-based testing","definition":"A test approach in which the management, selection, prioritisation, and use of test activities and resources are based on corresponding risk types and risk levels (ISO 29119-1)"},{"term":"Severity","definition":"The degree of impact that a defect has on the development or operation of a component or system"},{"term":"Smoke test","definition":"A test suite that covers the main functionality of a component or system to determine whether it works properly before planned testing begins"},{"term":"Test approach","definition":"The manner of implementing testing tasks"},{"term":"Test completion","definition":"The activity that makes testware available for later use, leaves test environments in a satisfactory condition and communicates the results of testing to relevant stakeholders"},{"term":"Test completion report","definition":"A type of test report produced at completion milestones that provides an evaluation of the corresponding test items against exit criteria"},{"term":"Test control","definition":"The activity that develops and applies corrective actions to get a test project on track when it deviates from what was planned"},{"term":"Test estimation","definition":"An approximation related to various aspects of testing"},{"term":"Test monitoring","definition":"The activity that checks the status of testing activities, identifies any variances from planned or expected, and reports status to stakeholders"},{"term":"Test plan","definition":"Documentation describing the test objectives to be achieved and the means and the schedule for achieving them, organised to coordinate testing activities (ISO 29119-1)"},{"term":"Test planning","definition":"The activity of establishing or updating a test plan"},{"term":"Test progress report","definition":"A type of periodic test report that includes the progress of test activities against a baseline, risks, and alternatives requiring a decision"},{"term":"Test pyramid","definition":"A graphical model representing the relationship of the amount of testing per level, with more at the bottom than at the top"},{"term":"Test reporting","definition":"Collecting and analysing data from testing activities and subsequently consolidating the data in a report to inform stakeholders"},{"term":"Test scope","definition":"A description of the test object and its features to be tested"},{"term":"Test strategy","definition":"A description of how to perform testing to reach test objectives under given circumstances"},{"term":"Testing quadrants","definition":"A classification model of test types/test levels in four quadrants, relating them to two dimensions of test objectives: supporting the product team versus critiquing the product, and technology-facing versus business-facing"},{"term":"Wideband delphi","definition":"An expert-based test estimation technique that aims at making an accurate estimation using the collective wisdom of the team members"},{"term":"Capture/replay","definition":"A test automation approach in which inputs to a test object are recorded during manual testing to generate automated test scripts that can be executed later"},{"term":"Data-driven testing","definition":"A scripting technique that uses data files to contain the test data and expected results needed to execute the test scripts"},{"term":"Keyword-driven testing","definition":"A scripting technique in which test scripts contain high-level keywords and supporting files that contain low-level scripts that implement those keywords"},{"term":"Probe effect","definition":"The effect on the component or system by the measurement instrument when the component or system is being measured, e.g., by a performance testing tool or monitor. For example, performance may be slightly worse when performance testing tools are being used"},{"term":"Test automation","definition":"The conversion of test activities to automatic operation"}];
const CTAI_GLOSSARY=[{"term":"AI","definition":"The capability of an engineered system to acquire, process, create and apply knowledge and skills (ISO/IEC TR 29119-11)"},{"term":"AI component","definition":"A component that provides AI functionality"},{"term":"AI development framework","definition":"A set of tools and libraries designed to help developers create artificial intelligence (AI) and machine learning (ML) applications more easily"},{"term":"AI effect","definition":"The situation when a previously labelled AI system is no longer\nconsidered to be AI as technology advances (ISO/IEC TR 29119-11)"},{"term":"AI-based system","definition":"A system that integrates one or more AI components"},{"term":"AI-specific processor","definition":"A type of specialised hardware designed to accelerate AI applications"},{"term":"AIaaS","definition":"A software licensing and delivery model in which AI and AI\ndevelopment services are centrally hosted"},{"term":"API","definition":"A type of interface in which the components or systems involved exchange information in a defined formal structure"},{"term":"ASIC","definition":"A kind of integrated circuit that is specially built for a specific application or purpose"},{"term":"association","definition":"An unsupervised learning technique that identifies relationships and\ndependencies between samples"},{"term":"AWS","definition":"A subsidiary of Amazon that provides on-demand cloud computing platforms and APIs to individuals, companies, and governments, on a metered, pay-as-you-go basis"},{"term":"Bayesian model","definition":"A statistical model that uses probability to represent the uncertainty of both model inputs and outputs"},{"term":"BERT","definition":"A natural language model based on the transformer architecture, notable for its dramatic improvement over previous state of the art models"},{"term":"case-based reasoning","definition":"The technique of solving a new problem based on the solutions of\nsimilar past problems"},{"term":"chatbot","definition":"An application used to conduct a conversation via text or text-to-speech"},{"term":"classification","definition":"A type of ML function that predicts the output class for a given input\n(After ISO/IEC TR 29119-11)"},{"term":"classifier","definition":"An ML model used for classification"},{"term":"clustering","definition":"A type of ML function that groups similar data points together"},{"term":"clustering algorithm","definition":"A type of ML algorithm used to group similar objects into clusters"},{"term":"CNTK","definition":"An open-source Microsoft deep-learning toolkit"},{"term":"CPU","definition":"A general-purpose processor with a small number of cores that are optimised for low-latency tasks that require single-threaded performance, such as running operating systems, web browsing or office applications"},{"term":"dataset","definition":"A collection of data used for training, evaluation, testing and prediction in ML"},{"term":"DBSCAN","definition":"An ML algorithm which operates on data density. The basic concept is to find areas of high density, which are separated from each other by areas of low density"},{"term":"decision tree","definition":"A tree-like ML model whose nodes represent decisions, and whose branches represent possible outcomes"},{"term":"deductive classifier","definition":"A classifier based on the application of inference and logic to input data"},{"term":"DIN","definition":"German Institute for Standardisation"},{"term":"DL","definition":"ML using neural networks with multiple layers"},{"term":"DNN","definition":"A neural network comprised of several layers of neurons"},{"term":"edge computing","definition":"The part of a distributed architecture in which information processing is performed close to where that information is used"},{"term":"EU","definition":"An international organisation comprising 27 European countries and governing common economic, social, and security policies"},{"term":"feature","definition":"An individual measurable attribute of the input data used for training by an ML algorithm and for prediction by an ML model"},{"term":"fuzzy logic","definition":"A type of logic based on the concept of partial truth represented by certainty factors between 0 and 1"},{"term":"GDPR","definition":"The European Union (EU) regulation on data protection and privacy\nthat applies to the data of citizens of the EU and the European\nEconomic Area"},{"term":"general AI","definition":"AI that exhibits intelligent behaviour comparable to a human across the full range of cognitive abilities (ISO/IEC TR 29119-11)"},{"term":"genetic algorithm","definition":"A search-based algorithm used for solving optimisation problems in machine learning"},{"term":"GPTs","definition":"A type of large language model and a prominent framework for generative artificial intelligence. They are artificial neural networks that are used in natural language processing tasks. GPTs are based on the transformer architecture, pre-trained on large data sets of unlabelled text, and able to generate novel human-like content"},{"term":"GPU","definition":"A specialised processor originally designed to handle graphics-related tasks capable of performing thousands of parallel calculations simultaneously and more efficiently than CPUs, thanks to a large number of smaller cores"},{"term":"IBM","definition":"An American multinational technology company headquartered in Armonk, New York"},{"term":"IEC","definition":"An international standards organisation that prepares and publishes international standards for all electrical, electronic and related technologies – collectively known as \"electrotechnology\""},{"term":"IEEE","definition":"An American professional association for electronics engineering, electrical engineering, and other related disciplines"},{"term":"intelligent agent","definition":"An autonomous program which directs its activity towards achieving\ngoals using observations and actions"},{"term":"ISO","definition":"An independent, non-governmental, international standard development organisation composed of representatives from the national standards organisations of member countries"},{"term":"JTC","definition":"Joint Technical Committee"},{"term":"K-means","definition":"An ML algorithm which attempts to cluster the data into a predetermined number of groups by minimising the distance from the cluster centre to the objects"},{"term":"linear regression","definition":"A statistical technique that models the relationship between variables by fitting a linear equation to the observed data when the target variable is numeric"},{"term":"logistic regression","definition":"A statistical technique that models the relationship between variables when the target variable is categorical rather than numeric"},{"term":"ML","definition":"The process using computational techniques to enable systems to learn from data or experience (ISO/IEC TR 29119-11)"},{"term":"ML framework","definition":"A tool or library that supports the creation of an ML model"},{"term":"ML model","definition":"ML output of an ML algorithm trained with a training dataset that generates predictions using patterns in the input data (ISO/IEC TR 29119-11)"},{"term":"ML model training","definition":"The process of applying the ML algorithm to the training dataset to create an ML model"},{"term":"narrow AI","definition":"AI focused on a single well-defined task to address a specific problem (ISO/IEC TR 29119-11)"},{"term":"neuromorphic processor","definition":"An integrated circuit designed to mimic the biological neurons of the human brain"},{"term":"NLP","definition":"A field of computing that provides the ability to read, understand, and\nderive meaning from natural languages"},{"term":"NPU","definition":"A class of specialised hardware accelerator or computer system designed to accelerate artificial intelligence and machine learning applications, including artificial neural networks and machine vision"},{"term":"pre-trained model","definition":"An ML model already trained when it was obtained"},{"term":"procedural reasoning","definition":"AI technology used for constructing real-time reasoning systems that can perform complex tasks in dynamic environments"},{"term":"random forest","definition":"Ensemble ML technology for classification, regression and other tasks that operate by constructing and running many decision trees and then either outputting the mode of the class or the mean prediction of the individual trees"},{"term":"reasoning technique","definition":"AI that generates conclusions from available information using logical\ntechniques (After ISO/IEC TR 29119-11)"},{"term":"reinforcement learning","definition":"The activity of building an ML model using a process of trial and reward to achieve an objective (After ISO/IEC TR 29119-11)"},{"term":"reward function","definition":"A function that defines the success of reinforcement learning"},{"term":"rule engines","definition":"A set of rules that determine which actions should occur when certain\nconditions are satisfied"},{"term":"SaaS","definition":"A software distribution model in which a cloud provider hosts applications and makes them available to end users over the internet"},{"term":"SC","definition":"Sub Committee"},{"term":"scalable ML","definition":"The ability of a machine learning system to handle ever larger amounts of data and computing resources"},{"term":"search algorithm","definition":"An algorithm that systematically visits a subset of all possible states or structures until the goal state or structure is reached (After ISO/IEC TR 29119-11)"},{"term":"SLA","definition":"A contract between a service provider and its customers that documents what services the provider will furnish and defines the service standards the provider is obligated to meet"},{"term":"SoC","definition":"An integrated circuit that integrates most or all components of a computer or other electronic system"},{"term":"super AI","definition":"An artificial intelligence-based system that far exceeds human\ncapabilities"},{"term":"supervised learning","definition":"Training an ML model from input data and its corresponding labels"},{"term":"SVM","definition":"An ML technique in which the data points are viewed as vectors in multi-dimensional space separated by a hyperplane"},{"term":"technological singularity","definition":"A point in the future when technological advances are no longer controllable by people (After ISO/IEC TR 29119-11)"},{"term":"TPU","definition":"A specialised processor developed by Google specifically to perform highly-optimised operations on tensors, which are multidimensional arrays used in deep learning models"},{"term":"transfer learning","definition":"A technique for modifying a pre-trained ML model to perform a different related task"},{"term":"unsupervised learning","definition":"Training an ML model from input data using an unlabelled dataset"},{"term":"VGG","definition":"An academic group focused on computer vision at Oxford University"},{"term":"von Neumann architecture","definition":"A computer architecture which consists of five main components:\nmemory, a central processing unit, a control unit, input and output"},{"term":"VPU","definition":"A specific type of AI accelerator, designed to accelerate machine vision tasks"},{"term":"adaptability","definition":"The ease with which the system can be modified for new situations, such as different hardware and changing operational environments"},{"term":"algorithmic bias","definition":"A type of bias that occurs when the learning algorithm is incorrectly configured, for example, when it overvalues some data compared to others"},{"term":"autonomy","definition":"The ability of a system to work for sustained periods without human intervention (ISO/IEC TR 29119-11)"},{"term":"bias","definition":"1. The systematic difference in treatment of certain objects, people or groups in comparison to others (ISO/IEC DIS 22989)\n\n2. The statistical measure of the distance between the outputs provided by the system and what are considered to be “fair outputs” which show no favouritism to a particular group"},{"term":"ethics","definition":"A system of accepted beliefs that control behaviour, especially such a system based on morals"},{"term":"evolution","definition":"1. The process of continuous change from a lower, simpler, or worse state to a higher, more complex, or better state\n\n2. The ability of the system to improve itself in response to changing external constraints"},{"term":"explainability","definition":"The level of understanding how the AI-based system came up with a given result (ISO/IEC TR 29119-11)"},{"term":"flexibility","definition":"The ability of a system to work in contexts outside its initial specification (After ISO/IEC TR 29119-11)"},{"term":"G20","definition":"An intergovernmental forum comprising 19 countries and the European Union (EU)"},{"term":"inappropriate bias","definition":"A type of bias that causes a system to produce results that lead to adverse effects for a particular group"},{"term":"interpretability","definition":"The level of understanding how the underlying AI technology works (ISO/IEC TR 29119-11)"},{"term":"ML system","definition":"A system that integrates one or more ML models"},{"term":"OECD","definition":"An intergovernmental organisation with 38 member countries, founded in 1961 to stimulate economic progress and world trade"},{"term":"reward hacking","definition":"The activity performed by an intelligent agent to maximise its reward function to the detriment of meeting the original objective (After ISO/IEC TR 29119-11)"},{"term":"safety","definition":"The expectation that a system does not, under defined conditions, lead to a state in which human life, health, property, or the environment is endangered"},{"term":"sample bias","definition":"A type of bias where the dataset is not fully representative of the data space to which ML is applied"},{"term":"self-learning system","definition":"An adaptive system that changes its behaviour based on learning through trial and error (After ISO/IEC TR 29119-11)"},{"term":"side effect","definition":"A secondary and usually adverse effect"},{"term":"transparency","definition":"The level of visibility of the algorithm and data used by the AI-based system (After ISO/IEC TR 29119-11)"},{"term":"UN","definition":"A diplomatic and political international organisation whose stated purposes are to maintain international peace and security, develop friendly relations among nations, achieve international cooperation, and serve as a centre for harmonising the actions of nations"},{"term":"UNESCO","definition":"A specialised agency of the United Nations (UN) aimed at promoting world peace and security through international cooperation in education, arts, sciences and culture"},{"term":"XAI","definition":"The field of study related to understanding the factors that influence AI system outputs"},{"term":"data acquisition","definition":"The activity of acquiring data relevant to the business problem to be solved by an ML model"},{"term":"data pre-processing","definition":"The activities of data cleaning, data transformation, data augmentation, and data sampling in the ML workflow"},{"term":"data preparation","definition":"The activities of data acquisition, data pre-processing and feature engineering in the ML workflow"},{"term":"EDA","definition":"The interactive, hypothesis-driven and visual exploration of data used to support all data preparation activities (data acquisition, data pre-processing and feature engineering)"},{"term":"epoch","definition":"An iteration of ML training on the whole training dataset"},{"term":"feature engineering","definition":"The activity in which those attributes in the raw data that best represent the underlying relationships that should appear in the ML model are identified for use in the training data (ISO/IEC TR 29119-11)"},{"term":"hyperparameter","definition":"A parameter used to either control the training of an ML model or to set the configuration of an ML model"},{"term":"hyperparameter tuning","definition":"The activity of determining the optimal hyperparameters based on particular goals"},{"term":"ML algorithm","definition":"An algorithm used to create an ML model from a training dataset"},{"term":"ML functional performance criteria","definition":"Criteria based on ML functional performance metrics used as a basis for model evaluation, tuning and testing"},{"term":"ML model deployment","definition":"The process of placing a finished ML model into a live environment where it can be used for its intended purpose"},{"term":"ML model evaluation","definition":"The process of comparing achieved ML functional performance metrics with required criteria and those of other ML models"},{"term":"ML model testing","definition":"The process where the performance of a fully trained ML model is evaluated on an independent testing dataset"},{"term":"ML model tuning","definition":"The process of testing hyperparameters to achieve optimum performance"},{"term":"ML workflow","definition":"A sequence of activities used to manage the development and deployment of an ML model"},{"term":"overfitting","definition":"The generation of an ML model that corresponds too closely to the training dataset, resulting in a model that finds it difficult to generalise to new data (After ISO/IEC TR 29119-11)"},{"term":"regression","definition":"A type of ML function that results in a numerical or continuous output value for a given input (After ISO/IEC TR 29119-11)"},{"term":"training dataset","definition":"A dataset used to train an ML model"},{"term":"underfitting","definition":"The generation of an ML model that does not reflect the underlying trend of the training dataset, resulting in a model that finds it difficult to make accurate predictions (ISO/IEC TR 29119-11)"},{"term":"validation dataset","definition":"A dataset used to evaluate a trained ML model with the purpose of tuning the model"},{"term":"annotation","definition":"The activity of identifying objects in images with bounding boxes to provide labelled data for classification"},{"term":"augmentation","definition":"The activity of creating new data points based on an existing dataset"},{"term":"classification model","definition":"An ML model used for classification"},{"term":"data cleaning","definition":"The activity of data pre-processing when incorrect data, duplicate data or outliers are either removed or corrected, data imputation is used, removal or anonymisation of personal information is performed"},{"term":"data gathering","definition":"The activity of data acquisition when the source of the data is identified and the means for collecting the data are determined"},{"term":"data identification","definition":"The activity of data acquisition when the types of data to be used for training and predictions are identified"},{"term":"data imputation","definition":"The activity of data pre-processing when the missing values are replaced with estimated or guessed values"},{"term":"data labelling","definition":"The activity of adding meaningful tags to objects in raw data to support classification in ML"},{"term":"data pipeline","definition":"The implementation of data preparation activities to provide input data to support training by an ML algorithm or prediction by an ML model"},{"term":"data sampling","definition":"The activity of data pre-processing which involves selection of some part of the total available dataset so that patterns in the larger dataset can be observed"},{"term":"data transformation","definition":"The activity of data pre-processing when the format of the given data is changed"},{"term":"data visualisation","definition":"A technique for graphically representing data relationships, trends and patterns"},{"term":"feature extraction","definition":"The activity which involves the derivation of informative and non-redundant features\nfrom the existing features"},{"term":"feature selection","definition":"The activity which involves the selection of those features which are most likely to contribute to model training and prediction"},{"term":"RAM","definition":"A form of electronic computer memory that can be read and changed in any order, typically used to store working data and machine code"},{"term":"test dataset","definition":"A dataset used to test an ML model and evaluate the model developed from a training dataset"},{"term":"accuracy","definition":"The ML functional performance metric used to evaluate a classifier, which measures the proportion of predictions that were correct (After ISO/IEC TR 29119-11)"},{"term":"AUC","definition":"A measure of how well a classifier can distinguish between two classes"},{"term":"confusion matrix","definition":"A technique for summarising the ML functional performance of a classification algorithm"},{"term":"F1-score","definition":"An ML functional performance metric used to evaluate a classifier which provides a balance between recall and precision"},{"term":"FN","definition":"An ML model prediction in which the model mistakenly predicts the negative class"},{"term":"FP","definition":"An ML model prediction in which the model mistakenly predicts the positive class"},{"term":"FPR","definition":"The ratio between the number of negative events wrongly categorised as positive (false positives) and the total number of actual negative events"},{"term":"inter-cluster metric","definition":"A metric that measures the similarity of data points in different clusters"},{"term":"intra-cluster metric","definition":"A metric that measures the similarity of data points within a cluster"},{"term":"ML benchmark suite","definition":"A dataset used to compare ML models and ML algorithms over a range of evaluation metrics"},{"term":"ML functional performance metrics","definition":"A set of measures that relate to the functional correctness of an ML system"},{"term":"MSE","definition":"The statistical measure of the average squared difference between the estimated values and the actual value"},{"term":"precision","definition":"An ML functional performance metric used to evaluate a classifier, which measures the proportion of predicted positives that were correct (After ISO/IEC TR 29119-11)"},{"term":"R-squared","definition":"A statistical measure of how close the data points are to the fitted regression line"},{"term":"recall","definition":"An ML functional performance metric used to evaluate a classifier, which measures the proportion of actual positives that were predicted correctly (After ISO/IEC TR 29119-11)"},{"term":"regression model","definition":"An ML model whose expected output for a given numeric input is a continuous variable (After ISO/IEC DIS 23053)"},{"term":"ROC","definition":"Receiver operating characteristic"},{"term":"ROC curve","definition":"A graphical plot that illustrates the ability of a binary classifier as its discrimination threshold is varied"},{"term":"silhouette coefficient","definition":"A clustering measure between -1 and +1 based on the average inter-cluster and intra-cluster differences"},{"term":"TN","definition":"A prediction in which the model correctly predicts the negative class"},{"term":"TP","definition":"A prediction in which the model correctly predicts the positive class"},{"term":"TPR","definition":"An ML functional performance metric used to evaluate a classifier, which measures the proportion of actual positives that were predicted correctly (After ISO/IEC TR 29119-11)"},{"term":"activation value","definition":"The output of an activation function of a neuron in a neural network"},{"term":"learning rate","definition":"A small positive constant that determines the step size of the updates for the weights and bias in the perceptron model"},{"term":"linear classifier","definition":"A type of classifier that makes its predictions based on a linear combination of input features"},{"term":"MC/DC","definition":"The coverage of all outcomes of the atomic conditions that independently affect the overall decision outcome (ISTQB Glossary)"},{"term":"neural network","definition":"A network of primitive processing elements connected by weighted links with adjustable weights, in which each element produces a value\nby applying a nonlinear function to its input values, and transmits it to other elements or presents it as an output value (ISO/IEC 2382)"},{"term":"neuron","definition":"A node in a neural network, usually receiving multiple input values and generating an activation value"},{"term":"neuron coverage","definition":"The coverage of activated neurons in the neural network for a set of tests"},{"term":"perceptron","definition":"A neural network with just one layer and one neuron"},{"term":"sign-change coverage","definition":"The coverage of neurons activated with both positive and negative activation values in a neural network for a set of tests"},{"term":"sign-sign coverage","definition":"The coverage achieved if by changing the sign of each neuron it can be shown to individually cause one neuron in the next layer to change sign while all other neurons in the next layer do not change sign for a set of tests"},{"term":"synapse","definition":"A connection between two neurons"},{"term":"threshold coverage","definition":"The coverage of neurons exceeding a threshold activation value in a neural network for a set of tests"},{"term":"training data (for neural network)","definition":"A data used to train the neural network"},{"term":"value-change coverage","definition":"The coverage of neurons activated where their activation values differ by more than a change amount in the neural network for a set of tests"},{"term":"weight","definition":"An internal variable of a connection between neurons in a neural network that affects how it computes its outputs and that changes as the neural network is trained"},{"term":"automation bias","definition":"A type of bias caused by a person favoring the recommendations of an automated decision-making system over other sources"},{"term":"big data","definition":"Extensive datasets whose characteristics in terms of volume, variety, velocity and/or variability require specialised technologies and techniques to process"},{"term":"concept drift","definition":"A change in the perceived accuracy of an ML model predictions over time caused by changes in user expectations, behaviour and the operational environment"},{"term":"input data testing","definition":"A test level that focuses on the quality of the data used for training and prediction by ML models"},{"term":"ML functional performance","definition":"The degree to which an ML model meets ML functional performance criteria"},{"term":"test oracle problem","definition":"The challenge of determining whether a test has passed or failed for a given set of test inputs and state"},{"term":"training data","definition":"Data used to train an ML model"},{"term":"autonomous system","definition":"A system capable of working without human intervention for sustained periods"},{"term":"double-blind testing","definition":"A testing when neither the experts nor the evaluators of the outputs should know which ratings were automated"},{"term":"expert system","definition":"An AI-based system for solving problems in a particular domain or application area by drawing inferences from a knowledge base developed from human expertise"},{"term":"ground truth","definition":"The information provided by direct observation and measurement that is known to be real or true"},{"term":"LIME method","definition":"The Local Interpretable Model-Agnostic Explanations program for explaining the predictions from an ML model"},{"term":"model-agnostic method","definition":"A method that may be used for any ML model"},{"term":"ML training data","definition":"A data used to train an ML model"},{"term":"non-deterministic system","definition":"A system which will not always produce the same set of outputs and final state given a particular set of inputs and starting state"},{"term":"probabilistic system","definition":"A system whose behaviour is described in terms of probabilities; hence its outputs cannot be perfectly predicted"},{"term":"SUT","definition":"A type of test object that is a system"},{"term":"test oracle","definition":"A source to determine an expected result to compare with the actual result of the system under test"},{"term":"test suite","definition":"A set of test scripts or test procedures to be executed in a specific test run"},{"term":"A/B testing","definition":"A statistical testing approach to determine which of two components or systems performs better"},{"term":"adversarial attack","definition":"The deliberate use of adversarial examples to cause an ML model to fail"},{"term":"adversarial examples","definition":"Perturbed valid inputs that are passed to the trained model to cause it to provide incorrect predictions during the adversarial attack"},{"term":"adversarial testing","definition":"The test activity when adversarial examples are identified and added to the training data, making sure that the model learns to correctly recognise them"},{"term":"attacker","definition":"A person seeking to exploit potential vulnerabilities of a system"},{"term":"back-to-back testing","definition":"Testing to compare two or more variants of a test item or a simulation model of the same test item by executing the same test cases on all variants and comparing the results"},{"term":"data poisoning","definition":"The deliberate and malicious manipulation of training or input data to an ML model"},{"term":"error guessing","definition":"A test design technique where the experience of the tester is used to anticipate what defects might be present in the component or system under test as a result of errors made, and to design tests specifically to expose them"},{"term":"exhaustive testing","definition":"A test approach in which the test suite comprises all combinations of input values and preconditions"},{"term":"experience-based testing","definition":"Testing based on the tester's experience, knowledge and intuition"},{"term":"exploratory testing","definition":"An informal test design technique where the tester actively controls the design of the tests as those tests are performed and uses information gained while testing to design new and better tests"},{"term":"follow-up test case","definition":"A test case generated by applying a metamorphic relation to a source test case during metamorphic testing"},{"term":"MR","definition":"A description of how a change in the test inputs from the source test case to the follow-up test case affects a change in the expected outputs from the source test case to the follow-up test case"},{"term":"MT","definition":"A test technique in which the inputs and expected results are extrapolated from a passing test case using a metamorphic relation"},{"term":"neural network trojan","definition":"A vulnerability injected into a neural network using a data poisoning attack with the intent of exploiting it later"},{"term":"outlier","definition":"An observation that lies outside the overall pattern of the data distribution"},{"term":"pairwise testing","definition":"A test technique in which test cases are designed to execute all possible discrete combinations of each pair of input parameters"},{"term":"partial oracle","definition":"A test oracle that verifies only some aspects of the test output"},{"term":"pattern","definition":"A regularity in data or a systematic relationship between data points"},{"term":"pseudo-oracle","definition":"An independently derived variant of the test item used to generate results which are compared with the results of the original test item based on the same test"},{"term":"source test case","definition":"A test case that passed and is used as the basis of follow-up test cases in metamorphic testing"},{"term":"tour","definition":"A set of exploratory tests organised around a special focus"},{"term":"trend","definition":"An upwards or downwards shift in a data set over time"},{"term":"virtual test environment","definition":"A test environment in which one or more parts are digitally simulated"},{"term":"multi-agent system","definition":"A system that comprises multiple intelligent agents"},{"term":"test environment","definition":"A space where AI models and systems are evaluated, validated, and tested to ensure they meet the set standards before deployment"},{"term":"digital twin","definition":"An advanced continuous simulation of a physical entity"},{"term":"Bayesian techniques","definition":"A technique that considers before and after probability distributions as parameters of a statistical model"},{"term":"defect prediction","definition":"A technique to predict the areas within the test object in which defects will occur or the quantity of defects that are present"},{"term":"GUI","definition":"A type of interface that allows users to interact with a component or system through graphical icons and visual indicators"},{"term":"visual testing","definition":"Testing that uses image recognition to interact with GUI objects through the same interface as an actual user, and does not require access to the underlying code and interface definitions"},{"term":"weak AI","definition":"AI focused on a single well-defined task to address a specific problem (ISO/IEC TR 29119-11)"}];
const GENAI_GLOSSARY=[{"term":"A/B testing","definition":"A statistical testing approach to determine which of two components or systems performs better"},{"term":"acceptance criteria","definition":"The criteria that a work product must satisfy to be accepted by the stakeholders"},{"term":"AI chatbot","definition":"A conversational agent that uses LLMs to process queries and generate human-like text responses, enabling interactive communication with users"},{"term":"back-to-back testing","definition":"Testing to compare two or more variants of a test item or a simulation model of the same test item by executing the same test cases on all variants and comparing the results"},{"term":"context window","definition":"The span of text, measured in tokens, that a language model considers when generating responses, influencing the relevance and coherence of its outputs"},{"term":"deep learning","definition":"ML using neural networks with multiple layers"},{"term":"embedding","definition":"A technique used to represent tokens as dense vectors in a continuous space, learned during training to capture semantic, syntactic, and contextual relationships"},{"term":"feature","definition":"An individual measurable attribute of the input data used for training by an ML algorithm and for prediction by an ML model"},{"term":"foundation LLM","definition":"General-purpose models pre-trained on a wide range of text data, capable of predicting the next word based on learned linguistic patterns"},{"term":"GenAI","definition":"A type of artificial intelligence system that uses machine learning models to generate (new) intellectual content that resembles human-created content"},{"term":"GPT","definition":"A type of transformer-based deep learning model pre-trained on vast amounts of text data to understand and generate human-like text"},{"term":"ground truth","definition":"The information provided by direct observation and measurement that is known to be real or true"},{"term":"instruction-tuned LLM","definition":"A foundation LLM trained to follow instructions, often reinforced by feedback to encourage correct answers"},{"term":"LLM","definition":"A computer program that uses very large collections of language data in order to understand and produce text in a way that is similar to the way humans do"},{"term":"ML","definition":"The process using computational techniques to enable systems to learn from data or experience (ISO/IEC TR 29119-11)"},{"term":"metamorphic testing","definition":"A test technique in which the inputs and expected results are extrapolated from a passing test case using a metamorphic relation"},{"term":"multimodal model","definition":"GenAI model that is capable of processing and generating content across multiple data types, such as text, images, and audio"},{"term":"prompt","definition":"A natural language input provided to elicit specific response in Generative AI and large language models"},{"term":"reasoning LLM","definition":"An LLM building upon instruction-tuned models by refining their ability to emulate human-like reasoning processes"},{"term":"SLM","definition":"Language model that is intentionally designed and trained to be small, offering a balance between efficiency and task-specific language understanding"},{"term":"symbolic AI","definition":"An AI approach that uses symbols, rules, and structured knowledge to model reasoning"},{"term":"test data","definition":"Data needed for test execution"},{"term":"test case","definition":"A set of preconditions, inputs, actions (where applicable), expected results and postconditions, developed based on test conditions"},{"term":"test oracle","definition":"A source to determine an expected result to compare with the actual result of the system under test"},{"term":"test oracle problem","definition":"The challenge of determining whether a test has passed or failed for a given set of test inputs and state"},{"term":"test script","definition":"A sequence of instructions for the execution of a test"},{"term":"tokenization","definition":"The process of breaking down text into smaller units (tokens) for processing by language models"},{"term":"transformer","definition":"A deep learning model architecture that utilises self-attention mechanisms to capture long-range dependencies in input sequences"},{"term":"vision-language model","definition":"A GenAI system that jointly processes visual and textual data to perform tasks by linking and generating content across both modalities"},{"term":"few-shot prompting","definition":"A technique where a model is given a few examples within the prompt to guide it in generating appropriate responses"},{"term":"meta prompting","definition":"The crafting of higher-level instructions that generate specific prompts for exploring or automating capabilities"},{"term":"NLP","definition":"The processing of data encoded in natural language by computers to retrieve information and for knowledge representation"},{"term":"one-shot prompting","definition":"A prompt writing technique where the prompt contains one example to guide the LLM's response"},{"term":"prompt chaining","definition":"A prompting technique that involves using the output of one prompt as the input for another, creating a sequence of prompts"},{"term":"prompt engineering","definition":"The process of designing and refining input prompts to guide LLMs toward producing desired outputs"},{"term":"system prompt","definition":"A predefined instruction set, typically hidden from the chatbot’s users, that consistently establishes the context, tone, and boundaries for an LLM's responses and guides its behaviour throughout interactions"},{"term":"test condition","definition":"A testable aspect of a component or system identified as a basis for testing"},{"term":"test design","definition":"The activity that derives and specifies test cases from test conditions"},{"term":"test implementation","definition":"The activity that prepares the testware needed for test execution"},{"term":"test report","definition":"Documentation summarising testing and results"},{"term":"user prompt","definition":"An instruction or query entered by a user into a Large Language Model (LLM) that directs the model's response to fulfil specific tasks or provide desired information"},{"term":"zero-shot prompting","definition":"A prompt writing technique where the prompt contains no examples, relying on the model's pre-existing knowledge to generate a response"},{"term":"bias","definition":"The systematic difference in treatment of certain objects, people or groups in comparison to others (ISO/IEC DIS 22989)"},{"term":"data privacy","definition":"The protection of personally identifiable information or otherwise sensitive information from undesired disclosure"},{"term":"hallucination","definition":"Wrong information created by an LLM"},{"term":"reasoning error","definition":"Errors that occur when LLMs misinterpret logical structures, leading to incorrect conclusions"},{"term":"security","definition":"The degree to which a component or system protects its data and resources against unauthorised access or use and secures unobstructed access and use for its legitimate users"},{"term":"temperature","definition":"A parameter that controls the randomness or creativity of LLM's outputs"},{"term":"vulnerability","definition":"A weakness in a component, system, procedures, or controls that could allow for a successful security attack"},{"term":"fine-tuning","definition":"A supervised learning process using a dataset of labelled examples to update LLM weights and adapt them for specific tasks or domains"},{"term":"LLM-powered agent","definition":"An application that integrates LLM reasoning, decision-making, and memory, using tools to perform tasks"},{"term":"LLMOps","definition":"Practices and tools focused on deploying, monitoring, and maintaining LLMs in production environments"},{"term":"overfitting","definition":"The generation of an ML model that corresponds too closely to the training dataset, resulting in a model that finds it difficult to generalise to new data"},{"term":"RAG","definition":"A technique combining LLM capabilities with a retriever to fetch relevant data for generating accurate, contextually relevant responses"},{"term":"test infrastructure","definition":"The test environments, test tools, office environment and procedures needed to perform testing"},{"term":"vector database","definition":"A database optimised for storing and querying high-dimensional vector representations of data"},{"term":"shadow AI","definition":"The use of GenAI tools or systems within an organisation without formal approval or oversight"}];
